window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["1CH"]={"book":"1CH","editions":{"epo-londona":[[1,1,"Adam, Set, Enoŝ,","Adam, Set, Enoŝ,"],[1,2,"Kenan, Mahalalel, Jared,","Kenan, Mahalalel, Jared,"],[1,3,"Ĥanoĥ, Metuŝelaĥ, Lemeĥ,","Ĥanoĥ, Metuŝelaĥ, Lemeĥ,"],[1,4,"Noa, Ŝem, Ĥam, kaj Jafet.","Noa, Ŝem, Ĥam, kaj Jafet."],[1,5,"La filoj de Jafet: Gomer, Magog, Madaj, Javan, Tubal, Meŝeĥ, kaj Tiras.","La filoj de Jafet: Gomer, Magog, Madaj, Javan, Tubal, Meŝeĥ, kaj Tiras."],[1,6,"La filoj de Gomer: Aŝkenaz, Rifat, kaj Togarma.","La filoj de Gomer: Aŝkenaz, Rifat, kaj Togarma."],[1,7,"La filoj de Javan: Eliŝa, Tarŝiŝ, Kitim, kaj Dodanim.","La filoj de Javan: Eliŝa, Tarŝiŝ, Kitim, kaj Dodanim."],[1,8,"La filoj de Ĥam: Kuŝ, Micraim, Put, kaj Kanaan.","La filoj de Ĥam: Kuŝ, Micraim, Put, kaj Kanaan."],[1,9,"La filoj de Kuŝ: Seba, Ĥavila, Sabta, Raama, kaj Sabteĥa. La filoj de Raama: Ŝeba kaj Dedan.","La filoj de Kuŝ: Seba, Ĥavila, Sabta, Raama, kaj Sabteĥa. La filoj de Raama: Ŝeba kaj Dedan."],[1,10,"Kuŝ naskigis ankaŭ Nimrodon; ĉi tiu komencis esti potenculo sur la tero.","Kuŝ naskigis ankaŭ Nimrodon; ĉi tiu komencis esti potenculo sur la tero."],[1,11,"Micraim naskigis la Ludidojn, la Anamidojn, la Lehabidojn, la Naftuĥidojn,","Micraim naskigis la Ludidojn, la Anamidojn, la Lehabidojn, la Naftuĥidojn,"],[1,12,"la Patrusidojn, la Kasluĥidojn (de kiuj devenis la Filiŝtoj), kaj la Kaftoridojn.","la Patrusidojn, la Kasluĥidojn (de kiuj devenis la Filiŝtoj), kaj la Kaftoridojn."],[1,13,"De Kanaan naskiĝis Cidon, lia unuenaskito, kaj Ĥet,","De Kanaan naskiĝis Cidon, lia unuenaskito, kaj Ĥet,"],[1,14,"la Jebusidoj, la Amoridoj, la Girgaŝidoj,","la Jebusidoj, la Amoridoj, la Girgaŝidoj,"],[1,15,"la Ĥividoj, la Arkidoj, la Sinidoj,","la Ĥividoj, la Arkidoj, la Sinidoj,"],[1,16,"la Arvadidoj, la Cemaridoj, la Ĥamatidoj.","la Arvadidoj, la Cemaridoj, la Ĥamatidoj."],[1,17,"La filoj de Ŝem: Elam, Aŝur, Arpaĥŝad, Lud, Aram, Uc, Ĥul, Geter, kaj Meŝeĥ.","La filoj de Ŝem: Elam, Aŝur, Arpaĥŝad, Lud, Aram, Uc, Ĥul, Geter, kaj Meŝeĥ."],[1,18,"De Arpaĥŝad naskiĝis Ŝelaĥ, de Ŝelaĥ naskiĝis Eber.","De Arpaĥŝad naskiĝis Ŝelaĥ, de Ŝelaĥ naskiĝis Eber."],[1,19,"Al Eber naskiĝis du filoj: la nomo de unu estis Peleg, ĉar en lia tempo estis dividita la tero; la nomo de lia frato estis Joktan.","Al Eber naskiĝis du filoj: la nomo de unu estis Peleg, ĉar en lia tempo estis dividita la tero; la nomo de lia frato estis Joktan."],[1,20,"De Joktan naskiĝis Almodad, Ŝelef, Ĥacarmavet, Jeraĥ,","De Joktan naskiĝis Almodad, Ŝelef, Ĥacarmavet, Jeraĥ,"],[1,21,"Hadoram, Uzal, Dikla,","Hadoram, Uzal, Dikla,"],[1,22,"Ebal, Abimael, Ŝeba,","Ebal, Abimael, Ŝeba,"],[1,23,"Ofir, Ĥavila, kaj Jobab. Ĉiuj ĉi tiuj estis la filoj de Joktan.","Ofir, Ĥavila, kaj Jobab. Ĉiuj ĉi tiuj estis la filoj de Joktan."],[1,24,"Ŝem, Arpaĥŝad, Ŝelaĥ,","Ŝem, Arpaĥŝad, Ŝelaĥ,"],[1,25,"Eber, Peleg, Reu,","Eber, Peleg, Reu,"],[1,26,"Serug, Naĥor, Teraĥ,","Serug, Naĥor, Teraĥ,"],[1,27,"Abram (tio estas Abraham).","Abram (tio estas Abraham)."],[1,28,"La filoj de Abraham: Isaak kaj Iŝmael.","La filoj de Abraham: Isaak kaj Iŝmael."],[1,29,"Jen estas ilia genealogio: de Iŝmael, la unuenaskito Nebajot, poste Kedar, Adbeel, Mibsam,","Jen estas ilia genealogio: de Iŝmael, la unuenaskito Nebajot, poste Kedar, Adbeel, Mibsam,"],[1,30,"Miŝma, Duma, Masa, Ĥadad, Tema,","Miŝma, Duma, Masa, Ĥadad, Tema,"],[1,31,"Jetur, Nafiŝ, kaj Kedma. Tio estas la filoj de Iŝmael.","Jetur, Nafiŝ, kaj Kedma. Tio estas la filoj de Iŝmael."],[1,32,"La filoj de Ketura, kromvirino de Abraham, kiujn ŝi naskis: Zimran, Jokŝan, Medan, Midjan, Jiŝbak, kaj Ŝuaĥ. Kaj la filoj de Jokŝan estis Ŝeba kaj Dedan.","La filoj de Ketura, kromvirino de Abraham, kiujn ŝi naskis: Zimran, Jokŝan, Medan, Midjan, Jiŝbak, kaj Ŝuaĥ. Kaj la filoj de Jokŝan estis Ŝeba kaj Dedan."],[1,33,"La filoj de Midjan: Efa, Efer, Ĥanoĥ, Abida, kaj Eldaa. Ĉiuj ĉi tiuj estis la filoj de Ketura.","La filoj de Midjan: Efa, Efer, Ĥanoĥ, Abida, kaj Eldaa. Ĉiuj ĉi tiuj estis la filoj de Ketura."],[1,34,"Abraham naskigis Isaakon. La filoj de Isaak: Esav kaj Izrael.","Abraham naskigis Isaakon. La filoj de Isaak: Esav kaj Izrael."],[1,35,"La filoj de Esav: Elifaz, Reuel, Jeuŝ, Jalam, kaj Koraĥ.","La filoj de Esav: Elifaz, Reuel, Jeuŝ, Jalam, kaj Koraĥ."],[1,36,"La filoj de Elifaz: Teman, Omar, Cefi, Gatam, Kenaz, Timna, kaj Amalek.","La filoj de Elifaz: Teman, Omar, Cefi, Gatam, Kenaz, Timna, kaj Amalek."],[1,37,"La filoj de Reuel: Naĥat, Zeraĥ, Ŝama, kaj Miza.","La filoj de Reuel: Naĥat, Zeraĥ, Ŝama, kaj Miza."],[1,38,"La filoj de Seir: Lotan, Ŝobal, Cibeon, Ana, Diŝon, Ecer, kaj Diŝan.","La filoj de Seir: Lotan, Ŝobal, Cibeon, Ana, Diŝon, Ecer, kaj Diŝan."],[1,39,"La filoj de Lotan: Ĥori kaj Homam; la fratino de Lotan estis Timna.","La filoj de Lotan: Ĥori kaj Homam; la fratino de Lotan estis Timna."],[1,40,"La filoj de Ŝobal: Aljan, Manaĥat, Ebal, Ŝefi, kaj Onam. La filoj de Cibeon: Aja kaj Ana.","La filoj de Ŝobal: Aljan, Manaĥat, Ebal, Ŝefi, kaj Onam. La filoj de Cibeon: Aja kaj Ana."],[1,41,"La filoj de Ana: Diŝon. La filoj de Diŝon: Ĥamran, Eŝban, Jitran, kaj Keran.","La filoj de Ana: Diŝon. La filoj de Diŝon: Ĥamran, Eŝban, Jitran, kaj Keran."],[1,42,"La filoj de Ecer: Bilhan, Zaavan, kaj Jaakan. La filoj de Diŝan: Uc kaj Aran.","La filoj de Ecer: Bilhan, Zaavan, kaj Jaakan. La filoj de Diŝan: Uc kaj Aran."],[1,43,"Jen estas la reĝoj, kiuj reĝis en la lando de Edom, antaŭ ol aperis reĝo ĉe la Izraelidoj: Bela, filo de Beor; la nomo de lia urbo estis Dinhaba.","Jen estas la reĝoj, kiuj reĝis en la lando de Edom, antaŭ ol aperis reĝo ĉe la Izraelidoj: Bela, filo de Beor; la nomo de lia urbo estis Dinhaba."],[1,44,"Kaj Bela mortis, kaj anstataŭ li ekreĝis Jobab, filo de Zeraĥ, el Bocra.","Kaj Bela mortis, kaj anstataŭ li ekreĝis Jobab, filo de Zeraĥ, el Bocra."],[1,45,"Kaj Joab mortis, kaj anstataŭ li ekreĝis Ĥuŝam, el la lando de la Temanidoj.","Kaj Joab mortis, kaj anstataŭ li ekreĝis Ĥuŝam, el la lando de la Temanidoj."],[1,46,"Kaj Ĥuŝam mortis, kaj anstataŭ li ekreĝis Hadad, filo de Bedad, kiu venkobatis la Midjanidojn sur la kampo de Moab; la nomo de lia urbo estis Avit.","Kaj Ĥuŝam mortis, kaj anstataŭ li ekreĝis Hadad, filo de Bedad, kiu venkobatis la Midjanidojn sur la kampo de Moab; la nomo de lia urbo estis Avit."],[1,47,"Kaj Hadad mortis, kaj anstataŭ li ekreĝis Samla el Masreka.","Kaj Hadad mortis, kaj anstataŭ li ekreĝis Samla el Masreka."],[1,48,"Kaj Samla mortis, kaj anstataŭ li ekreĝis Ŝaul el Reĥobot ĉe la Rivero.","Kaj Samla mortis, kaj anstataŭ li ekreĝis Ŝaul el Reĥobot ĉe la Rivero."],[1,49,"Kaj Ŝaul mortis, kaj anstataŭ li ekreĝis Baal-Ĥanan, filo de Aĥbor.","Kaj Ŝaul mortis, kaj anstataŭ li ekreĝis Baal-Ĥanan, filo de Aĥbor."],[1,50,"Kaj Baal-Ĥanan mortis, kaj anstataŭ li ekreĝis Hadad; la nomo de lia urbo estis Pai; la nomo de lia edzino estis Mehetabel, filino de Matred, filino de Me-Zahab.","Kaj Baal-Ĥanan mortis, kaj anstataŭ li ekreĝis Hadad; la nomo de lia urbo estis Pai; la nomo de lia edzino estis Mehetabel, filino de Matred, filino de Me-Zahab."],[1,51,"Kaj Hadad mortis. Tiam la ĉefoj de Edom estis: ĉefo Timna, ĉefo Alva, ĉefo Jetet,","Kaj Hadad mortis. Tiam la ĉefoj de Edom estis: ĉefo Timna, ĉefo Alva, ĉefo Jetet,"],[1,52,"ĉefo Oholibama, ĉefo Ela, ĉefo Pinon,","ĉefo Oholibama, ĉefo Ela, ĉefo Pinon,"],[1,53,"ĉefo Kenaz, ĉefo Teman, ĉefo Mibcar,","ĉefo Kenaz, ĉefo Teman, ĉefo Mibcar,"],[1,54,"ĉefo Magdiel, ĉefo Iram. Tio estas la ĉefoj de Edom.","ĉefo Magdiel, ĉefo Iram. Tio estas la ĉefoj de Edom."],[2,1,"Jen estas la filoj de Izrael: Ruben, Simeon, Levi, Jehuda, Isaĥar, Zebulun,","Jen estas la filoj de Izrael: Ruben, Simeon, Levi, Jehuda, Isaĥar, Zebulun,"],[2,2,"Dan, Jozef, Benjamen, Naftali, Gad, kaj Aŝer.","Dan, Jozef, Benjamen, Naftali, Gad, kaj Aŝer."],[2,3,"La filoj de Jehuda: Er, Onan, kaj Ŝela, tri naskiĝis al li de Bat-Ŝua, la Kanaanidino. Er, la unuenaskito de Jehuda, estis malbona antaŭ la Eternulo, kaj Li mortigis lin.","La filoj de Jehuda: Er, Onan, kaj Ŝela, tri naskiĝis al li de Bat-Ŝua, la Kanaanidino. Er, la unuenaskito de Jehuda, estis malbona antaŭ la Eternulo, kaj Li mortigis lin."],[2,4,"Kaj lia bofilino Tamar naskis al li Perecon kaj Zeraĥon. La nombro de ĉiuj filoj de Jehuda estis kvin.","Kaj lia bofilino Tamar naskis al li Perecon kaj Zeraĥon. La nombro de ĉiuj filoj de Jehuda estis kvin."],[2,5,"La filoj de Perec: Ĥecron kaj Ĥamul.","La filoj de Perec: Ĥecron kaj Ĥamul."],[2,6,"La filoj de Zeraĥ: Zimri, Etan, Heman, Kalkol, kaj Dara; da ili ĉiuj estis kvin.","La filoj de Zeraĥ: Zimri, Etan, Heman, Kalkol, kaj Dara; da ili ĉiuj estis kvin."],[2,7,"La filoj de Karmi: Aĥan, kiu malĝojigis Izraelon, pekinte kontraŭ anatemaĵo.","La filoj de Karmi: Aĥan, kiu malĝojigis Izraelon, pekinte kontraŭ anatemaĵo."],[2,8,"La filoj de Etan: Azarja.","La filoj de Etan: Azarja."],[2,9,"La filoj de Ĥecron, kiuj naskiĝis al li: Jeraĥmeel, Ram, kaj Kelubaj.","La filoj de Ĥecron, kiuj naskiĝis al li: Jeraĥmeel, Ram, kaj Kelubaj."],[2,10,"Ram naskigis Aminadabon; Aminadab naskigis Naĥŝonon, princon de la idoj de Jehuda;","Ram naskigis Aminadabon; Aminadab naskigis Naĥŝonon, princon de la idoj de Jehuda;"],[2,11,"Naĥŝon naskigis Salman; Salma naskigis Boazon;","Naĥŝon naskigis Salman; Salma naskigis Boazon;"],[2,12,"Boaz naskigis Obedon; Obed naskigis Jiŝajon;","Boaz naskigis Obedon; Obed naskigis Jiŝajon;"],[2,13,"Jiŝaj naskigis sian unuenaskiton Eliab, la dua estis Abinadab, la tria estis Ŝimea,","Jiŝaj naskigis sian unuenaskiton Eliab, la dua estis Abinadab, la tria estis Ŝimea,"],[2,14,"la kvara estis Netanel, la kvina estis Radaj,","la kvara estis Netanel, la kvina estis Radaj,"],[2,15,"la sesa estis Ocem, la sepa estis David.","la sesa estis Ocem, la sepa estis David."],[2,16,"Iliaj fratinoj estis: Ceruja kaj Abigail. La filoj de Ceruja estis: Abiŝaj, Joab, kaj Asahel — tri.","Iliaj fratinoj estis: Ceruja kaj Abigail. La filoj de Ceruja estis: Abiŝaj, Joab, kaj Asahel — tri."],[2,17,"Abigail naskis Amasan; la patro de Amasa estis Jeter, Iŝmaelido.","Abigail naskis Amasan; la patro de Amasa estis Jeter, Iŝmaelido."],[2,18,"Kaleb, filo de Ĥecron, naskigis de sia edzino Azuba kaj de Jeriot; jen estas ŝiaj filoj: Jeŝer, Ŝobab, kaj Ardon.","Kaleb, filo de Ĥecron, naskigis de sia edzino Azuba kaj de Jeriot; jen estas ŝiaj filoj: Jeŝer, Ŝobab, kaj Ardon."],[2,19,"Kiam mortis Azuba, Kaleb prenis al si Efratan, kaj ŝi naskis al li Ĥuron.","Kiam mortis Azuba, Kaleb prenis al si Efratan, kaj ŝi naskis al li Ĥuron."],[2,20,"Ĥur naskigis Urin; kaj Uri naskigis Becalelon.","Ĥur naskigis Urin; kaj Uri naskigis Becalelon."],[2,21,"Poste Ĥecron envenis al la filino de Maĥir, patro de Gilead; li prenis ŝin, kiam li havis la aĝon de sesdek jaroj, kaj ŝi naskis al li Segubon.","Poste Ĥecron envenis al la filino de Maĥir, patro de Gilead; li prenis ŝin, kiam li havis la aĝon de sesdek jaroj, kaj ŝi naskis al li Segubon."],[2,22,"Segub naskigis Jairon, kaj li havis dudek tri urbojn en la lando Gilead.","Segub naskigis Jairon, kaj li havis dudek tri urbojn en la lando Gilead."],[2,23,"Sed la Geŝuranoj kaj Sirianoj forprenis de ili la Vilaĝojn de Jair, Kenaton kaj ĝiajn dependaĵojn, sesdek urbetojn. Ĉiuj ĉi tiuj estis la filoj de Maĥir, patro de Gilead.","Sed la Geŝuranoj kaj Sirianoj forprenis de ili la Vilaĝojn de Jair, Kenaton kaj ĝiajn dependaĵojn, sesdek urbetojn. Ĉiuj ĉi tiuj estis la filoj de Maĥir, patro de Gilead."],[2,24,"Post la morto de Ĥecron en Kaleb-Efrata la edzino de Ĥecron, Abija, naskis al li Aŝĥuron, la fondinton de Tekoa.","Post la morto de Ĥecron en Kaleb-Efrata la edzino de Ĥecron, Abija, naskis al li Aŝĥuron, la fondinton de Tekoa."],[2,25,"La filoj de Jeraĥmeel, unuenaskito de Ĥecron, estis: la unuenaskito Ram, poste Buna, Oren, Ocem, kaj Aĥija.","La filoj de Jeraĥmeel, unuenaskito de Ĥecron, estis: la unuenaskito Ram, poste Buna, Oren, Ocem, kaj Aĥija."],[2,26,"Jeraĥmeel havis ankaŭ alian edzinon, ŝia nomo estis Atara; ŝi estis la patrino de Onam.","Jeraĥmeel havis ankaŭ alian edzinon, ŝia nomo estis Atara; ŝi estis la patrino de Onam."],[2,27,"La filoj de Ram, la unuenaskito de Jeraĥmeel, estis: Maac, Jamin, kaj Eker.","La filoj de Ram, la unuenaskito de Jeraĥmeel, estis: Maac, Jamin, kaj Eker."],[2,28,"La filoj de Onam estis: Ŝamaj kaj Jada. La filoj de Ŝamaj estis: Nadab kaj Abiŝur.","La filoj de Onam estis: Ŝamaj kaj Jada. La filoj de Ŝamaj estis: Nadab kaj Abiŝur."],[2,29,"La nomo de la edzino de Abiŝur estis Abiĥail; ŝi naskis al li Aĥbanon kaj Molidon.","La nomo de la edzino de Abiŝur estis Abiĥail; ŝi naskis al li Aĥbanon kaj Molidon."],[2,30,"La filoj de Nadab estis: Seled kaj Apaim. Seled mortis sen infanoj.","La filoj de Nadab estis: Seled kaj Apaim. Seled mortis sen infanoj."],[2,31,"La filo de Apaim estis Jiŝei. La filo de Jiŝei estis Ŝeŝan. La filo de Ŝeŝan estis Aĥlaj.","La filo de Apaim estis Jiŝei. La filo de Jiŝei estis Ŝeŝan. La filo de Ŝeŝan estis Aĥlaj."],[2,32,"La filoj de Jada, frato de Ŝamaj, estis: Jeter kaj Jonatan. Jeter mortis sen infanoj.","La filoj de Jada, frato de Ŝamaj, estis: Jeter kaj Jonatan. Jeter mortis sen infanoj."],[2,33,"La filoj de Jonatan estis: Pelet kaj Zaza. Tio estis la idoj de Jeraĥmeel.","La filoj de Jonatan estis: Pelet kaj Zaza. Tio estis la idoj de Jeraĥmeel."],[2,34,"Ŝeŝan ne havis filojn, sed nur filinojn. Ŝeŝan havis sklavon Egipton, kies nomo estis Jarĥa;","Ŝeŝan ne havis filojn, sed nur filinojn. Ŝeŝan havis sklavon Egipton, kies nomo estis Jarĥa;"],[2,35,"kaj Ŝeŝan donis sian filinon kiel edzinon al sia sklavo Jarĥa, kaj ŝi naskis al li Atajon.","kaj Ŝeŝan donis sian filinon kiel edzinon al sia sklavo Jarĥa, kaj ŝi naskis al li Atajon."],[2,36,"Ataj naskigis Natanon; kaj Natan naskigis Zabadon.","Ataj naskigis Natanon; kaj Natan naskigis Zabadon."],[2,37,"Zabad naskigis Eflalon; kaj Eflal naskigis Obedon.","Zabad naskigis Eflalon; kaj Eflal naskigis Obedon."],[2,38,"Obed naskigis Jehun, kaj Jehu naskigis Azarjan.","Obed naskigis Jehun, kaj Jehu naskigis Azarjan."],[2,39,"Azarja naskigis Ĥelecon; kaj Ĥelec naskigis Eleasan.","Azarja naskigis Ĥelecon; kaj Ĥelec naskigis Eleasan."],[2,40,"Eleasa naskigis Sismajon; kaj Sismaj naskigis Ŝalumon.","Eleasa naskigis Sismajon; kaj Sismaj naskigis Ŝalumon."],[2,41,"Ŝalum naskigis Jekamjan; kaj Jekamja naskigis Eliŝaman.","Ŝalum naskigis Jekamjan; kaj Jekamja naskigis Eliŝaman."],[2,42,"La filoj de Kaleb, frato de Jeraĥmeel: lia unuenaskito Meŝa, kiu estis la fondinto de Zif; kaj la filoj de Mareŝa, fondinto de Ĥebron.","La filoj de Kaleb, frato de Jeraĥmeel: lia unuenaskito Meŝa, kiu estis la fondinto de Zif; kaj la filoj de Mareŝa, fondinto de Ĥebron."],[2,43,"La filoj de Ĥebron: Koraĥ, Tapuaĥ, Rekem, kaj Ŝema.","La filoj de Ĥebron: Koraĥ, Tapuaĥ, Rekem, kaj Ŝema."],[2,44,"Ŝema naskigis Raĥamon, fondinton de Jorkeam; kaj Rekem naskigis Ŝamajon.","Ŝema naskigis Raĥamon, fondinton de Jorkeam; kaj Rekem naskigis Ŝamajon."],[2,45,"La filo de Ŝamaj estis Maon; kaj Maon estis la fondinto de Bet-Cur.","La filo de Ŝamaj estis Maon; kaj Maon estis la fondinto de Bet-Cur."],[2,46,"Kaj Efa, kromvirino de Kaleb, naskis Ĥaranon, Mocan, kaj Gazezon; kaj Ĥaran naskigis Gazezon.","Kaj Efa, kromvirino de Kaleb, naskis Ĥaranon, Mocan, kaj Gazezon; kaj Ĥaran naskigis Gazezon."],[2,47,"La filoj de Jedaj estis: Regem, Jotam, Geŝan, Pelet, Efa, kaj Ŝaaf.","La filoj de Jedaj estis: Regem, Jotam, Geŝan, Pelet, Efa, kaj Ŝaaf."],[2,48,"Maaĥa, kromvirino de Kaleb, naskis Ŝeberon kaj Tirĥanan.","Maaĥa, kromvirino de Kaleb, naskis Ŝeberon kaj Tirĥanan."],[2,49,"Ŝi naskis ankaŭ Ŝaafon, la fondinton de Madmana, Ŝevan, la fondinton de Maĥbena kaj la fondinton de Gibea. La filino de Kaleb estis Aĥsa.","Ŝi naskis ankaŭ Ŝaafon, la fondinton de Madmana, Ŝevan, la fondinton de Maĥbena kaj la fondinton de Gibea. La filino de Kaleb estis Aĥsa."],[2,50,"Tio estis la idoj de Kaleb: la filo de Ĥur, unuenaskito de Efrata: Ŝobal, fondinto de Kirjat-Jearim,","Tio estis la idoj de Kaleb: la filo de Ĥur, unuenaskito de Efrata: Ŝobal, fondinto de Kirjat-Jearim,"],[2,51,"Salma, fondinto de Bet-Leĥem, Ĥaref, fondinto de Bet-Gader.","Salma, fondinto de Bet-Leĥem, Ĥaref, fondinto de Bet-Gader."],[2,52,"Ŝobal, fondinto de Kirjat-Jearim, havis la filojn: Haroe, duono de la Menuĥot.","Ŝobal, fondinto de Kirjat-Jearim, havis la filojn: Haroe, duono de la Menuĥot."],[2,53,"La familioj de Kirjat-Jearim estis: la Jetridoj, la Putidoj, la Ŝumatidoj, la Miŝraidoj. De ĉi tiuj devenis la Coreaidoj kaj la Eŝtaolidoj.","La familioj de Kirjat-Jearim estis: la Jetridoj, la Putidoj, la Ŝumatidoj, la Miŝraidoj. De ĉi tiuj devenis la Coreaidoj kaj la Eŝtaolidoj."],[2,54,"La idoj de Salma: la Bet-Leĥemanoj, la Netofaanoj, la Atrotanoj de la domo de Joab, la duono de la Manaĥatanoj, la Coreanoj;","La idoj de Salma: la Bet-Leĥemanoj, la Netofaanoj, la Atrotanoj de la domo de Joab, la duono de la Manaĥatanoj, la Coreanoj;"],[2,55,"kaj la familioj de la skribistoj, kiuj loĝis en Jabec, la Tiratidoj, Ŝimeatidoj, kaj Suĥatidoj; tio estis la Kenidoj, kiuj devenis de Ĥamat, la fondinto de Bet-Reĥab.","kaj la familioj de la skribistoj, kiuj loĝis en Jabec, la Tiratidoj, Ŝimeatidoj, kaj Suĥatidoj; tio estis la Kenidoj, kiuj devenis de Ĥamat, la fondinto de Bet-Reĥab."],[3,1,"Jen estas la filoj de David, kiuj naskiĝis al li en Ĥebron: la unuenaskito Amnon, de la Jizreelanino Aĥinoam; la dua estis Daniel, de la Karmelanino Abigail;","Jen estas la filoj de David, kiuj naskiĝis al li en Ĥebron: la unuenaskito Amnon, de la Jizreelanino Aĥinoam; la dua estis Daniel, de la Karmelanino Abigail;"],[3,2,"la tria estis Abŝalom, filo de Maaĥa, filino de Talmaj, reĝo de Geŝur; la kvara estis Adonija, filo de Ĥagit;","la tria estis Abŝalom, filo de Maaĥa, filino de Talmaj, reĝo de Geŝur; la kvara estis Adonija, filo de Ĥagit;"],[3,3,"la kvina estis Ŝefatja, de Abital; la sesa estis Jitream, de lia edzino Egla;","la kvina estis Ŝefatja, de Abital; la sesa estis Jitream, de lia edzino Egla;"],[3,4,"ses naskiĝis al li en Ĥebron. Li reĝis tie sep jarojn kaj ses monatojn; kaj tridek tri jarojn li reĝis en Jerusalem.","ses naskiĝis al li en Ĥebron. Li reĝis tie sep jarojn kaj ses monatojn; kaj tridek tri jarojn li reĝis en Jerusalem."],[3,5,"Kaj jen estas tiuj, kiuj naskiĝis al li en Jerusalem: Ŝimea, Ŝobab, Natan, Salomono — ĉi tiuj kvar de Bat-Ŝua, filino de Amiel;","Kaj jen estas tiuj, kiuj naskiĝis al li en Jerusalem: Ŝimea, Ŝobab, Natan, Salomono — ĉi tiuj kvar de Bat-Ŝua, filino de Amiel;"],[3,6,"Jibĥar, Eliŝama, Elifelet,","Jibĥar, Eliŝama, Elifelet,"],[3,7,"Noga, Nefeg, Jafia,","Noga, Nefeg, Jafia,"],[3,8,"Eliŝama, Eljada, kaj Elifelet — naŭ.","Eliŝama, Eljada, kaj Elifelet — naŭ."],[3,9,"Tio estas ĉiuj filoj de David, krom la filoj de kromvirinoj; kaj ilia fratino estis Tamar.","Tio estas ĉiuj filoj de David, krom la filoj de kromvirinoj; kaj ilia fratino estis Tamar."],[3,10,"La filo de Salomono estis Reĥabeam; la filo de ĉi tiu estis Abija; la filo de ĉi tiu: Asa; la filo de ĉi tiu: Jehoŝafat;","La filo de Salomono estis Reĥabeam; la filo de ĉi tiu estis Abija; la filo de ĉi tiu: Asa; la filo de ĉi tiu: Jehoŝafat;"],[3,11,"la filo de ĉi tiu: Joram; la filo de ĉi tiu: Aĥazja; la filo de ĉi tiu: Joaŝ;","la filo de ĉi tiu: Joram; la filo de ĉi tiu: Aĥazja; la filo de ĉi tiu: Joaŝ;"],[3,12,"la filo de ĉi tiu: Amacja; la filo de ĉi tiu: Azarja; la filo de ĉi tiu: Jotam;","la filo de ĉi tiu: Amacja; la filo de ĉi tiu: Azarja; la filo de ĉi tiu: Jotam;"],[3,13,"la filo de ĉi tiu: Aĥaz; la filo de ĉi tiu: Ĥizkija; la filo de ĉi tiu: Manase;","la filo de ĉi tiu: Aĥaz; la filo de ĉi tiu: Ĥizkija; la filo de ĉi tiu: Manase;"],[3,14,"la filo de ĉi tiu: Amon; la filo de ĉi tiu: Joŝija.","la filo de ĉi tiu: Amon; la filo de ĉi tiu: Joŝija."],[3,15,"La filoj de Joŝija estis: la unuenaskito Joĥanan, la dua Jehojakim, la tria Cidkija, la kvara Ŝalum.","La filoj de Joŝija estis: la unuenaskito Joĥanan, la dua Jehojakim, la tria Cidkija, la kvara Ŝalum."],[3,16,"La filoj de Jehojakim: lia filo Jeĥonja, lia filo Cidkija.","La filoj de Jehojakim: lia filo Jeĥonja, lia filo Cidkija."],[3,17,"La filoj de Jeĥonja: Asir, lia filo Ŝealtiel,","La filoj de Jeĥonja: Asir, lia filo Ŝealtiel,"],[3,18,"Malkiram, Pedaja, Ŝenacar, Jekamja, Ĥoŝama, kaj Nedabja.","Malkiram, Pedaja, Ŝenacar, Jekamja, Ĥoŝama, kaj Nedabja."],[3,19,"La filoj de Pedaja: Zerubabel kaj Ŝimei. La filoj de Zerubabel: Meŝulam, Ĥananja; ilia fratino estis Ŝelomit;","La filoj de Pedaja: Zerubabel kaj Ŝimei. La filoj de Zerubabel: Meŝulam, Ĥananja; ilia fratino estis Ŝelomit;"],[3,20,"ankaŭ ĉi tiuj kvin: Ĥaŝuba, Ohel, Bereĥja, Ĥasadja, kaj Juŝab-Ĥesed.","ankaŭ ĉi tiuj kvin: Ĥaŝuba, Ohel, Bereĥja, Ĥasadja, kaj Juŝab-Ĥesed."],[3,21,"La idoj de Ĥananja: Pelatja kaj Jeŝaja; la filoj de Refaja, la filoj de Arnan, la filoj de Obadja, la filoj de Ŝeĥanja.","La idoj de Ĥananja: Pelatja kaj Jeŝaja; la filoj de Refaja, la filoj de Arnan, la filoj de Obadja, la filoj de Ŝeĥanja."],[3,22,"La filo de Ŝeĥanja estis Ŝemaja; la filoj de Ŝemaja: Ĥatuŝ, Jigal, Bariaĥ, Nearja, kaj Ŝafat — ses.","La filo de Ŝeĥanja estis Ŝemaja; la filoj de Ŝemaja: Ĥatuŝ, Jigal, Bariaĥ, Nearja, kaj Ŝafat — ses."],[3,23,"La filoj de Nearja: Eljoenaj, Ĥizkija, kaj Azrikam — tri.","La filoj de Nearja: Eljoenaj, Ĥizkija, kaj Azrikam — tri."],[3,24,"La filoj de Eljoenaj: Hodavja, Eljaŝib, Pelaja, Akub, Joĥanan, Delaja, kaj Anani — sep.","La filoj de Eljoenaj: Hodavja, Eljaŝib, Pelaja, Akub, Joĥanan, Delaja, kaj Anani — sep."],[4,1,"La filoj de Jehuda estis: Perec, Ĥecron, Karmi, Ĥur, kaj Ŝobal.","La filoj de Jehuda estis: Perec, Ĥecron, Karmi, Ĥur, kaj Ŝobal."],[4,2,"Reaja, filo de Ŝobal, naskigis Jaĥaton; Jaĥat naskigis Aĥumajon kaj Lahadon; tio estas la familioj de la Coreaidoj.","Reaja, filo de Ŝobal, naskigis Jaĥaton; Jaĥat naskigis Aĥumajon kaj Lahadon; tio estas la familioj de la Coreaidoj."],[4,3,"Kaj jen estas la domanaro de Etam: Jizreel, Jiŝma, Jidbaŝ; la nomo de ilia fratino estis Haclelponi;","Kaj jen estas la domanaro de Etam: Jizreel, Jiŝma, Jidbaŝ; la nomo de ilia fratino estis Haclelponi;"],[4,4,"kaj Penuel, la fondinto de Gedor, kaj Ezer, la fondinto de Ĥuŝa. Tio estas la idoj de Ĥur, unuenaskito de Efrata, posedanto de Bet-Leĥem.","kaj Penuel, la fondinto de Gedor, kaj Ezer, la fondinto de Ĥuŝa. Tio estas la idoj de Ĥur, unuenaskito de Efrata, posedanto de Bet-Leĥem."],[4,5,"Aŝĥur, fondinto de Tekoa, havis du edzinojn: Ĥela kaj Naara.","Aŝĥur, fondinto de Tekoa, havis du edzinojn: Ĥela kaj Naara."],[4,6,"Naara naskis al li Aĥuzamon, Ĥeferon, Temnin, kaj Aĥaŝtarin; tio estas la filoj de Naara;","Naara naskis al li Aĥuzamon, Ĥeferon, Temnin, kaj Aĥaŝtarin; tio estas la filoj de Naara;"],[4,7,"la filoj de Ĥela estis: Ceret, Coĥar, kaj Etnan.","la filoj de Ĥela estis: Ceret, Coĥar, kaj Etnan."],[4,8,"Koc naskigis Anubon, Cobeban, kaj la familiojn de Aĥarĥel, filo de Harum.","Koc naskigis Anubon, Cobeban, kaj la familiojn de Aĥarĥel, filo de Harum."],[4,9,"Jabec estis la plej estimata inter siaj fratoj. Lia patrino donis al li la nomon Jabec, ĉar ŝi diris: En malĝojo mi naskis.","Jabec estis la plej estimata inter siaj fratoj. Lia patrino donis al li la nomon Jabec, ĉar ŝi diris: En malĝojo mi naskis."],[4,10,"Kaj Jabec vokis al Dio de Izrael, dirante: Ho, se Vi min benus kaj vastigus miajn limojn, kaj Via mano estus kun mi kaj forigus la malbonon, por ke mi ne havu aflikton! Kaj Dio plenumis tion, pri kio li petis.","Kaj Jabec vokis al Dio de Izrael, dirante: Ho, se Vi min benus kaj vastigus miajn limojn, kaj Via mano estus kun mi kaj forigus la malbonon, por ke mi ne havu aflikton! Kaj Dio plenumis tion, pri kio li petis."],[4,11,"Kelub, frato de Ŝuĥa, naskigis Meĥiron; ĉi tiu estis la patro de Eŝton.","Kelub, frato de Ŝuĥa, naskigis Meĥiron; ĉi tiu estis la patro de Eŝton."],[4,12,"Eŝton naskigis Bet-Rafan, Paseaĥon, kaj Teĥinan, fondinton de la urbo Naĥaŝ; tio estas la loĝantoj de Reĥa.","Eŝton naskigis Bet-Rafan, Paseaĥon, kaj Teĥinan, fondinton de la urbo Naĥaŝ; tio estas la loĝantoj de Reĥa."],[4,13,"La filoj de Kenaz estis: Otniel kaj Seraja; la filo de Otniel estis Ĥatat.","La filoj de Kenaz estis: Otniel kaj Seraja; la filo de Otniel estis Ĥatat."],[4,14,"Meonotaj naskigis Ofran, kaj Seraja naskigis Joabon, fondinton de la Valo de Ĉarpentistoj; ĉar ili estis ĉarpentistoj.","Meonotaj naskigis Ofran, kaj Seraja naskigis Joabon, fondinton de la Valo de Ĉarpentistoj; ĉar ili estis ĉarpentistoj."],[4,15,"La filoj de Kaleb, filo de Jefune: Iru, Ela, kaj Naam; la filo de Ela estis Kenaz.","La filoj de Kaleb, filo de Jefune: Iru, Ela, kaj Naam; la filo de Ela estis Kenaz."],[4,16,"La filoj de Jehalelel: Zif, Zifa, Tirja, kaj Asarel.","La filoj de Jehalelel: Zif, Zifa, Tirja, kaj Asarel."],[4,17,"La filoj de Ezra: Jeter, Mered, Efer, kaj Jalon. Ŝi naskis Mirjamon, Ŝamajon, kaj Jiŝbaĥon, la patron de Eŝtemoa;","La filoj de Ezra: Jeter, Mered, Efer, kaj Jalon. Ŝi naskis Mirjamon, Ŝamajon, kaj Jiŝbaĥon, la patron de Eŝtemoa;"],[4,18,"dum lia edzino la Judino naskis Jeredon, fondinton de Gedor, Ĥeberon, fondinton de Soĥo, kaj Jekutielon, fondinton de Zanoaĥ. Tiuj estis la filoj de Bitja, filino de Faraono, kiun prenis Mered.","dum lia edzino la Judino naskis Jeredon, fondinton de Gedor, Ĥeberon, fondinton de Soĥo, kaj Jekutielon, fondinton de Zanoaĥ. Tiuj estis la filoj de Bitja, filino de Faraono, kiun prenis Mered."],[4,19,"La filoj de la edzino de Hodija, fratino de Naĥam: la patro de Keila, la Garmano, kaj Eŝtemoa, la Maaĥatano.","La filoj de la edzino de Hodija, fratino de Naĥam: la patro de Keila, la Garmano, kaj Eŝtemoa, la Maaĥatano."],[4,20,"La filoj de Ŝimon: Amnon, Rina, Ben-Ĥanan, kaj Tilon; la filoj de Jiŝei: Zoĥet kaj Ben-Zoĥet.","La filoj de Ŝimon: Amnon, Rina, Ben-Ĥanan, kaj Tilon; la filoj de Jiŝei: Zoĥet kaj Ben-Zoĥet."],[4,21,"La filoj de Ŝela, filo de Jehuda: Er, patro de Leĥa, kaj Lada, patro de Mareŝa, kaj la familioj de la tolfaristoj el la domo de Aŝbea;","La filoj de Ŝela, filo de Jehuda: Er, patro de Leĥa, kaj Lada, patro de Mareŝa, kaj la familioj de la tolfaristoj el la domo de Aŝbea;"],[4,22,"kaj Jokim, kaj la loĝantoj de Kozeba, kaj Joaŝ, kaj Saraf, kiuj estis sinjoroj en Moab kaj poste revenis en Bet-Leĥemon, laŭ antikvaj rakontoj.","kaj Jokim, kaj la loĝantoj de Kozeba, kaj Joaŝ, kaj Saraf, kiuj estis sinjoroj en Moab kaj poste revenis en Bet-Leĥemon, laŭ antikvaj rakontoj."],[4,23,"Ili estis potistoj, kaj loĝis inter ĝardenoj kaj brutejoj; ĉe la reĝo ili tie loĝis por liaj laboroj.","Ili estis potistoj, kaj loĝis inter ĝardenoj kaj brutejoj; ĉe la reĝo ili tie loĝis por liaj laboroj."],[4,24,"La filoj de Simeon: Nemuel, Jamin, Jarib, Zeraĥ, kaj Ŝaul.","La filoj de Simeon: Nemuel, Jamin, Jarib, Zeraĥ, kaj Ŝaul."],[4,25,"La filo de ĉi tiu estis Ŝalum; la filo de ĉi tiu estis Mibsam; la filo de ĉi tiu estis Miŝma.","La filo de ĉi tiu estis Ŝalum; la filo de ĉi tiu estis Mibsam; la filo de ĉi tiu estis Miŝma."],[4,26,"La filoj de Miŝma: lia filo Ĥamuel, lia filo Zakur, lia filo Ŝimei.","La filoj de Miŝma: lia filo Ĥamuel, lia filo Zakur, lia filo Ŝimei."],[4,27,"Ŝimei havis dek ses filojn kaj ses filinojn; sed liaj fratoj ne havis multe da filoj, kaj ilia tuta parencaro ne tiel multiĝis, kiel la idaro de Jehuda.","Ŝimei havis dek ses filojn kaj ses filinojn; sed liaj fratoj ne havis multe da filoj, kaj ilia tuta parencaro ne tiel multiĝis, kiel la idaro de Jehuda."],[4,28,"Ili loĝis en Beer-Ŝeba, Molada, kaj Ĥacar-Ŝual,","Ili loĝis en Beer-Ŝeba, Molada, kaj Ĥacar-Ŝual,"],[4,29,"en Bilha, Ecem, kaj Tolad,","en Bilha, Ecem, kaj Tolad,"],[4,30,"en Betuel, Ĥorma, kaj Ciklag,","en Betuel, Ĥorma, kaj Ciklag,"],[4,31,"en Bet-Markabot, Ĥacar-Susim, Bet-Biri, kaj Ŝaaraim. Tio estis iliaj urboj ĝis la reĝado de David.","en Bet-Markabot, Ĥacar-Susim, Bet-Biri, kaj Ŝaaraim. Tio estis iliaj urboj ĝis la reĝado de David."],[4,32,"Iliaj vilaĝoj estis: Etam, Ain, Rimon, Toĥen, kaj Aŝan, kvin urboj;","Iliaj vilaĝoj estis: Etam, Ain, Rimon, Toĥen, kaj Aŝan, kvin urboj;"],[4,33,"kaj ĉiuj iliaj vilaĝoj, kiuj estis ĉirkaŭ tiuj urboj, ĝis Baal. Tie estis ilia loĝloko, kaj ili havis apartan genealogian registron.","kaj ĉiuj iliaj vilaĝoj, kiuj estis ĉirkaŭ tiuj urboj, ĝis Baal. Tie estis ilia loĝloko, kaj ili havis apartan genealogian registron."],[4,34,"Kaj Meŝobab, Jamleĥ, Joŝa, filo de Amacja,","Kaj Meŝobab, Jamleĥ, Joŝa, filo de Amacja,"],[4,35,"Joel, Jehu, filo de Joŝibja, filo de Seraja, filo de Asiel,","Joel, Jehu, filo de Joŝibja, filo de Seraja, filo de Asiel,"],[4,36,"Eljoenaj, Jaakoba, Jeŝoĥaja, Asaja, Adiel, Jesimiel, Benaja,","Eljoenaj, Jaakoba, Jeŝoĥaja, Asaja, Adiel, Jesimiel, Benaja,"],[4,37,"Ziza, filo de Ŝifi, filo de Alon, filo de Jedaja, filo de Ŝimri, filo de Ŝemaja.","Ziza, filo de Ŝifi, filo de Alon, filo de Jedaja, filo de Ŝimri, filo de Ŝemaja."],[4,38,"Ĉi tiuj, cititaj laŭ iliaj nomoj, estis princoj en siaj familioj, kaj iliaj patrodomoj forte vastiĝis.","Ĉi tiuj, cititaj laŭ iliaj nomoj, estis princoj en siaj familioj, kaj iliaj patrodomoj forte vastiĝis."],[4,39,"Ili iris ĝis Gedor, ĝis la orienta flanko de la valo, por serĉi paŝtejon por siaj ŝafoj;","Ili iris ĝis Gedor, ĝis la orienta flanko de la valo, por serĉi paŝtejon por siaj ŝafoj;"],[4,40,"kaj ili trovis paŝtejon grasan kaj bonan, kaj teron vastan, trankvilan, kaj kvietan, ĉar el la Ĥamidoj estis tiuj, kiuj tie loĝis antaŭe.","kaj ili trovis paŝtejon grasan kaj bonan, kaj teron vastan, trankvilan, kaj kvietan, ĉar el la Ĥamidoj estis tiuj, kiuj tie loĝis antaŭe."],[4,41,"Kaj venis tiuj, kiuj ĵus estas cititaj, en la tempo de Ĥizkija, reĝo de Judujo, kaj disbatis iliajn tendojn, kaj ankaŭ la Meunojn, kiuj tie troviĝis, kaj ekstermis ilin por ĉiam kaj ekloĝis sur ilia loko, ĉar tie estis paŝtejo por iliaj ŝafoj.","Kaj venis tiuj, kiuj ĵus estas cititaj, en la tempo de Ĥizkija, reĝo de Judujo, kaj disbatis iliajn tendojn, kaj ankaŭ la Meunojn, kiuj tie troviĝis, kaj ekstermis ilin por ĉiam kaj ekloĝis sur ilia loko, ĉar tie estis paŝtejo por iliaj ŝafoj."],[4,42,"Kaj el ili, el la idoj de Simeon, kvincent homoj iris al la monto Seir; iliaj estroj estis Pelatja, Nearja, Refaja, kaj Uziel, filoj de Jiŝei.","Kaj el ili, el la idoj de Simeon, kvincent homoj iris al la monto Seir; iliaj estroj estis Pelatja, Nearja, Refaja, kaj Uziel, filoj de Jiŝei."],[4,43,"Kaj ili venkobatis la restintajn saviĝintojn de Amalek kaj ekloĝis tie por ĉiam.","Kaj ili venkobatis la restintajn saviĝintojn de Amalek kaj ekloĝis tie por ĉiam."],[5,1,"La filoj de Ruben, unuenaskito de Izrael. (Li estis la unuenaskito; sed kiam li malhonoris la liton de sia patro, lia unuenaskiteco estis fordonita al la filoj de Jozef, filo de Izrael, kaj li ne estis enskribita en la genealogian liston kiel unuenaskito;","La filoj de Ruben, unuenaskito de Izrael. (Li estis la unuenaskito; sed kiam li malhonoris la liton de sia patro, lia unuenaskiteco estis fordonita al la filoj de Jozef, filo de Izrael, kaj li ne estis enskribita en la genealogian liston kiel unuenaskito;"],[5,2,"Jehuda estis la plej potenca inter siaj fratoj, kaj la reganto devenis de li; sed la unuenaskiteco estis donita al Jozef.)","Jehuda estis la plej potenca inter siaj fratoj, kaj la reganto devenis de li; sed la unuenaskiteco estis donita al Jozef.)"],[5,3,"La filoj de Ruben, unuenaskito de Izrael: Ĥanoĥ, Palu, Ĥecron, kaj Karmi.","La filoj de Ruben, unuenaskito de Izrael: Ĥanoĥ, Palu, Ĥecron, kaj Karmi."],[5,4,"La idoj de Joel: lia filo estis Ŝemaja, lia filo estis Gog, lia filo estis Ŝimei,","La idoj de Joel: lia filo estis Ŝemaja, lia filo estis Gog, lia filo estis Ŝimei,"],[5,5,"lia filo estis Miĥa, lia filo estis Reaja, lia filo estis Baal,","lia filo estis Miĥa, lia filo estis Reaja, lia filo estis Baal,"],[5,6,"lia filo estis Beera, kiun forkondukis en kaptitecon Tiglat-Pileser, reĝo de Asirio. Li estis princo de la Rubenidoj.","lia filo estis Beera, kiun forkondukis en kaptitecon Tiglat-Pileser, reĝo de Asirio. Li estis princo de la Rubenidoj."],[5,7,"Kaj liaj fratoj, laŭ iliaj familioj, laŭ ilia genealogia listo, estis: Jeiel, la ĉefo, Zeĥarja,","Kaj liaj fratoj, laŭ iliaj familioj, laŭ ilia genealogia listo, estis: Jeiel, la ĉefo, Zeĥarja,"],[5,8,"kaj Bela, filo de Azaz, filo de Ŝema, filo de Joel. Li loĝis en Aroer, ĝis Nebo kaj Baal-Meon.","kaj Bela, filo de Azaz, filo de Ŝema, filo de Joel. Li loĝis en Aroer, ĝis Nebo kaj Baal-Meon."],[5,9,"Oriente li loĝis ĝis la komenco de la dezerto ĉe la rivero Eŭfrato; ĉar ili havis multe da brutoj en la lando Gilead.","Oriente li loĝis ĝis la komenco de la dezerto ĉe la rivero Eŭfrato; ĉar ili havis multe da brutoj en la lando Gilead."],[5,10,"En la tempo de Saul ili militis kontraŭ la Hagaridoj, kaj ĉi tiuj enfalis en iliajn manojn; kaj ili ekloĝis en la tendoj de tiuj en la tuta orienta parto de Gilead.","En la tempo de Saul ili militis kontraŭ la Hagaridoj, kaj ĉi tiuj enfalis en iliajn manojn; kaj ili ekloĝis en la tendoj de tiuj en la tuta orienta parto de Gilead."],[5,11,"La idoj de Gad loĝis apude de ili, en la lando Baŝan, ĝis Salĥa;","La idoj de Gad loĝis apude de ili, en la lando Baŝan, ĝis Salĥa;"],[5,12,"la ĉefo estis Joel, la dua estis Ŝafam, poste Janaj kaj Ŝafat en Baŝan.","la ĉefo estis Joel, la dua estis Ŝafam, poste Janaj kaj Ŝafat en Baŝan."],[5,13,"Iliaj fratoj, laŭ iliaj patrodomoj: Miĥael, Meŝulam, Ŝeba, Joraj, Jakan, Zia, kaj Eber — sep.","Iliaj fratoj, laŭ iliaj patrodomoj: Miĥael, Meŝulam, Ŝeba, Joraj, Jakan, Zia, kaj Eber — sep."],[5,14,"Jen estas la filoj de Abiĥail, filo de Ĥuri, filo de Jaroaĥ, filo de Gilead, filo de Miĥael, filo de Jeŝiŝaj, filo de Jaĥdo, filo de Buz;","Jen estas la filoj de Abiĥail, filo de Ĥuri, filo de Jaroaĥ, filo de Gilead, filo de Miĥael, filo de Jeŝiŝaj, filo de Jaĥdo, filo de Buz;"],[5,15,"Aĥi, filo de Abdiel, filo de Guni, estis ĉefo de ilia patrodomo.","Aĥi, filo de Abdiel, filo de Guni, estis ĉefo de ilia patrodomo."],[5,16,"Kaj ili loĝis en Gilead en Baŝan kaj ĝiaj filinurboj, kaj sur ĉiuj kampoj de Ŝaron, ĝis iliaj finoj.","Kaj ili loĝis en Gilead en Baŝan kaj ĝiaj filinurboj, kaj sur ĉiuj kampoj de Ŝaron, ĝis iliaj finoj."],[5,17,"Ĉiuj ili estis genealogie enskribitaj en la tempo de Jotam, reĝo de Judujo, kaj en la tempo de Jerobeam, reĝo de Izrael.","Ĉiuj ili estis genealogie enskribitaj en la tempo de Jotam, reĝo de Judujo, kaj en la tempo de Jerobeam, reĝo de Izrael."],[5,18,"La idoj de Ruben kaj la Gadidoj kaj la duontribo de Manase havis da batalkapablaj viroj, portantaj ŝildon kaj glavon, streĉantaj pafarkon, kaj instruitaj por milito, kvardek kvar mil sepcent sesdek, elirantojn en militistaro.","La idoj de Ruben kaj la Gadidoj kaj la duontribo de Manase havis da batalkapablaj viroj, portantaj ŝildon kaj glavon, streĉantaj pafarkon, kaj instruitaj por milito, kvardek kvar mil sepcent sesdek, elirantojn en militistaro."],[5,19,"Ili militis kontraŭ la Hagaridoj, kontraŭ Jetur, Nafiŝ, kaj Nodab.","Ili militis kontraŭ la Hagaridoj, kontraŭ Jetur, Nafiŝ, kaj Nodab."],[5,20,"Kaj ili ricevis helpon kontraŭ ĉi tiuj; kaj la Hagaridoj, kun ĉio, kion ili havis, estis transdonitaj en iliajn manojn. Ĉar dum la milito ili vokis al Dio, kaj Li aŭskultis ilian preĝon pro tio, ke ili fidis Lin.","Kaj ili ricevis helpon kontraŭ ĉi tiuj; kaj la Hagaridoj, kun ĉio, kion ili havis, estis transdonitaj en iliajn manojn. Ĉar dum la milito ili vokis al Dio, kaj Li aŭskultis ilian preĝon pro tio, ke ili fidis Lin."],[5,21,"Kaj ili forkaptis la brutojn de tiuj, kvindek mil kamelojn, ducent kvindek mil ŝafojn, du mil azenojn, kaj cent mil homojn.","Kaj ili forkaptis la brutojn de tiuj, kvindek mil kamelojn, ducent kvindek mil ŝafojn, du mil azenojn, kaj cent mil homojn."],[5,22,"Multe da mortigitoj falis, ĉar de Dio estis la milito. Kaj ili loĝis sur ilia loko ĝis la elpatrujigo.","Multe da mortigitoj falis, ĉar de Dio estis la milito. Kaj ili loĝis sur ilia loko ĝis la elpatrujigo."],[5,23,"La idoj de la duontribo de Manase loĝis en la lando de Baŝan ĝis Baal-Ĥermon, Senir, kaj la monto Ĥermon. Ili estis en granda nombro.","La idoj de la duontribo de Manase loĝis en la lando de Baŝan ĝis Baal-Ĥermon, Senir, kaj la monto Ĥermon. Ili estis en granda nombro."],[5,24,"Kaj jen estas la ĉefoj de iliaj patrodomoj: Efer, Jiŝei, Eliel, Azriel, Jeremia, Hodavja, kaj Jaĥdiel, viroj potencaj, viroj famaj, ĉefoj de siaj patrodomoj.","Kaj jen estas la ĉefoj de iliaj patrodomoj: Efer, Jiŝei, Eliel, Azriel, Jeremia, Hodavja, kaj Jaĥdiel, viroj potencaj, viroj famaj, ĉefoj de siaj patrodomoj."],[5,25,"Sed ili defalis de Dio de iliaj patroj, kaj malĉaste sekvis la diojn de la enlandaj popoloj, kiujn Dio ekstermis antaŭ ili;","Sed ili defalis de Dio de iliaj patroj, kaj malĉaste sekvis la diojn de la enlandaj popoloj, kiujn Dio ekstermis antaŭ ili;"],[5,26,"tial Dio de Izrael ekscitis kontraŭ ili la spiriton de Pul, reĝo de Asirio, kaj la spiriton de Tiglat-Pileser, reĝo de Asirio, kaj li elpatrujigis la Rubenidojn, la Gadidojn, kaj la duontribon de la Manaseidoj, kaj forkondukis ilin en Ĥalaĥon, Ĥaboron, Haran, kaj al la rivero Gozan ĝis la nuna tago.","tial Dio de Izrael ekscitis kontraŭ ili la spiriton de Pul, reĝo de Asirio, kaj la spiriton de Tiglat-Pileser, reĝo de Asirio, kaj li elpatrujigis la Rubenidojn, la Gadidojn, kaj la duontribon de la Manaseidoj, kaj forkondukis ilin en Ĥalaĥon, Ĥaboron, Haran, kaj al la rivero Gozan ĝis la nuna tago."],[6,1,"La filoj de Levi: Gerŝon, Kehat, kaj Merari.","La filoj de Levi: Gerŝon, Kehat, kaj Merari."],[6,2,"La filoj de Kehat: Amram, Jichar, Ĥebron, kaj Uziel.","La filoj de Kehat: Amram, Jichar, Ĥebron, kaj Uziel."],[6,3,"La infanoj de Amram: Aaron, Moseo, kaj Mirjam; kaj la filoj de Aaron: Nadab, Abihu, Eleazar, kaj Itamar.","La infanoj de Amram: Aaron, Moseo, kaj Mirjam; kaj la filoj de Aaron: Nadab, Abihu, Eleazar, kaj Itamar."],[6,4,"Eleazar naskigis Pineĥason, Pineĥas naskigis Abiŝuan,","Eleazar naskigis Pineĥason, Pineĥas naskigis Abiŝuan,"],[6,5,"Abiŝua naskigis Bukin, Buki naskigis Uzin,","Abiŝua naskigis Bukin, Buki naskigis Uzin,"],[6,6,"Uzi naskigis Zeraĥjan, Zeraĥja naskigis Merajoton,","Uzi naskigis Zeraĥjan, Zeraĥja naskigis Merajoton,"],[6,7,"Merajot naskigis Amarjan, Amarja naskigis Aĥitubon,","Merajot naskigis Amarjan, Amarja naskigis Aĥitubon,"],[6,8,"Aĥitub naskigis Cadokon, Cadok naskigis Aĥimaacon,","Aĥitub naskigis Cadokon, Cadok naskigis Aĥimaacon,"],[6,9,"Aĥimaac naskigis Azarjan, Azarja naskigis Joĥananon,","Aĥimaac naskigis Azarjan, Azarja naskigis Joĥananon,"],[6,10,"Joĥanan naskigis Azarjan (li estis tiu, kiu estis pastro en la domo, kiun Salomono konstruis en Jerusalem),","Joĥanan naskigis Azarjan (li estis tiu, kiu estis pastro en la domo, kiun Salomono konstruis en Jerusalem),"],[6,11,"Azarja naskigis Amarjan, Amarja naskigis Aĥitubon,","Azarja naskigis Amarjan, Amarja naskigis Aĥitubon,"],[6,12,"Aĥitub naskigis Cadokon, Cadok naskigis Ŝalumon,","Aĥitub naskigis Cadokon, Cadok naskigis Ŝalumon,"],[6,13,"Ŝalum naskigis Ĥilkijan, Ĥilkija naskigis Azarjan,","Ŝalum naskigis Ĥilkijan, Ĥilkija naskigis Azarjan,"],[6,14,"Azarja naskigis Serajan, Seraja naskigis Jehocadakon.","Azarja naskigis Serajan, Seraja naskigis Jehocadakon."],[6,15,"Jehocadak iris en kaptitecon, kiam la Eternulo elpatrujigis la Judojn kaj la Jerusalemanojn per Nebukadnecar.","Jehocadak iris en kaptitecon, kiam la Eternulo elpatrujigis la Judojn kaj la Jerusalemanojn per Nebukadnecar."],[6,16,"La filoj de Levi: Gerŝon, Kehat, kaj Merari.","La filoj de Levi: Gerŝon, Kehat, kaj Merari."],[6,17,"Jen estas la nomoj de la filoj de Gerŝon: Libni kaj Ŝimei.","Jen estas la nomoj de la filoj de Gerŝon: Libni kaj Ŝimei."],[6,18,"La filoj de Kehat: Amram, Jichar, Ĥebron, kaj Uziel.","La filoj de Kehat: Amram, Jichar, Ĥebron, kaj Uziel."],[6,19,"La filoj de Merari: Maĥli kaj Muŝi. Kaj jen estas la familioj de Levi laŭ iliaj patrodomoj:","La filoj de Merari: Maĥli kaj Muŝi. Kaj jen estas la familioj de Levi laŭ iliaj patrodomoj:"],[6,20,"la idoj de Gerŝon: Libni; lia filo: Jaĥat; lia filo: Zima;","la idoj de Gerŝon: Libni; lia filo: Jaĥat; lia filo: Zima;"],[6,21,"lia filo: Joaĥ; lia filo: Ido; lia filo: Zeraĥ; lia filo: Jeatraj.","lia filo: Joaĥ; lia filo: Ido; lia filo: Zeraĥ; lia filo: Jeatraj."],[6,22,"La idoj de Kehat: lia filo: Aminadab; lia filo: Koraĥ; lia filo: Asir;","La idoj de Kehat: lia filo: Aminadab; lia filo: Koraĥ; lia filo: Asir;"],[6,23,"lia filo: Elkana; lia filo: Ebjasaf; lia filo: Asir;","lia filo: Elkana; lia filo: Ebjasaf; lia filo: Asir;"],[6,24,"lia filo: Taĥat; lia filo: Uriel; lia filo: Uzija; lia filo: Ŝaul.","lia filo: Taĥat; lia filo: Uriel; lia filo: Uzija; lia filo: Ŝaul."],[6,25,"La filoj de Elkana: Amasaj kaj Aĥimot.","La filoj de Elkana: Amasaj kaj Aĥimot."],[6,26,"Elkana: la idoj de Elkana: lia filo: Cofaj; lia filo: Naĥat;","Elkana: la idoj de Elkana: lia filo: Cofaj; lia filo: Naĥat;"],[6,27,"lia filo: Eliab; lia filo: Jeroĥam; lia filo: Elkana.","lia filo: Eliab; lia filo: Jeroĥam; lia filo: Elkana."],[6,28,"La filoj de Samuel: la unuenaskito Vaŝni, kaj Abija.","La filoj de Samuel: la unuenaskito Vaŝni, kaj Abija."],[6,29,"La idoj de Merari: Maĥli; lia filo: Libni; lia filo: Ŝimei; lia filo: Uza;","La idoj de Merari: Maĥli; lia filo: Libni; lia filo: Ŝimei; lia filo: Uza;"],[6,30,"lia filo: Ŝimea; lia filo: Ĥagija; lia filo: Asaja.","lia filo: Ŝimea; lia filo: Ĥagija; lia filo: Asaja."],[6,31,"Jen estas tiuj, kiujn David starigis por kantado en la domo de la Eternulo de post la tempo, kiam la sankta kesto trovis tie ripozejon;","Jen estas tiuj, kiujn David starigis por kantado en la domo de la Eternulo de post la tempo, kiam la sankta kesto trovis tie ripozejon;"],[6,32,"ili servadis antaŭ la tabernaklo de kunveno per kantado, ĝis Salomono konstruis la domon de la Eternulo en Jerusalem; kaj ili stariĝadis al sia servado laŭ sia regularo;","ili servadis antaŭ la tabernaklo de kunveno per kantado, ĝis Salomono konstruis la domon de la Eternulo en Jerusalem; kaj ili stariĝadis al sia servado laŭ sia regularo;"],[6,33,"jen estas tiuj, kiuj stariĝadis, kaj iliaj filoj: el la Kehatidoj estis la kantisto Heman, filo de Joel, filo de Samuel,","jen estas tiuj, kiuj stariĝadis, kaj iliaj filoj: el la Kehatidoj estis la kantisto Heman, filo de Joel, filo de Samuel,"],[6,34,"filo de Elkana, filo de Jeroĥam, filo de Eliel, filo de Toaĥ,","filo de Elkana, filo de Jeroĥam, filo de Eliel, filo de Toaĥ,"],[6,35,"filo de Cuf, filo de Elkana, filo de Maĥat, filo de Amasaj,","filo de Cuf, filo de Elkana, filo de Maĥat, filo de Amasaj,"],[6,36,"filo de Elkana, filo de Joel, filo de Azarja, filo de Cefanja,","filo de Elkana, filo de Joel, filo de Azarja, filo de Cefanja,"],[6,37,"filo de Taĥat, filo de Asir, filo de Ebjasaf, filo de Koraĥ,","filo de Taĥat, filo de Asir, filo de Ebjasaf, filo de Koraĥ,"],[6,38,"filo de Jichar, filo de Kehat, filo de Levi, filo de Izrael.","filo de Jichar, filo de Kehat, filo de Levi, filo de Izrael."],[6,39,"Kaj lia frato Asaf, kiu staradis dekstre de li, Asaf, filo de Bereĥja, filo de Ŝimea,","Kaj lia frato Asaf, kiu staradis dekstre de li, Asaf, filo de Bereĥja, filo de Ŝimea,"],[6,40,"filo de Miĥael, filo de Baaseja, filo de Malkija,","filo de Miĥael, filo de Baaseja, filo de Malkija,"],[6,41,"filo de Etni, filo de Zeraĥ, filo de Adaja,","filo de Etni, filo de Zeraĥ, filo de Adaja,"],[6,42,"filo de Etan, filo de Zima, filo de Ŝimei,","filo de Etan, filo de Zima, filo de Ŝimei,"],[6,43,"filo de Jaĥat, filo de Gerŝon, filo de Levi.","filo de Jaĥat, filo de Gerŝon, filo de Levi."],[6,44,"La idoj de Merari, iliaj fratoj, staradis maldekstre: Etan, filo de Kiŝi, filo de Abdi, filo de Maluĥ,","La idoj de Merari, iliaj fratoj, staradis maldekstre: Etan, filo de Kiŝi, filo de Abdi, filo de Maluĥ,"],[6,45,"filo de Ĥaŝabja, filo de Amacja, filo de Ĥilkija,","filo de Ĥaŝabja, filo de Amacja, filo de Ĥilkija,"],[6,46,"filo de Amci, filo de Bani, filo de Ŝemer,","filo de Amci, filo de Bani, filo de Ŝemer,"],[6,47,"filo de Maĥli, filo de Muŝi, filo de Merari, filo de Levi.","filo de Maĥli, filo de Muŝi, filo de Merari, filo de Levi."],[6,48,"Kaj iliaj fratoj, la Levidoj, estis destinitaj por ĉiuj servoj en la tabernaklo de la domo de Dio.","Kaj iliaj fratoj, la Levidoj, estis destinitaj por ĉiuj servoj en la tabernaklo de la domo de Dio."],[6,49,"Aaron kaj liaj filoj incensadis sur la altaro de bruloferoj kaj sur la altaro de incensado; ili estis destinitaj por ĉiuj servoj en la plejsanktejo, kaj por pekliberigi Izraelon, konforme al ĉio, kion ordonis Moseo, servanto de Dio.","Aaron kaj liaj filoj incensadis sur la altaro de bruloferoj kaj sur la altaro de incensado; ili estis destinitaj por ĉiuj servoj en la plejsanktejo, kaj por pekliberigi Izraelon, konforme al ĉio, kion ordonis Moseo, servanto de Dio."],[6,50,"Kaj jen estas la idoj de Aaron: lia filo: Eleazar; lia filo: Pineĥas; lia filo: Abiŝua;","Kaj jen estas la idoj de Aaron: lia filo: Eleazar; lia filo: Pineĥas; lia filo: Abiŝua;"],[6,51,"lia filo: Buki; lia filo: Uzi; lia filo: Zeraĥja;","lia filo: Buki; lia filo: Uzi; lia filo: Zeraĥja;"],[6,52,"lia filo: Merajot; lia filo: Amarja; lia filo: Aĥitub;","lia filo: Merajot; lia filo: Amarja; lia filo: Aĥitub;"],[6,53,"lia filo: Cadok; lia filo: Aĥimaac.","lia filo: Cadok; lia filo: Aĥimaac."],[6,54,"Kaj jen estas iliaj loĝlokoj, laŭ iliaj vilaĝoj en iliaj limoj: al la idoj de Aaron, al la familioj de la Kehatidoj, ĉar al ili destinis la loto,","Kaj jen estas iliaj loĝlokoj, laŭ iliaj vilaĝoj en iliaj limoj: al la idoj de Aaron, al la familioj de la Kehatidoj, ĉar al ili destinis la loto,"],[6,55,"oni donis Ĥebronon, en la lando de Jehuda, kaj ĝiajn antaŭurbojn ĉirkaŭ ĝi;","oni donis Ĥebronon, en la lando de Jehuda, kaj ĝiajn antaŭurbojn ĉirkaŭ ĝi;"],[6,56,"sed la kampon de tiu urbo kaj ĝiajn vilaĝojn oni donis al Kaleb, filo de Jefune.","sed la kampon de tiu urbo kaj ĝiajn vilaĝojn oni donis al Kaleb, filo de Jefune."],[6,57,"Al la idoj de Aaron oni donis la urbojn de rifuĝo: Ĥebronon, Libnan kaj ĝiajn antaŭurbojn, Jatiron, Eŝtemoan kaj ĝiajn antaŭurbojn,","Al la idoj de Aaron oni donis la urbojn de rifuĝo: Ĥebronon, Libnan kaj ĝiajn antaŭurbojn, Jatiron, Eŝtemoan kaj ĝiajn antaŭurbojn,"],[6,58,"Ĥilenon kaj ĝiajn antaŭurbojn, Debiron kaj ĝiajn antaŭurbojn,","Ĥilenon kaj ĝiajn antaŭurbojn, Debiron kaj ĝiajn antaŭurbojn,"],[6,59,"Aŝanon kaj ĝiajn antaŭurbojn, Bet-Ŝemeŝon kaj ĝiajn antaŭurbojn;","Aŝanon kaj ĝiajn antaŭurbojn, Bet-Ŝemeŝon kaj ĝiajn antaŭurbojn;"],[6,60,"kaj de la tribo de Benjamen: Geban kaj ĝiajn antaŭurbojn, Alemeton kaj ĝiajn antaŭurbojn, kaj Anatoton kaj ĝiajn antaŭurbojn. La nombro de ĉiuj iliaj urboj en iliaj familioj estis dek tri urboj.","kaj de la tribo de Benjamen: Geban kaj ĝiajn antaŭurbojn, Alemeton kaj ĝiajn antaŭurbojn, kaj Anatoton kaj ĝiajn antaŭurbojn. La nombro de ĉiuj iliaj urboj en iliaj familioj estis dek tri urboj."],[6,61,"Al la idoj de Kehat, kiuj restis el la familio de la tribo, oni donis de la duontribo de Manase laŭlote dek urbojn.","Al la idoj de Kehat, kiuj restis el la familio de la tribo, oni donis de la duontribo de Manase laŭlote dek urbojn."],[6,62,"Al la idoj de Gerŝon laŭ iliaj familioj oni donis de la tribo Isaĥar, de la tribo Aŝer, de la tribo Naftali, kaj de la tribo Manase en Baŝan dek tri urbojn.","Al la idoj de Gerŝon laŭ iliaj familioj oni donis de la tribo Isaĥar, de la tribo Aŝer, de la tribo Naftali, kaj de la tribo Manase en Baŝan dek tri urbojn."],[6,63,"Al la idoj de Merari laŭ iliaj familioj oni donis de la tribo Ruben, de la tribo Gad, kaj de la tribo Zebulun laŭlote dek du urbojn.","Al la idoj de Merari laŭ iliaj familioj oni donis de la tribo Ruben, de la tribo Gad, kaj de la tribo Zebulun laŭlote dek du urbojn."],[6,64,"Kaj la Izraelidoj donis al la Levidoj la urbojn kaj iliajn antaŭurbojn.","Kaj la Izraelidoj donis al la Levidoj la urbojn kaj iliajn antaŭurbojn."],[6,65,"Ili donis laŭlote de la tribo de la Jehudaidoj, de la tribo de la Simeonidoj, kaj de la tribo de la Benjamenidoj tiujn urbojn, kiujn ili nomis laŭ la nomoj.","Ili donis laŭlote de la tribo de la Jehudaidoj, de la tribo de la Simeonidoj, kaj de la tribo de la Benjamenidoj tiujn urbojn, kiujn ili nomis laŭ la nomoj."],[6,66,"Al kelkaj familioj el la idoj de Kehat oni donis urbojn, apartenontajn al ili, de la tribo Efraim.","Al kelkaj familioj el la idoj de Kehat oni donis urbojn, apartenontajn al ili, de la tribo Efraim."],[6,67,"Kaj oni donis al ili la urbojn de rifuĝo: Ŝeĥemon kaj ĝiajn antaŭurbojn, sur la monto de Efraim, Gezeron kaj ĝiajn antaŭurbojn,","Kaj oni donis al ili la urbojn de rifuĝo: Ŝeĥemon kaj ĝiajn antaŭurbojn, sur la monto de Efraim, Gezeron kaj ĝiajn antaŭurbojn,"],[6,68,"Jokmeamon kaj ĝiajn antaŭurbojn, Bet-Ĥoronon kaj ĝiajn antaŭurbojn,","Jokmeamon kaj ĝiajn antaŭurbojn, Bet-Ĥoronon kaj ĝiajn antaŭurbojn,"],[6,69,"Ajalonon kaj ĝiajn antaŭurbojn, Gat-Rimonon kaj ĝiajn antaŭurbojn;","Ajalonon kaj ĝiajn antaŭurbojn, Gat-Rimonon kaj ĝiajn antaŭurbojn;"],[6,70,"kaj de la duontribo de Manase: Aneron kaj ĝiajn antaŭurbojn, Bileamon kaj ĝiajn antaŭurbojn. Tio estis por la restintaj familioj de la Kehatidoj.","kaj de la duontribo de Manase: Aneron kaj ĝiajn antaŭurbojn, Bileamon kaj ĝiajn antaŭurbojn. Tio estis por la restintaj familioj de la Kehatidoj."],[6,71,"Al la idoj de Gerŝon oni donis de la familioj de la duontribo de Manase: Golanon en Baŝan kaj ĝiajn antaŭurbojn, kaj Aŝtaroton kaj ĝiajn antaŭurbojn;","Al la idoj de Gerŝon oni donis de la familioj de la duontribo de Manase: Golanon en Baŝan kaj ĝiajn antaŭurbojn, kaj Aŝtaroton kaj ĝiajn antaŭurbojn;"],[6,72,"de la tribo Isaĥar: Kedeŝon kaj ĝiajn antaŭurbojn, Dabraton kaj ĝiajn antaŭurbojn,","de la tribo Isaĥar: Kedeŝon kaj ĝiajn antaŭurbojn, Dabraton kaj ĝiajn antaŭurbojn,"],[6,73,"Ramoton kaj ĝiajn antaŭurbojn, kaj Anemon kaj ĝiajn antaŭurbojn;","Ramoton kaj ĝiajn antaŭurbojn, kaj Anemon kaj ĝiajn antaŭurbojn;"],[6,74,"de la tribo Aŝer: Maŝalon kaj ĝiajn antaŭurbojn, Abdonon kaj ĝiajn antaŭurbojn,","de la tribo Aŝer: Maŝalon kaj ĝiajn antaŭurbojn, Abdonon kaj ĝiajn antaŭurbojn,"],[6,75,"Ĥukokon kaj ĝiajn antaŭurbojn, kaj Reĥobon kaj ĝiajn antaŭurbojn;","Ĥukokon kaj ĝiajn antaŭurbojn, kaj Reĥobon kaj ĝiajn antaŭurbojn;"],[6,76,"de la tribo Naftali: Kedeŝon en Galileo kaj ĝiajn antaŭurbojn, Ĥamonon kaj ĝiajn antaŭurbojn, kaj Kirjataimon kaj ĝiajn antaŭurbojn.","de la tribo Naftali: Kedeŝon en Galileo kaj ĝiajn antaŭurbojn, Ĥamonon kaj ĝiajn antaŭurbojn, kaj Kirjataimon kaj ĝiajn antaŭurbojn."],[6,77,"Al la ceteraj idoj de Merari oni donis de la tribo Zebulun: Rimonon kaj ĝiajn antaŭurbojn, kaj Taboron kaj ĝiajn antaŭurbojn;","Al la ceteraj idoj de Merari oni donis de la tribo Zebulun: Rimonon kaj ĝiajn antaŭurbojn, kaj Taboron kaj ĝiajn antaŭurbojn;"],[6,78,"kaj transe de Jordan, kontraŭ Jeriĥo, oriente de Jordan, oni donis de la tribo Ruben: Beceron en la dezerto kaj ĝiajn antaŭurbojn, Jahacon kaj ĝiajn antaŭurbojn,","kaj transe de Jordan, kontraŭ Jeriĥo, oriente de Jordan, oni donis de la tribo Ruben: Beceron en la dezerto kaj ĝiajn antaŭurbojn, Jahacon kaj ĝiajn antaŭurbojn,"],[6,79,"Kedemoton kaj ĝiajn antaŭurbojn, kaj Mefaaton kaj ĝiajn antaŭurbojn;","Kedemoton kaj ĝiajn antaŭurbojn, kaj Mefaaton kaj ĝiajn antaŭurbojn;"],[6,80,"kaj de la tribo Gad: Ramoton en Gilead kaj ĝiajn antaŭurbojn, Maĥanaimon kaj ĝiajn antaŭurbojn,","kaj de la tribo Gad: Ramoton en Gilead kaj ĝiajn antaŭurbojn, Maĥanaimon kaj ĝiajn antaŭurbojn,"],[6,81,"Ĥeŝbonon kaj ĝiajn antaŭurbojn, kaj Jazeron kaj ĝiajn antaŭurbojn.","Ĥeŝbonon kaj ĝiajn antaŭurbojn, kaj Jazeron kaj ĝiajn antaŭurbojn."],[7,1,"La filoj de Isaĥar estis: Tola, Pua, Jaŝub, kaj Ŝimron — kvar.","La filoj de Isaĥar estis: Tola, Pua, Jaŝub, kaj Ŝimron — kvar."],[7,2,"La idoj de Tola: Uzi, Refaja, Jeriel, Jaĥmaj, Jibsam, kaj Ŝemuel, ĉefoj de patrodomoj de Tola, kuraĝaj militistoj en siaj generacioj; ilia nombro en la tempo de David estis dudek du mil sescent.","La idoj de Tola: Uzi, Refaja, Jeriel, Jaĥmaj, Jibsam, kaj Ŝemuel, ĉefoj de patrodomoj de Tola, kuraĝaj militistoj en siaj generacioj; ilia nombro en la tempo de David estis dudek du mil sescent."],[7,3,"La idoj de Uzi: Jizraĥja; la idoj de Jizraĥja: Miĥael, Obadja, Joel, kaj Jiŝija — kune kvin patrodomoj.","La idoj de Uzi: Jizraĥja; la idoj de Jizraĥja: Miĥael, Obadja, Joel, kaj Jiŝija — kune kvin patrodomoj."],[7,4,"Kun ili, laŭ iliaj generacioj, laŭ iliaj patrodomoj, estis da militistoj armitaj por milito tridek ses mil; ĉar ili havis multe da edzinoj kaj infanoj.","Kun ili, laŭ iliaj generacioj, laŭ iliaj patrodomoj, estis da militistoj armitaj por milito tridek ses mil; ĉar ili havis multe da edzinoj kaj infanoj."],[7,5,"Da iliaj fratoj, en ĉiuj familioj de Isaĥar, estis okdek sep mil batalkapabluloj, ĉiuj enskribitaj en la genealogiajn listojn.","Da iliaj fratoj, en ĉiuj familioj de Isaĥar, estis okdek sep mil batalkapabluloj, ĉiuj enskribitaj en la genealogiajn listojn."],[7,6,"Ĉe Benjamen: Bela, Beĥer, kaj Jediael — tri.","Ĉe Benjamen: Bela, Beĥer, kaj Jediael — tri."],[7,7,"La idoj de Bela: Ecbon, Uzi, Uziel, Jerimot, kaj Iri — kvin patrodomoj, militkapablaj. En la genealogiaj listoj ili prezentis la nombron de dudek du mil tridek kvar.","La idoj de Bela: Ecbon, Uzi, Uziel, Jerimot, kaj Iri — kvin patrodomoj, militkapablaj. En la genealogiaj listoj ili prezentis la nombron de dudek du mil tridek kvar."],[7,8,"La idoj de Beĥer: Zemira, Joaŝ, Eliezer, Eljoenaj, Omri, Jeremot, Abija, Anatot, kaj Alemet; ĉiuj ili estis la filoj de Beĥer.","La idoj de Beĥer: Zemira, Joaŝ, Eliezer, Eljoenaj, Omri, Jeremot, Abija, Anatot, kaj Alemet; ĉiuj ili estis la filoj de Beĥer."],[7,9,"En la listoj, laŭ ilia genealogio, laŭ iliaj patrodomoj, estis dudek mil ducent batalkapabluloj.","En la listoj, laŭ ilia genealogio, laŭ iliaj patrodomoj, estis dudek mil ducent batalkapabluloj."],[7,10,"La idoj de Jediael: Bilhan; la idoj de Bilhan: Jeuŝ, Benjamen, Ehud, Kenaana, Zetan, Tarŝiŝ, kaj Aĥiŝaĥar.","La idoj de Jediael: Bilhan; la idoj de Bilhan: Jeuŝ, Benjamen, Ehud, Kenaana, Zetan, Tarŝiŝ, kaj Aĥiŝaĥar."],[7,11,"Ĉiuj ili estis la idoj de Jediael, laŭ patrodomoj, batalkapabluloj, dek sep mil ducent armitaj por milito.","Ĉiuj ili estis la idoj de Jediael, laŭ patrodomoj, batalkapabluloj, dek sep mil ducent armitaj por milito."],[7,12,"Ŝupim kaj Ĥupim, idoj de Ir; Ĥuŝim, idoj de Aĥer.","Ŝupim kaj Ĥupim, idoj de Ir; Ĥuŝim, idoj de Aĥer."],[7,13,"La filoj de Naftali: Jaĥciel, Guni, Jecer, kaj Ŝalum, filoj de Bilha.","La filoj de Naftali: Jaĥciel, Guni, Jecer, kaj Ŝalum, filoj de Bilha."],[7,14,"La filoj de Manase: Asriel, kiun naskis lia kromvirino, Sirianino; ŝi naskis ankaŭ Maĥiron, la patron de Gilead.","La filoj de Manase: Asriel, kiun naskis lia kromvirino, Sirianino; ŝi naskis ankaŭ Maĥiron, la patron de Gilead."],[7,15,"Maĥir prenis edzinon el la domanaro de Ĥupim kaj Ŝupim; la nomo de lia fratino estis Maaĥa. La nomo de la dua estis Celofĥad. Celofĥad havis nur filinojn.","Maĥir prenis edzinon el la domanaro de Ĥupim kaj Ŝupim; la nomo de lia fratino estis Maaĥa. La nomo de la dua estis Celofĥad. Celofĥad havis nur filinojn."],[7,16,"Kaj Maaĥa, la edzino de Maĥir, naskis filon kaj donis al li la nomon Pereŝ; la nomo de lia frato estis Ŝereŝ; liaj filoj estis Ulam kaj Rekem.","Kaj Maaĥa, la edzino de Maĥir, naskis filon kaj donis al li la nomon Pereŝ; la nomo de lia frato estis Ŝereŝ; liaj filoj estis Ulam kaj Rekem."],[7,17,"La filo de Ulam estis Bedan. Tio estas la filoj de Gilead, filo de Maĥir, filo de Manase.","La filo de Ulam estis Bedan. Tio estas la filoj de Gilead, filo de Maĥir, filo de Manase."],[7,18,"Lia fratino Moleĥet naskis Iŝ-Hodon, Abiezeron, kaj Maĥlan.","Lia fratino Moleĥet naskis Iŝ-Hodon, Abiezeron, kaj Maĥlan."],[7,19,"La filoj de Ŝemida estis: Aĥjan, Ŝeĥem, Likĥi, kaj Aniam.","La filoj de Ŝemida estis: Aĥjan, Ŝeĥem, Likĥi, kaj Aniam."],[7,20,"La idoj de Efraim: Ŝutelaĥ, kaj lia filo Bered, kaj lia filo Taĥat, kaj lia filo Eleada, kaj lia filo Taĥat,","La idoj de Efraim: Ŝutelaĥ, kaj lia filo Bered, kaj lia filo Taĥat, kaj lia filo Eleada, kaj lia filo Taĥat,"],[7,21,"kaj lia filo Zabad, kaj lia filo Ŝutelaĥ, kaj Ezer, kaj Elead. Kaj mortigis ilin la loĝantoj de Gat, la indiĝenoj de la lando, kiam ili iris, por forpreni iliajn brutojn.","kaj lia filo Zabad, kaj lia filo Ŝutelaĥ, kaj Ezer, kaj Elead. Kaj mortigis ilin la loĝantoj de Gat, la indiĝenoj de la lando, kiam ili iris, por forpreni iliajn brutojn."],[7,22,"Kaj ilia patro Efraim funebris longan tempon, kaj liaj fratoj venis, por konsoli lin.","Kaj ilia patro Efraim funebris longan tempon, kaj liaj fratoj venis, por konsoli lin."],[7,23,"Kaj li envenis al sia edzino, kaj ŝi gravediĝis kaj naskis filon, kaj donis al li la nomon Beria, ĉar malfeliĉo okazis en lia domo.","Kaj li envenis al sia edzino, kaj ŝi gravediĝis kaj naskis filon, kaj donis al li la nomon Beria, ĉar malfeliĉo okazis en lia domo."],[7,24,"Lia filino estis Ŝeera. Ŝi konstruis Bet-Ĥoronon, la malsupran kaj la supran, kaj Uzen-Ŝeeran.","Lia filino estis Ŝeera. Ŝi konstruis Bet-Ĥoronon, la malsupran kaj la supran, kaj Uzen-Ŝeeran."],[7,25,"Kaj lia filo estis Refaĥ, lia filo estis Reŝef, lia filo estis Telaĥ, lia filo estis Taĥan,","Kaj lia filo estis Refaĥ, lia filo estis Reŝef, lia filo estis Telaĥ, lia filo estis Taĥan,"],[7,26,"lia filo estis Ladan, lia filo estis Amihud, lia filo estis Eliŝama,","lia filo estis Ladan, lia filo estis Amihud, lia filo estis Eliŝama,"],[7,27,"lia filo estis Nun, lia filo estis Josuo.","lia filo estis Nun, lia filo estis Josuo."],[7,28,"Ilia posedaĵo kaj loĝloko estis Bet-El kaj ĝiaj filinurboj, oriente Naaran, okcidente Gezer kun ĝiaj filinurboj, kaj Ŝeĥem kun ĝiaj filinurboj, ĝis Aza kun ĝiaj filinurboj;","Ilia posedaĵo kaj loĝloko estis Bet-El kaj ĝiaj filinurboj, oriente Naaran, okcidente Gezer kun ĝiaj filinurboj, kaj Ŝeĥem kun ĝiaj filinurboj, ĝis Aza kun ĝiaj filinurboj;"],[7,29,"ĉe la flanko de la Manaseidoj: Bet-Ŝean kun ĝiaj filinurboj, Taanaĥ kun ĝiaj filinurboj, Megido kun ĝiaj filinurboj, Dor kun ĝiaj filinurboj. En tiuj lokoj loĝis la idoj de Jozef, filo de Izrael.","ĉe la flanko de la Manaseidoj: Bet-Ŝean kun ĝiaj filinurboj, Taanaĥ kun ĝiaj filinurboj, Megido kun ĝiaj filinurboj, Dor kun ĝiaj filinurboj. En tiuj lokoj loĝis la idoj de Jozef, filo de Izrael."],[7,30,"La filoj de Aŝer: Jimna, Jiŝva, Jiŝvi, Beria; ilia fratino estis Seraĥ.","La filoj de Aŝer: Jimna, Jiŝva, Jiŝvi, Beria; ilia fratino estis Seraĥ."],[7,31,"La filoj de Beria: Ĥeber, kaj Malkiel, kiu estis la patro de Birzait.","La filoj de Beria: Ĥeber, kaj Malkiel, kiu estis la patro de Birzait."],[7,32,"Ĥeber naskigis Jafleton, Ŝomeron, Ĥotamon, kaj Ŝuan, ilian fratinon.","Ĥeber naskigis Jafleton, Ŝomeron, Ĥotamon, kaj Ŝuan, ilian fratinon."],[7,33,"La filoj de Jaflet: Pasaĥ, Bimhal, kaj Aŝvat. Tio estas la filoj de Jaflet.","La filoj de Jaflet: Pasaĥ, Bimhal, kaj Aŝvat. Tio estas la filoj de Jaflet."],[7,34,"La filoj de Ŝemer: Aĥi, Rohaga, Jeĥuba, kaj Aram.","La filoj de Ŝemer: Aĥi, Rohaga, Jeĥuba, kaj Aram."],[7,35,"La filoj de lia frato Helem: Cofaĥ, Jimna, Ŝeleŝ, kaj Amal.","La filoj de lia frato Helem: Cofaĥ, Jimna, Ŝeleŝ, kaj Amal."],[7,36,"La filoj de Cofaĥ: Suaĥ, Ĥarnefer, Ŝual, Beri, Jimra,","La filoj de Cofaĥ: Suaĥ, Ĥarnefer, Ŝual, Beri, Jimra,"],[7,37,"Becer, Hod, Ŝama, Ŝilŝa, Jitran, kaj Beera.","Becer, Hod, Ŝama, Ŝilŝa, Jitran, kaj Beera."],[7,38,"La filoj de Jeter: Jefune, Pispa, kaj Ara.","La filoj de Jeter: Jefune, Pispa, kaj Ara."],[7,39,"La filoj de Ula: Araĥ, Ĥaniel, kaj Ricja.","La filoj de Ula: Araĥ, Ĥaniel, kaj Ricja."],[7,40,"Ĉiuj ĉi tiuj estis idoj de Aŝer, ĉefoj de patrodomoj, elektitaj, kuraĝaj militistoj, ĉefaj estroj. Ili estis enskribitaj en la genealogia listo, en la militistaro, por milito; ilia nombro estis dudek ses mil viroj.","Ĉiuj ĉi tiuj estis idoj de Aŝer, ĉefoj de patrodomoj, elektitaj, kuraĝaj militistoj, ĉefaj estroj. Ili estis enskribitaj en la genealogia listo, en la militistaro, por milito; ilia nombro estis dudek ses mil viroj."],[8,1,"De Benjamen naskiĝis: Bela, lia unuenaskito, Aŝbel, la dua, Aĥraĥ, la tria;","De Benjamen naskiĝis: Bela, lia unuenaskito, Aŝbel, la dua, Aĥraĥ, la tria;"],[8,2,"Noĥa estis la kvara, kaj Rafa estis la kvina.","Noĥa estis la kvara, kaj Rafa estis la kvina."],[8,3,"La filoj de Bela estis: Adar, Gera, Abihud,","La filoj de Bela estis: Adar, Gera, Abihud,"],[8,4,"Abiŝua, Naaman, Aĥoaĥ,","Abiŝua, Naaman, Aĥoaĥ,"],[8,5,"Gera, Ŝefufan, kaj Ĥuram.","Gera, Ŝefufan, kaj Ĥuram."],[8,6,"Jen estas la filoj de Ehud, kiuj estis ĉefoj de patrodomoj, kiuj loĝis en Geba kaj elmigris en Manaĥaton:","Jen estas la filoj de Ehud, kiuj estis ĉefoj de patrodomoj, kiuj loĝis en Geba kaj elmigris en Manaĥaton:"],[8,7,"Naaman, Aĥija, Gera; ĉi tiu elmigrigis ilin, kaj li naskigis Uzan kaj Aĥiĥudon.","Naaman, Aĥija, Gera; ĉi tiu elmigrigis ilin, kaj li naskigis Uzan kaj Aĥiĥudon."],[8,8,"Ŝaĥaraim naskigis sur la kampoj de Moab, post kiam li forigis de si siajn edzinojn Ĥuŝim kaj Baara.","Ŝaĥaraim naskigis sur la kampoj de Moab, post kiam li forigis de si siajn edzinojn Ĥuŝim kaj Baara."],[8,9,"Li naskigis de sia edzino Ĥodeŝ: Jobabon, Cibjan, Meŝan, Malkamon,","Li naskigis de sia edzino Ĥodeŝ: Jobabon, Cibjan, Meŝan, Malkamon,"],[8,10,"Jeucon, Ŝoĥjan, kaj Mirman. Tio estis liaj filoj, ĉefoj de patrodomoj.","Jeucon, Ŝoĥjan, kaj Mirman. Tio estis liaj filoj, ĉefoj de patrodomoj."],[8,11,"De Ĥuŝim li naskigis Abitubon kaj Elpaalon.","De Ĥuŝim li naskigis Abitubon kaj Elpaalon."],[8,12,"La filoj de Elpaal: Eber, Miŝeam, kaj Ŝemer; ĉi tiu konstruis Onon kaj Lodon kaj ĝiajn filinurbojn;","La filoj de Elpaal: Eber, Miŝeam, kaj Ŝemer; ĉi tiu konstruis Onon kaj Lodon kaj ĝiajn filinurbojn;"],[8,13,"kaj Beria, kaj Ŝema. Ili estis la ĉefoj de patrodomoj de la loĝantoj de Ajalon; ili elpelis la loĝantojn de Gat.","kaj Beria, kaj Ŝema. Ili estis la ĉefoj de patrodomoj de la loĝantoj de Ajalon; ili elpelis la loĝantojn de Gat."],[8,14,"Aĥjo, Ŝaŝak, Jeremot,","Aĥjo, Ŝaŝak, Jeremot,"],[8,15,"Zebadja, Arad, Eder,","Zebadja, Arad, Eder,"],[8,16,"Miĥael, Jiŝpa, kaj Joĥa estis la filoj de Beria.","Miĥael, Jiŝpa, kaj Joĥa estis la filoj de Beria."],[8,17,"Zebadja, Meŝulam, Ĥizki, Ĥeber,","Zebadja, Meŝulam, Ĥizki, Ĥeber,"],[8,18,"Jiŝmeraj, Jizlia, kaj Jobab estis la filoj de Elpaal.","Jiŝmeraj, Jizlia, kaj Jobab estis la filoj de Elpaal."],[8,19,"Jakim, Ziĥri, Zabdi,","Jakim, Ziĥri, Zabdi,"],[8,20,"Elienaj, Ciltaj, Eliel,","Elienaj, Ciltaj, Eliel,"],[8,21,"Adaja, Beraja, kaj Ŝimrat estis la filoj de Ŝimei.","Adaja, Beraja, kaj Ŝimrat estis la filoj de Ŝimei."],[8,22,"Jiŝpan, Eber, Eliel,","Jiŝpan, Eber, Eliel,"],[8,23,"Abdon, Ziĥri, Ĥanan,","Abdon, Ziĥri, Ĥanan,"],[8,24,"Ĥananja, Elam, Antotija,","Ĥananja, Elam, Antotija,"],[8,25,"Jifdeja, kaj Penuel estis la filoj de Ŝaŝak.","Jifdeja, kaj Penuel estis la filoj de Ŝaŝak."],[8,26,"Ŝamŝeraj, Ŝeĥarja, Atalja,","Ŝamŝeraj, Ŝeĥarja, Atalja,"],[8,27,"Jaareŝja, Elija, kaj Ziĥri estis la filoj de Jeroĥam.","Jaareŝja, Elija, kaj Ziĥri estis la filoj de Jeroĥam."],[8,28,"Tio estis la ĉefoj de patrodomoj, ĉefoj laŭ siaj generacioj; ili loĝis en Jerusalem.","Tio estis la ĉefoj de patrodomoj, ĉefoj laŭ siaj generacioj; ili loĝis en Jerusalem."],[8,29,"En Gibeon loĝis: la fondinto de Gibeon — la nomo de lia edzino estis Maaĥa —","En Gibeon loĝis: la fondinto de Gibeon — la nomo de lia edzino estis Maaĥa —"],[8,30,"kaj lia unuenaskita filo Abdon, Cur, Kiŝ, Baal, Nadab,","kaj lia unuenaskita filo Abdon, Cur, Kiŝ, Baal, Nadab,"],[8,31,"Gedor, Aĥjo, kaj Zeĥer.","Gedor, Aĥjo, kaj Zeĥer."],[8,32,"Miklot naskigis Ŝiman. Ankaŭ ili apud siaj fratoj enloĝiĝis en Jerusalem kun siaj fratoj.","Miklot naskigis Ŝiman. Ankaŭ ili apud siaj fratoj enloĝiĝis en Jerusalem kun siaj fratoj."],[8,33,"Ner naskigis Kiŝon, Kiŝ naskigis Saulon, Saul naskigis Jonatanon, Malki-Ŝuan, Abinadabon, kaj Eŝbaalon.","Ner naskigis Kiŝon, Kiŝ naskigis Saulon, Saul naskigis Jonatanon, Malki-Ŝuan, Abinadabon, kaj Eŝbaalon."],[8,34,"La filo de Jonatan estis Merib-Baal, kaj Merib-Baal naskigis Miĥan.","La filo de Jonatan estis Merib-Baal, kaj Merib-Baal naskigis Miĥan."],[8,35,"La filoj de Miĥa estis Piton, Meleĥ, Taarea, kaj Aĥaz.","La filoj de Miĥa estis Piton, Meleĥ, Taarea, kaj Aĥaz."],[8,36,"Aĥaz naskigis Jehoadan; Jehoada naskigis Alemeton, Azmaveton, kaj Zimrin; Zimri naskigis Mocan.","Aĥaz naskigis Jehoadan; Jehoada naskigis Alemeton, Azmaveton, kaj Zimrin; Zimri naskigis Mocan."],[8,37,"Moca naskigis Binean; lia filo estis Rafa, lia filo estis Eleasa, lia filo estis Acel.","Moca naskigis Binean; lia filo estis Rafa, lia filo estis Eleasa, lia filo estis Acel."],[8,38,"Acel havis ses filojn; jen estas iliaj nomoj: Azrikam, Boĥru, Iŝmael, Ŝearja, Obadja, kaj Ĥanan. Ĉiuj ĉi tiuj estis la filoj de Acel.","Acel havis ses filojn; jen estas iliaj nomoj: Azrikam, Boĥru, Iŝmael, Ŝearja, Obadja, kaj Ĥanan. Ĉiuj ĉi tiuj estis la filoj de Acel."],[8,39,"La filoj de lia frato Eŝek: lia unuenaskito estis Ulam, la dua estis Jeuŝ, kaj la tria estis Elifelet.","La filoj de lia frato Eŝek: lia unuenaskito estis Ulam, la dua estis Jeuŝ, kaj la tria estis Elifelet."],[8,40,"La filoj de Ulam estis kuraĝaj militistoj, pafarkistoj, kaj ili havis multe da filoj kaj nepoj: cent kvindek. Ĉiuj ĉi tiuj estis el la Benjamenidoj.","La filoj de Ulam estis kuraĝaj militistoj, pafarkistoj, kaj ili havis multe da filoj kaj nepoj: cent kvindek. Ĉiuj ĉi tiuj estis el la Benjamenidoj."],[9,1,"Ĉiuj Izraelidoj estis kalkulitaj, kaj ili estis enskribitaj en la libro de la reĝoj de Izrael. La Judojn oni forkondukis en Babelon pro iliaj malbonagoj.","Ĉiuj Izraelidoj estis kalkulitaj, kaj ili estis enskribitaj en la libro de la reĝoj de Izrael. La Judojn oni forkondukis en Babelon pro iliaj malbonagoj."],[9,2,"La unuaj loĝantoj, kiuj loĝis en siaj posedaĵoj, en siaj urboj, estis Izraelidoj, pastroj, Levidoj, kaj Netinoj.","La unuaj loĝantoj, kiuj loĝis en siaj posedaĵoj, en siaj urboj, estis Izraelidoj, pastroj, Levidoj, kaj Netinoj."],[9,3,"En Jerusalem loĝis parto de la idoj de Jehuda, de la idoj de Benjamen, kaj de la idoj de Efraim kaj de Manase:","En Jerusalem loĝis parto de la idoj de Jehuda, de la idoj de Benjamen, kaj de la idoj de Efraim kaj de Manase:"],[9,4,"Utaj, filo de Amihud, filo de Omri, filo de Imri, filo de Bani, el la idoj de Perec, filo de Jehuda;","Utaj, filo de Amihud, filo de Omri, filo de Imri, filo de Bani, el la idoj de Perec, filo de Jehuda;"],[9,5,"kaj el la Ŝiloanoj: Asaja, la unuenaskito, kaj liaj filoj;","kaj el la Ŝiloanoj: Asaja, la unuenaskito, kaj liaj filoj;"],[9,6,"el la idoj de Zeraĥ: Jeuel, kaj iliaj fratoj, sescent naŭdek;","el la idoj de Zeraĥ: Jeuel, kaj iliaj fratoj, sescent naŭdek;"],[9,7,"el la Benjamenidoj: Salu, filo de Meŝulam, filo de Hodavja, filo de Hasenua,","el la Benjamenidoj: Salu, filo de Meŝulam, filo de Hodavja, filo de Hasenua,"],[9,8,"kaj Jibneja, filo de Jeroĥam, Ela, filo de Uzi, filo de Miĥri, kaj Meŝulam, filo de Ŝefatja, filo de Reuel, filo de Jibnija;","kaj Jibneja, filo de Jeroĥam, Ela, filo de Uzi, filo de Miĥri, kaj Meŝulam, filo de Ŝefatja, filo de Reuel, filo de Jibnija;"],[9,9,"kaj iliaj fratoj laŭ sia deveno, naŭcent kvindek ses. Ĉiuj ĉi tiuj estis ĉefoj de patrodomoj en siaj patrodomoj.","kaj iliaj fratoj laŭ sia deveno, naŭcent kvindek ses. Ĉiuj ĉi tiuj estis ĉefoj de patrodomoj en siaj patrodomoj."],[9,10,"Kaj el la pastroj: Jedaja, Jehojarib, Jaĥin;","Kaj el la pastroj: Jedaja, Jehojarib, Jaĥin;"],[9,11,"Azarja, filo de Ĥilkija, filo de Meŝulam, filo de Cadok, filo de Merajot, filo de Aĥitub, estro en la domo de Dio;","Azarja, filo de Ĥilkija, filo de Meŝulam, filo de Cadok, filo de Merajot, filo de Aĥitub, estro en la domo de Dio;"],[9,12,"kaj Adaja, filo de Jeroĥam, filo de Paŝĥur, filo de Malkija, kaj Maasaj, filo de Adiel, filo de Jaĥzera, filo de Meŝulam, filo de Meŝilemit, filo de Imer;","kaj Adaja, filo de Jeroĥam, filo de Paŝĥur, filo de Malkija, kaj Maasaj, filo de Adiel, filo de Jaĥzera, filo de Meŝulam, filo de Meŝilemit, filo de Imer;"],[9,13,"kaj iliaj fratoj, ĉefoj de siaj patrodomoj, mil sepcent sesdek, tre lertaj en la laboro de la servado en la domo de Dio.","kaj iliaj fratoj, ĉefoj de siaj patrodomoj, mil sepcent sesdek, tre lertaj en la laboro de la servado en la domo de Dio."],[9,14,"El la Levidoj: Ŝemaja, filo de Ĥaŝub, filo de Azrikam, filo de Ĥaŝabja, el la idoj de Merari;","El la Levidoj: Ŝemaja, filo de Ĥaŝub, filo de Azrikam, filo de Ĥaŝabja, el la idoj de Merari;"],[9,15,"kaj Bakbakar, Ĥereŝ, Galal, Matanja, filo de Miĥa, filo de Ziĥri, filo de Asaf,","kaj Bakbakar, Ĥereŝ, Galal, Matanja, filo de Miĥa, filo de Ziĥri, filo de Asaf,"],[9,16,"Obadja, filo de Ŝemaja, filo de Galal, filo de Jedutun, Bereĥja, filo de Asa, filo de Elkana, kiu loĝis en la vilaĝoj de la Netofaanoj.","Obadja, filo de Ŝemaja, filo de Galal, filo de Jedutun, Bereĥja, filo de Asa, filo de Elkana, kiu loĝis en la vilaĝoj de la Netofaanoj."],[9,17,"Kaj la pordegistoj: Ŝalum, Akub, Talmon, Aĥiman, kaj iliaj fratoj; Ŝalum estis la ĉefo.","Kaj la pordegistoj: Ŝalum, Akub, Talmon, Aĥiman, kaj iliaj fratoj; Ŝalum estis la ĉefo."],[9,18,"Kaj ĝis nun ĉe la reĝa pordego, oriente, ili estas pordegistoj el la anaro de la Levidoj.","Kaj ĝis nun ĉe la reĝa pordego, oriente, ili estas pordegistoj el la anaro de la Levidoj."],[9,19,"Ŝalum, filo de Kore, filo de Ebjasaf, filo de Koraĥ, kaj liaj fratoj el lia patrodomo, la Koraĥidoj, laŭ sia ofico estis gardistoj de la sojloj de la tabernaklo, kiel iliaj patroj ĉe la restejo de la Eternulo estis gardistoj de la eniro.","Ŝalum, filo de Kore, filo de Ebjasaf, filo de Koraĥ, kaj liaj fratoj el lia patrodomo, la Koraĥidoj, laŭ sia ofico estis gardistoj de la sojloj de la tabernaklo, kiel iliaj patroj ĉe la restejo de la Eternulo estis gardistoj de la eniro."],[9,20,"Pineĥas, filo de Eleazar, en la antaŭa tempo estis ilia estro, kaj la Eternulo estis kun li.","Pineĥas, filo de Eleazar, en la antaŭa tempo estis ilia estro, kaj la Eternulo estis kun li."],[9,21,"Zeĥarja, filo de Meŝelemja, estis pordisto ĉe la tabernaklo de kunveno.","Zeĥarja, filo de Meŝelemja, estis pordisto ĉe la tabernaklo de kunveno."],[9,22,"La tuta nombro de tiuj, kiuj estis elektitaj kiel pordegistoj ĉe la sojloj, estis ducent dek du. Ili estis enregistritaj laŭ siaj vilaĝoj. Ilin starigis David, kaj Samuel, la antaŭvidisto, pro ilia fideleco.","La tuta nombro de tiuj, kiuj estis elektitaj kiel pordegistoj ĉe la sojloj, estis ducent dek du. Ili estis enregistritaj laŭ siaj vilaĝoj. Ilin starigis David, kaj Samuel, la antaŭvidisto, pro ilia fideleco."],[9,23,"Ili kaj iliaj filoj estis gardistoj de la pordegoj en la domo de la Eternulo, la domo de la tabernaklo, laŭ deĵoroj.","Ili kaj iliaj filoj estis gardistoj de la pordegoj en la domo de la Eternulo, la domo de la tabernaklo, laŭ deĵoroj."],[9,24,"Ĉe la kvar flankoj estis la pordegistoj: oriente, okcidente, norde, kaj sude.","Ĉe la kvar flankoj estis la pordegistoj: oriente, okcidente, norde, kaj sude."],[9,25,"Iliaj fratoj estis en siaj vilaĝoj, kaj ili devis nur de tempo al tempo, unu fojon en sep tagoj, veni al ili.","Iliaj fratoj estis en siaj vilaĝoj, kaj ili devis nur de tempo al tempo, unu fojon en sep tagoj, veni al ili."],[9,26,"Ĉar konstante estis kvar estroj de pordegistoj, ili estis Levidoj; ili estis super la ĉambroj kaj super la trezoroj en la domo de Dio.","Ĉar konstante estis kvar estroj de pordegistoj, ili estis Levidoj; ili estis super la ĉambroj kaj super la trezoroj en la domo de Dio."],[9,27,"Ili noktadis ĉirkaŭ la domo de Dio, ĉar ili havis la devon gardi, kaj ili devis malfermi ĉiumatene.","Ili noktadis ĉirkaŭ la domo de Dio, ĉar ili havis la devon gardi, kaj ili devis malfermi ĉiumatene."],[9,28,"Parto el ili estis super ĉiuj vazoj de la servado, laŭkalkule ili enportadis kaj laŭkalkule elportadis.","Parto el ili estis super ĉiuj vazoj de la servado, laŭkalkule ili enportadis kaj laŭkalkule elportadis."],[9,29,"Parto el ili estis komisiita pri la ceteraj vazoj kaj pri ĉiuj sanktaj objektoj, pri la faruno, la vino, la oleo, la olibano, kaj la aromaĵoj.","Parto el ili estis komisiita pri la ceteraj vazoj kaj pri ĉiuj sanktaj objektoj, pri la faruno, la vino, la oleo, la olibano, kaj la aromaĵoj."],[9,30,"El la pastridoj kelkaj pretigadis la ŝmiraĵojn el aromaĵoj.","El la pastridoj kelkaj pretigadis la ŝmiraĵojn el aromaĵoj."],[9,31,"Al Matitja el la Levidoj, kiu estis unuenaskito de Ŝalum, Koraĥido, estis komisiitaj la aferoj de la patoj.","Al Matitja el la Levidoj, kiu estis unuenaskito de Ŝalum, Koraĥido, estis komisiitaj la aferoj de la patoj."],[9,32,"Al parto de la Kehatidoj, iliaj fratoj, estis komisiitaj la panoj de propono, kiujn ili devis pretigi por ĉiu sabato.","Al parto de la Kehatidoj, iliaj fratoj, estis komisiitaj la panoj de propono, kiujn ili devis pretigi por ĉiu sabato."],[9,33,"La kantistoj, ĉefoj de patrodomoj inter la Levidoj, estis liberaj de servado en la ĉambroj, ĉar tage kaj nokte ili devis sin okupadi per sia arto.","La kantistoj, ĉefoj de patrodomoj inter la Levidoj, estis liberaj de servado en la ĉambroj, ĉar tage kaj nokte ili devis sin okupadi per sia arto."],[9,34,"Tio estas la ĉefoj de patrodomoj de la Levidoj en siaj generacioj. Ili loĝis en Jerusalem.","Tio estas la ĉefoj de patrodomoj de la Levidoj en siaj generacioj. Ili loĝis en Jerusalem."],[9,35,"En Gibeon loĝis: Jeiel, la fondinto de Gibeon — la nomo de lia edzino estis Maaĥa —","En Gibeon loĝis: Jeiel, la fondinto de Gibeon — la nomo de lia edzino estis Maaĥa —"],[9,36,"kaj lia unuenaskita filo Abdon, kaj Cur, Kiŝ, Baal, Ner, Nadab,","kaj lia unuenaskita filo Abdon, kaj Cur, Kiŝ, Baal, Ner, Nadab,"],[9,37,"Gedor, Aĥjo, Zeĥarja, kaj Miklot.","Gedor, Aĥjo, Zeĥarja, kaj Miklot."],[9,38,"Miklot naskigis Ŝimamon. Ili ankaŭ apud siaj fratoj enloĝiĝis en Jerusalem kun siaj fratoj.","Miklot naskigis Ŝimamon. Ili ankaŭ apud siaj fratoj enloĝiĝis en Jerusalem kun siaj fratoj."],[9,39,"Ner naskigis Kiŝon, Kiŝ naskigis Saulon, Saul naskigis Jonatanon, Malki-Ŝuan, Abinadabon, kaj Eŝbaalon.","Ner naskigis Kiŝon, Kiŝ naskigis Saulon, Saul naskigis Jonatanon, Malki-Ŝuan, Abinadabon, kaj Eŝbaalon."],[9,40,"La filo de Jonatan estis Merib-Baal, kaj Merib-Baal naskigis Miĥan.","La filo de Jonatan estis Merib-Baal, kaj Merib-Baal naskigis Miĥan."],[9,41,"La filoj de Miĥa estis: Piton, Meleĥ, kaj Taĥrea,","La filoj de Miĥa estis: Piton, Meleĥ, kaj Taĥrea,"],[9,42,"kaj Aĥaz — li naskigis Jaaran, Jaara naskigis Alemeton, Azmaveton, kaj Zimrin; Zimri naskigis Mocan;","kaj Aĥaz — li naskigis Jaaran, Jaara naskigis Alemeton, Azmaveton, kaj Zimrin; Zimri naskigis Mocan;"],[9,43,"Moca naskigis Binean; lia filo estis Refaja, lia filo estis Eleasa, lia filo estis Acel.","Moca naskigis Binean; lia filo estis Refaja, lia filo estis Eleasa, lia filo estis Acel."],[9,44,"Acel havis ses filojn; jen estas iliaj nomoj: Azrikam, Boĥru, Iŝmael, Ŝearja, Obadja, kaj Ĥanan. Tio estis la filoj de Acel.","Acel havis ses filojn; jen estas iliaj nomoj: Azrikam, Boĥru, Iŝmael, Ŝearja, Obadja, kaj Ĥanan. Tio estis la filoj de Acel."],[10,1,"Dume la Filiŝtoj batalis kontraŭ Izrael; kaj la Izraelidoj forkuris de la Filiŝtoj, kaj falis mortigitaj sur la monto Gilboa.","Dume la Filiŝtoj batalis kontraŭ Izrael; kaj la Izraelidoj forkuris de la Filiŝtoj, kaj falis mortigitaj sur la monto Gilboa."],[10,2,"Kaj la Filiŝtoj kuratingis Saulon kaj liajn filojn; kaj la Filiŝtoj mortigis Jonatanon kaj Abinadabon kaj Malki-Ŝuan, filojn de Saul.","Kaj la Filiŝtoj kuratingis Saulon kaj liajn filojn; kaj la Filiŝtoj mortigis Jonatanon kaj Abinadabon kaj Malki-Ŝuan, filojn de Saul."],[10,3,"La batalo fortiĝis kontraŭ Saul; kaj la arkpafistoj trovis lin, kaj li estis vundita de la arkpafistoj.","La batalo fortiĝis kontraŭ Saul; kaj la arkpafistoj trovis lin, kaj li estis vundita de la arkpafistoj."],[10,4,"Tiam Saul diris al sia armilportisto: Eltiru vian glavon, kaj trapiku min per ĝi, por ke ne venu tiuj necirkumciditoj kaj ne mokmalhonoru min. Sed lia armilportisto ne volis, ĉar li forte timis. Tiam Saul prenis sian glavon kaj faligis sin sur ĝin.","Tiam Saul diris al sia armilportisto: Eltiru vian glavon, kaj trapiku min per ĝi, por ke ne venu tiuj necirkumciditoj kaj ne mokmalhonoru min. Sed lia armilportisto ne volis, ĉar li forte timis. Tiam Saul prenis sian glavon kaj faligis sin sur ĝin."],[10,5,"Kiam lia armilportisto vidis, ke Saul mortis, li ankaŭ faligis sin sur la glavon kaj mortis.","Kiam lia armilportisto vidis, ke Saul mortis, li ankaŭ faligis sin sur la glavon kaj mortis."],[10,6,"Tiamaniere mortis Saul kaj liaj tri filoj, kaj lia tuta domo kune mortis.","Tiamaniere mortis Saul kaj liaj tri filoj, kaj lia tuta domo kune mortis."],[10,7,"Kiam ĉiuj Izraelidoj, kiuj estis en la valo, vidis, ke oni forkuras kaj ke Saul kaj liaj filoj mortis, tiam ili forlasis siajn urbojn kaj forkuris; kaj venis la Filiŝtoj kaj enloĝiĝis en ili.","Kiam ĉiuj Izraelidoj, kiuj estis en la valo, vidis, ke oni forkuras kaj ke Saul kaj liaj filoj mortis, tiam ili forlasis siajn urbojn kaj forkuris; kaj venis la Filiŝtoj kaj enloĝiĝis en ili."],[10,8,"En la sekvanta tago venis la Filiŝtoj, por senvestigi la mortigitojn, kaj ili trovis Saulon kaj liajn filojn falintajn sur la monto Gilboa.","En la sekvanta tago venis la Filiŝtoj, por senvestigi la mortigitojn, kaj ili trovis Saulon kaj liajn filojn falintajn sur la monto Gilboa."],[10,9,"Kaj ili senvestigis lin kaj prenis lian kapon kaj liajn armilojn kaj sendis en la landon de la Filiŝtoj ĉirkaŭen, por anonci al iliaj idoloj kaj al la popolo.","Kaj ili senvestigis lin kaj prenis lian kapon kaj liajn armilojn kaj sendis en la landon de la Filiŝtoj ĉirkaŭen, por anonci al iliaj idoloj kaj al la popolo."],[10,10,"Kaj ili metis liajn armilojn en la domon de siaj dioj, kaj lian kranion ili alfiksis en la domo de Dagon.","Kaj ili metis liajn armilojn en la domon de siaj dioj, kaj lian kranion ili alfiksis en la domo de Dagon."],[10,11,"Kiam la tuta Jabeŝ en Gilead aŭdis pri ĉio, kion faris la Filiŝtoj al Saul,","Kiam la tuta Jabeŝ en Gilead aŭdis pri ĉio, kion faris la Filiŝtoj al Saul,"],[10,12,"tiam leviĝis ĉiuj kuraĝuloj, kaj prenis la korpon de Saul kaj la korpojn de liaj filoj kaj alportis lin en Jabeŝon, kaj enterigis iliajn ostojn sub la kverko en Jabeŝ, kaj fastis dum sep tagoj.","tiam leviĝis ĉiuj kuraĝuloj, kaj prenis la korpon de Saul kaj la korpojn de liaj filoj kaj alportis lin en Jabeŝon, kaj enterigis iliajn ostojn sub la kverko en Jabeŝ, kaj fastis dum sep tagoj."],[10,13,"Tiamaniere mortis Saul pro siaj malbonagoj, kiujn li faris antaŭ la Eternulo, ne plenumante la vorton de la Eternulo; ankaŭ pro tio, ke li turnis sin al antaŭdiristino, por demandi,","Tiamaniere mortis Saul pro siaj malbonagoj, kiujn li faris antaŭ la Eternulo, ne plenumante la vorton de la Eternulo; ankaŭ pro tio, ke li turnis sin al antaŭdiristino, por demandi,"],[10,14,"sed ne demandis la Eternulon. Pro tio Li mortigis lin, kaj transdonis la reĝadon al David, filo de Jiŝaj.","sed ne demandis la Eternulon. Pro tio Li mortigis lin, kaj transdonis la reĝadon al David, filo de Jiŝaj."],[11,1,"Kaj kunvenis ĉiuj Izraelidoj al David en Ĥebronon, kaj diris: Jen ni estas via osto kaj via karno.","Kaj kunvenis ĉiuj Izraelidoj al David en Ĥebronon, kaj diris: Jen ni estas via osto kaj via karno."],[11,2,"Ankaŭ hieraŭ kaj antaŭhieraŭ, kiam Saul estis ankoraŭ reĝo, vi elkondukadis kaj enkondukadis Izraelon; kaj la Eternulo, via Dio, diris al vi: Vi paŝtos Mian popolon Izrael, kaj vi estos estro de Mia popolo Izrael.","Ankaŭ hieraŭ kaj antaŭhieraŭ, kiam Saul estis ankoraŭ reĝo, vi elkondukadis kaj enkondukadis Izraelon; kaj la Eternulo, via Dio, diris al vi: Vi paŝtos Mian popolon Izrael, kaj vi estos estro de Mia popolo Izrael."],[11,3,"Kaj ĉiuj plejaĝuloj de Izrael venis al la reĝo en Ĥebronon, kaj David faris kun ili interligon en Ĥebron antaŭ la Eternulo; kaj ili sanktoleis Davidon reĝo super Izrael, konforme al la vorto de la Eternulo per Samuel.","Kaj ĉiuj plejaĝuloj de Izrael venis al la reĝo en Ĥebronon, kaj David faris kun ili interligon en Ĥebron antaŭ la Eternulo; kaj ili sanktoleis Davidon reĝo super Izrael, konforme al la vorto de la Eternulo per Samuel."],[11,4,"Kaj David kaj ĉiuj Izraelidoj iris en Jerusalemon (tio estas, en Jebuson). Tie la Jebusidoj estis la loĝantoj de la lando.","Kaj David kaj ĉiuj Izraelidoj iris en Jerusalemon (tio estas, en Jebuson). Tie la Jebusidoj estis la loĝantoj de la lando."],[11,5,"Kaj la loĝantoj de Jebus diris al David: Vi ne eniros ĉi tien. Sed David venkoprenis la fortikaĵon Cion, tio estas, la urbon de David.","Kaj la loĝantoj de Jebus diris al David: Vi ne eniros ĉi tien. Sed David venkoprenis la fortikaĵon Cion, tio estas, la urbon de David."],[11,6,"Kaj David diris: Kiu la unua venkobatos la Jebusidojn, tiu estos ĉefo kaj estro. Kaj la unua supreniris Joab, filo de Ceruja, kaj li fariĝis ĉefo.","Kaj David diris: Kiu la unua venkobatos la Jebusidojn, tiu estos ĉefo kaj estro. Kaj la unua supreniris Joab, filo de Ceruja, kaj li fariĝis ĉefo."],[11,7,"Kaj David ekloĝis en tiu fortikaĵo; pro tio oni donis al ĝi la nomon: Urbo de David.","Kaj David ekloĝis en tiu fortikaĵo; pro tio oni donis al ĝi la nomon: Urbo de David."],[11,8,"Kaj li ĉirkaŭkonstruis la urbon ĉiuflanke, de Milo en la tuta ĉirkaŭo; kaj Joab restarigis la ceterajn partojn de la urbo.","Kaj li ĉirkaŭkonstruis la urbon ĉiuflanke, de Milo en la tuta ĉirkaŭo; kaj Joab restarigis la ceterajn partojn de la urbo."],[11,9,"Kaj David fariĝadis ĉiam pli kaj pli granda, kaj la Eternulo Cebaot estis kun li.","Kaj David fariĝadis ĉiam pli kaj pli granda, kaj la Eternulo Cebaot estis kun li."],[11,10,"Jen estas la ĉefaj herooj, kiuj estis ĉe David, kaj kiuj tenis sin forte kun li dum lia reĝado, kune kun la tuta Izrael, por reĝigi lin super Izrael konforme al la vorto de la Eternulo.","Jen estas la ĉefaj herooj, kiuj estis ĉe David, kaj kiuj tenis sin forte kun li dum lia reĝado, kune kun la tuta Izrael, por reĝigi lin super Izrael konforme al la vorto de la Eternulo."],[11,11,"Jen estas la nombro de la herooj, kiuj estis ĉe David: Jaŝobeam, filo de Ĥaĥmoni, estro de la tridek; li levis sian lancon kontraŭ tricent kaj mortigis ilin per unu fojo.","Jen estas la nombro de la herooj, kiuj estis ĉe David: Jaŝobeam, filo de Ĥaĥmoni, estro de la tridek; li levis sian lancon kontraŭ tricent kaj mortigis ilin per unu fojo."],[11,12,"Post li estis Eleazar, filo de Dodo, la Aĥoĥido; li estis el la tri herooj.","Post li estis Eleazar, filo de Dodo, la Aĥoĥido; li estis el la tri herooj."],[11,13,"Li estis kun David en Pas-Damim, kie la Filiŝtoj kolektiĝis por batalo; tie estis kampoparto plena de hordeo; kaj la popolo forkuris antaŭ la Filiŝtoj.","Li estis kun David en Pas-Damim, kie la Filiŝtoj kolektiĝis por batalo; tie estis kampoparto plena de hordeo; kaj la popolo forkuris antaŭ la Filiŝtoj."],[11,14,"Sed tiuj stariĝis meze de la kampoparto, kaj savis ĝin kaj venkobatis la Filiŝtojn; kaj la Eternulo helpis per granda helpo.","Sed tiuj stariĝis meze de la kampoparto, kaj savis ĝin kaj venkobatis la Filiŝtojn; kaj la Eternulo helpis per granda helpo."],[11,15,"Kaj tri el la tridek ĉefoj iris sur la rokon al David, en la kavernon Adulam, dum la tendaro de la Filiŝtoj staris en la valo Refaim.","Kaj tri el la tridek ĉefoj iris sur la rokon al David, en la kavernon Adulam, dum la tendaro de la Filiŝtoj staris en la valo Refaim."],[11,16,"David tiam estis en la fortikaĵo, kaj la garnizono de la Filiŝtoj estis tiam en Bet-Leĥem.","David tiam estis en la fortikaĵo, kaj la garnizono de la Filiŝtoj estis tiam en Bet-Leĥem."],[11,17,"Kaj David esprimis deziron kaj diris: Kiu trinkigus al mi akvon el la puto Bet-Leĥema, kiu estas apud la pordego?","Kaj David esprimis deziron kaj diris: Kiu trinkigus al mi akvon el la puto Bet-Leĥema, kiu estas apud la pordego?"],[11,18,"Tiam tiuj tri trarompe penetris en la tendaron de la Filiŝtoj, ĉerpis akvon el la puto Bet-Leĥema, kiu estis apud la pordego, prenis kaj alportis al David. Sed David ne volis trinki ĝin; li elverŝis ĝin al la Eternulo,","Tiam tiuj tri trarompe penetris en la tendaron de la Filiŝtoj, ĉerpis akvon el la puto Bet-Leĥema, kiu estis apud la pordego, prenis kaj alportis al David. Sed David ne volis trinki ĝin; li elverŝis ĝin al la Eternulo,"],[11,19,"kaj diris: Gardu min mia Dio, ke mi ne faru tion: ĉu mi trinku la sangon de tiuj viroj, kiuj riskis sian vivon? ĉar kun risko por sia vivo ili alportis ĝin. Kaj li ne volis trinki ĝin. Tion faris la tri herooj.","kaj diris: Gardu min mia Dio, ke mi ne faru tion: ĉu mi trinku la sangon de tiuj viroj, kiuj riskis sian vivon? ĉar kun risko por sia vivo ili alportis ĝin. Kaj li ne volis trinki ĝin. Tion faris la tri herooj."],[11,20,"Abiŝaj, frato de Joab, estis estro de tiuj tri; li mortigis per sia lanco tricent homojn, kaj li havis gloran nomon inter la tri.","Abiŝaj, frato de Joab, estis estro de tiuj tri; li mortigis per sia lanco tricent homojn, kaj li havis gloran nomon inter la tri."],[11,21,"El la tri li estis honorata de du kaj estis ilia estro, sed en la trion li ne eniris.","El la tri li estis honorata de du kaj estis ilia estro, sed en la trion li ne eniris."],[11,22,"Benaja, filo de Jehojada, filo de homo kuraĝa, granda pro siaj faroj, el Kabceel: li mortigis la du fortulojn de Moab; li ankaŭ malsupreniris, kaj mortigis leonon en kavo en neĝa tago.","Benaja, filo de Jehojada, filo de homo kuraĝa, granda pro siaj faroj, el Kabceel: li mortigis la du fortulojn de Moab; li ankaŭ malsupreniris, kaj mortigis leonon en kavo en neĝa tago."],[11,23,"Li ankaŭ mortigis Egipton, viron, kiu havis la alton de kvin ulnoj; en la mano de la Egipto estis lanco kiel rultrabo de teksisto; li aliris al li kun bastono, elŝiris la lancon el la mano de la Egipto, kaj mortigis lin per lia propra lanco.","Li ankaŭ mortigis Egipton, viron, kiu havis la alton de kvin ulnoj; en la mano de la Egipto estis lanco kiel rultrabo de teksisto; li aliris al li kun bastono, elŝiris la lancon el la mano de la Egipto, kaj mortigis lin per lia propra lanco."],[11,24,"Tion faris Benaja, filo de Jehojada. Kaj li havis gloran nomon inter la tri herooj.","Tion faris Benaja, filo de Jehojada. Kaj li havis gloran nomon inter la tri herooj."],[11,25,"Inter la tridek li estis plej honorata, sed en la trion li ne eniris. Kaj David faris lin lia korpogardistestro.","Inter la tridek li estis plej honorata, sed en la trion li ne eniris. Kaj David faris lin lia korpogardistestro."],[11,26,"La ĉefaj militistoj estis: Asahel, frato de Joab, Elĥanan, filo de Dodo, el Bet-Leĥem,","La ĉefaj militistoj estis: Asahel, frato de Joab, Elĥanan, filo de Dodo, el Bet-Leĥem,"],[11,27,"Ŝamot, la Harorano, Ĥelec, la Pelonano,","Ŝamot, la Harorano, Ĥelec, la Pelonano,"],[11,28,"Ira, filo de Ikeŝ, la Tekoaano, Abiezer, la Anatotano,","Ira, filo de Ikeŝ, la Tekoaano, Abiezer, la Anatotano,"],[11,29,"Sibĥaj, la Ĥuŝaido, Ilaj, la Aĥoĥido,","Sibĥaj, la Ĥuŝaido, Ilaj, la Aĥoĥido,"],[11,30,"Maharaj, la Netofaano, Ĥeled, filo de Baana, la Netofaano,","Maharaj, la Netofaano, Ĥeled, filo de Baana, la Netofaano,"],[11,31,"Itaj, filo de Ribaj, el Gibea de la Benjamenidoj, Benaja, la Piratonano,","Itaj, filo de Ribaj, el Gibea de la Benjamenidoj, Benaja, la Piratonano,"],[11,32,"Ĥuraj, el Naĥale-Gaaŝ, Abiel, la Arbatano,","Ĥuraj, el Naĥale-Gaaŝ, Abiel, la Arbatano,"],[11,33,"Azmavet, la Baĥurimano, Eljaĥba, la Ŝaalbonano;","Azmavet, la Baĥurimano, Eljaĥba, la Ŝaalbonano;"],[11,34,"el la filoj de Haŝem, la Gizonano: Jonatan, filo de Ŝage, la Hararano,","el la filoj de Haŝem, la Gizonano: Jonatan, filo de Ŝage, la Hararano,"],[11,35,"Aĥiam, filo de Saĥar, la Hararano, Elifal, filo de Ur,","Aĥiam, filo de Saĥar, la Hararano, Elifal, filo de Ur,"],[11,36,"Ĥefer, la Meĥeratano, Aĥija, la Pelonano,","Ĥefer, la Meĥeratano, Aĥija, la Pelonano,"],[11,37,"Ĥecro, la Karmelano, Naaraj, filo de Ezbaj,","Ĥecro, la Karmelano, Naaraj, filo de Ezbaj,"],[11,38,"Joel, frato de Natan, Mibĥar, filo de Hagri,","Joel, frato de Natan, Mibĥar, filo de Hagri,"],[11,39,"Celek, la Amonido, Naĥaraj, la Beerotano, armilportisto de Joab, filo de Ceruja,","Celek, la Amonido, Naĥaraj, la Beerotano, armilportisto de Joab, filo de Ceruja,"],[11,40,"Ira, la Jetrido, Gareb, la Jetrido,","Ira, la Jetrido, Gareb, la Jetrido,"],[11,41,"Urija, la Ĥetido, Zabad, filo de Aĥlaj,","Urija, la Ĥetido, Zabad, filo de Aĥlaj,"],[11,42,"Adina, filo de Ŝiza, la Rubenido, ĉefo de Rubenidoj, kaj kun li estis tridek,","Adina, filo de Ŝiza, la Rubenido, ĉefo de Rubenidoj, kaj kun li estis tridek,"],[11,43,"Ĥanan, filo de Maaĥa, Joŝafat, la Mitnido,","Ĥanan, filo de Maaĥa, Joŝafat, la Mitnido,"],[11,44,"Uzija, la Aŝterotano, Ŝama kaj Jeiel, filoj de Ĥotam, la Aroerano,","Uzija, la Aŝterotano, Ŝama kaj Jeiel, filoj de Ĥotam, la Aroerano,"],[11,45,"Jediael, filo de Ŝimri, kaj lia frato Joĥa, la Ticano,","Jediael, filo de Ŝimri, kaj lia frato Joĥa, la Ticano,"],[11,46,"Eliel, la Maĥavido, Jeribaj kaj Joŝavja, filoj de Elnaam, Jitma, la Moabido,","Eliel, la Maĥavido, Jeribaj kaj Joŝavja, filoj de Elnaam, Jitma, la Moabido,"],[11,47,"Eliel, Obed, kaj Jaasiel el Mecobaja.","Eliel, Obed, kaj Jaasiel el Mecobaja."],[12,1,"Jen estas tiuj, kiuj venis al David en Ciklagon, kiam li estis ankoraŭ kaŝita antaŭ Saul, filo de Kiŝ; ili ankaŭ estis inter la herooj, helpantoj en la milito;","Jen estas tiuj, kiuj venis al David en Ciklagon, kiam li estis ankoraŭ kaŝita antaŭ Saul, filo de Kiŝ; ili ankaŭ estis inter la herooj, helpantoj en la milito;"],[12,2,"armitaj per pafarko, povosciantaj ĵeti ŝtonojn kaj pafarkajn sagojn per la dekstra mano kaj per la maldekstra, el la fratoj de Saul, Benjamenidoj:","armitaj per pafarko, povosciantaj ĵeti ŝtonojn kaj pafarkajn sagojn per la dekstra mano kaj per la maldekstra, el la fratoj de Saul, Benjamenidoj:"],[12,3,"la ĉefo Aĥiezer, kaj Joaŝ, filoj de Ŝemaa, la Gibeaano, Jeziel kaj Pelet, filoj de Azmavet, Beraĥa, kaj Jehu, la Anatotano,","la ĉefo Aĥiezer, kaj Joaŝ, filoj de Ŝemaa, la Gibeaano, Jeziel kaj Pelet, filoj de Azmavet, Beraĥa, kaj Jehu, la Anatotano,"],[12,4,"Jiŝmaja, la Gibeonano, heroo el tridek kaj super tridek, Jeremia, Jaĥaziel, Joĥanan, kaj Jozabad, la Gederaano,","Jiŝmaja, la Gibeonano, heroo el tridek kaj super tridek, Jeremia, Jaĥaziel, Joĥanan, kaj Jozabad, la Gederaano,"],[12,5,"Eluzaj, Jerimot, Bealja, Ŝemarja, kaj Ŝefatja, la Ĥarufano,","Eluzaj, Jerimot, Bealja, Ŝemarja, kaj Ŝefatja, la Ĥarufano,"],[12,6,"Elkana, Jiŝija, Azarel, Joezer, kaj Jaŝobeam, la Koraĥidoj,","Elkana, Jiŝija, Azarel, Joezer, kaj Jaŝobeam, la Koraĥidoj,"],[12,7,"Joela kaj Zebadja, filoj de Jeroĥam, el Gedor.","Joela kaj Zebadja, filoj de Jeroĥam, el Gedor."],[12,8,"El la Gadidoj apartiĝis al David en la fortikigitan lokon en la dezerto kuraĝaj militistoj, kapablaj batalistoj, armitaj per ŝildo kaj lanco; iliaj vizaĝoj estis kiel vizaĝo de leono, kaj rapidkuraj ili estis, kiel gazeloj sur la montoj:","El la Gadidoj apartiĝis al David en la fortikigitan lokon en la dezerto kuraĝaj militistoj, kapablaj batalistoj, armitaj per ŝildo kaj lanco; iliaj vizaĝoj estis kiel vizaĝo de leono, kaj rapidkuraj ili estis, kiel gazeloj sur la montoj:"],[12,9,"Ezer estis la ĉefo, Obadja la dua, Eliab la tria,","Ezer estis la ĉefo, Obadja la dua, Eliab la tria,"],[12,10,"Miŝmana la kvara, Jeremia la kvina,","Miŝmana la kvara, Jeremia la kvina,"],[12,11,"Ataj la sesa, Eliel la sepa,","Ataj la sesa, Eliel la sepa,"],[12,12,"Joĥanan la oka, Elzabad la naŭa,","Joĥanan la oka, Elzabad la naŭa,"],[12,13,"Jeremia la deka, Maĥbanaj la dek-unua.","Jeremia la deka, Maĥbanaj la dek-unua."],[12,14,"Ĉi tiuj el la Gadidoj estis ĉefoj en la militistaro: la plej malgranda estis super cent, kaj la plej granda super mil.","Ĉi tiuj el la Gadidoj estis ĉefoj en la militistaro: la plej malgranda estis super cent, kaj la plej granda super mil."],[12,15,"Ili estis tiuj, kiuj transiris Jordanon en la unua monato, kiam ĝi inundis siajn ambaŭ bordojn, kaj ili dispelis ĉiujn loĝantojn de la valoj orienten kaj okcidenten.","Ili estis tiuj, kiuj transiris Jordanon en la unua monato, kiam ĝi inundis siajn ambaŭ bordojn, kaj ili dispelis ĉiujn loĝantojn de la valoj orienten kaj okcidenten."],[12,16,"Ankaŭ el la idoj de Benjamen kaj de Jehuda oni venis en la fortikigitan lokon al David.","Ankaŭ el la idoj de Benjamen kaj de Jehuda oni venis en la fortikigitan lokon al David."],[12,17,"Kaj David eliris renkonte al ili, kaj ekparolis kaj diris al ili: Se vi venis al mi kun paco, por helpi al mi, mia koro estos kun vi; sed se por ruze transdoni min al miaj malamikoj, kvankam miaj manoj estas senkulpaj, tiam vidu tion Dio de niaj patroj, kaj Li juĝu.","Kaj David eliris renkonte al ili, kaj ekparolis kaj diris al ili: Se vi venis al mi kun paco, por helpi al mi, mia koro estos kun vi; sed se por ruze transdoni min al miaj malamikoj, kvankam miaj manoj estas senkulpaj, tiam vidu tion Dio de niaj patroj, kaj Li juĝu."],[12,18,"Kaj spirito venis sur Amasajon, la estron de la herooj, kaj li diris: Al vi, ho David, kaj kun vi, ho filo de Jiŝaj, estu paco; paco al vi, kaj paco al viaj helpantoj, ĉar al vi helpas via Dio. Kaj David ilin akceptis kaj faris ilin ĉefoj de la militistoj.","Kaj spirito venis sur Amasajon, la estron de la herooj, kaj li diris: Al vi, ho David, kaj kun vi, ho filo de Jiŝaj, estu paco; paco al vi, kaj paco al viaj helpantoj, ĉar al vi helpas via Dio. Kaj David ilin akceptis kaj faris ilin ĉefoj de la militistoj."],[12,19,"Ankaŭ el la Manaseidoj oni aliĝis al David, kiam li iris kun la Filiŝtoj milite kontraŭ Saulon, sed ne helpis al ili; ĉar post konsiliĝo la estroj de la Filiŝtoj forsendis lin, dirante: Kun niaj kapoj li aliĝos al sia sinjoro Saul.","Ankaŭ el la Manaseidoj oni aliĝis al David, kiam li iris kun la Filiŝtoj milite kontraŭ Saulon, sed ne helpis al ili; ĉar post konsiliĝo la estroj de la Filiŝtoj forsendis lin, dirante: Kun niaj kapoj li aliĝos al sia sinjoro Saul."],[12,20,"Kiam li venis en Ciklagon, aliĝis al li el la Manaseidoj: Adnaĥ, Jozabad, Jediael, Miĥael, Jozabad, Elihu, kaj Ciltaj, milestroj de la Manaseidoj.","Kiam li venis en Ciklagon, aliĝis al li el la Manaseidoj: Adnaĥ, Jozabad, Jediael, Miĥael, Jozabad, Elihu, kaj Ciltaj, milestroj de la Manaseidoj."],[12,21,"Kaj ili helpis al David kontraŭ la militistoj, ĉar ili ĉiuj estis herooj, kaj ili estis estroj en militistaro.","Kaj ili helpis al David kontraŭ la militistoj, ĉar ili ĉiuj estis herooj, kaj ili estis estroj en militistaro."],[12,22,"Ĉiutage oni venis pli al David, por helpi al li, ĝis kolektiĝis granda armeo, kiel armeo de Dio.","Ĉiutage oni venis pli al David, por helpi al li, ĝis kolektiĝis granda armeo, kiel armeo de Dio."],[12,23,"Jen estas la nombro de la ĉefaj armitaj militistoj, kiuj venis al David en Ĥebronon, por transdoni al li la regnon de Saul, konforme al la vorto de la Eternulo:","Jen estas la nombro de la ĉefaj armitaj militistoj, kiuj venis al David en Ĥebronon, por transdoni al li la regnon de Saul, konforme al la vorto de la Eternulo:"],[12,24,"da Jehudaidoj, portantaj ŝildon kaj lancon, estis ses mil okcent armitaj por la militistaro;","da Jehudaidoj, portantaj ŝildon kaj lancon, estis ses mil okcent armitaj por la militistaro;"],[12,25,"el la Simeonidoj, batalkapablaj por la militistaro, estis sep mil cent;","el la Simeonidoj, batalkapablaj por la militistaro, estis sep mil cent;"],[12,26,"el la Levidoj estis kvar mil sescent;","el la Levidoj estis kvar mil sescent;"],[12,27,"kaj Jehojada, estro de Aaronidoj, kaj kun li tri mil sepcent;","kaj Jehojada, estro de Aaronidoj, kaj kun li tri mil sepcent;"],[12,28,"kaj Cadok, kuraĝa junulo, kaj lia patrodomo, dudek du estroj;","kaj Cadok, kuraĝa junulo, kaj lia patrodomo, dudek du estroj;"],[12,29,"el la Benjamenidoj, samtribanoj de Saul, tri mil; ĝis tiam la plimulto el ili fidele servis al la domo de Saul;","el la Benjamenidoj, samtribanoj de Saul, tri mil; ĝis tiam la plimulto el ili fidele servis al la domo de Saul;"],[12,30,"el la Efraimidoj dudek mil okcent kuraĝaj militistoj, viroj famaj en siaj patrodomoj;","el la Efraimidoj dudek mil okcent kuraĝaj militistoj, viroj famaj en siaj patrodomoj;"],[12,31,"el la duontribo de Manase dek ok mil, kiuj estis vokitaj laŭnome, por iri reĝigi Davidon;","el la duontribo de Manase dek ok mil, kiuj estis vokitaj laŭnome, por iri reĝigi Davidon;"],[12,32,"el la Isaĥaridoj, kiuj komprenis la cirkonstancojn, kaj sciis, kion Izrael devas fari, estis ducent ĉefoj, kaj ĉiuj iliaj fratoj agis laŭ iliaj vortoj;","el la Isaĥaridoj, kiuj komprenis la cirkonstancojn, kaj sciis, kion Izrael devas fari, estis ducent ĉefoj, kaj ĉiuj iliaj fratoj agis laŭ iliaj vortoj;"],[12,33,"el la Zebulunidoj, militkapablaj, kaj irantaj en militon kun ĉiaj bataliloj, estis kvindek mil, por enviciĝi en konkordo;","el la Zebulunidoj, militkapablaj, kaj irantaj en militon kun ĉiaj bataliloj, estis kvindek mil, por enviciĝi en konkordo;"],[12,34,"el la Naftaliidoj estis mil estroj, kaj kun ili tridek sep mil kun ŝildoj kaj lancoj;","el la Naftaliidoj estis mil estroj, kaj kun ili tridek sep mil kun ŝildoj kaj lancoj;"],[12,35,"el la Danidoj, armitaj por milito, estis dudek ok mil sescent;","el la Danidoj, armitaj por milito, estis dudek ok mil sescent;"],[12,36,"el la Aŝeridoj, militkapablaj kaj pretaj por milito, kvardek mil;","el la Aŝeridoj, militkapablaj kaj pretaj por milito, kvardek mil;"],[12,37,"de trans Jordan, el la Rubenidoj, la Gadidoj, kaj la duontribo de Manase, kun ĉiaj militaj bataliloj, cent dudek mil.","de trans Jordan, el la Rubenidoj, la Gadidoj, kaj la duontribo de Manase, kun ĉiaj militaj bataliloj, cent dudek mil."],[12,38,"Ĉiuj tiuj militistoj, prezentantaj aranĝitajn vicojn, venis plenkore en Ĥebronon, por fari Davidon reĝo super la tuta Izrael; ankaŭ ĉiuj ceteraj Izraelidoj estis unuanimaj, por reĝigi Davidon.","Ĉiuj tiuj militistoj, prezentantaj aranĝitajn vicojn, venis plenkore en Ĥebronon, por fari Davidon reĝo super la tuta Izrael; ankaŭ ĉiuj ceteraj Izraelidoj estis unuanimaj, por reĝigi Davidon."],[12,39,"Kaj ili restis tie kun David dum tri tagoj, manĝis kaj trinkis; ĉar iliaj fratoj pretigis por ili;","Kaj ili restis tie kun David dum tri tagoj, manĝis kaj trinkis; ĉar iliaj fratoj pretigis por ili;"],[12,40,"ankaŭ tiuj, kiuj estis proksime de ili, ĝis Isaĥar, Zebulun, kaj Naftali, alportadis al ili sur azenoj, kameloj, muloj, kaj bovoj manĝaĵon el faruno, premitajn figojn, sekvinberojn, vinon, oleon, bovojn, kaj ŝafojn en granda kvanto; ĉar estis ĝojo en Izrael.","ankaŭ tiuj, kiuj estis proksime de ili, ĝis Isaĥar, Zebulun, kaj Naftali, alportadis al ili sur azenoj, kameloj, muloj, kaj bovoj manĝaĵon el faruno, premitajn figojn, sekvinberojn, vinon, oleon, bovojn, kaj ŝafojn en granda kvanto; ĉar estis ĝojo en Izrael."],[13,1,"David konsiliĝis kun la milestroj, centestroj, kaj ĉiuj ĉefoj;","David konsiliĝis kun la milestroj, centestroj, kaj ĉiuj ĉefoj;"],[13,2,"kaj David diris al la tuta komunumo de Izrael: Se plaĉas al vi, kaj se tio estas de la Eternulo, nia Dio, ni dissendu ĉiuflanken al ĉiuj ceteraj niaj fratoj en ĉiujn regionojn de Izrael, kaj samtempe al la pastroj kaj Levidoj en la urbojn de ilia loĝado, ke ili kolektiĝu al ni;","kaj David diris al la tuta komunumo de Izrael: Se plaĉas al vi, kaj se tio estas de la Eternulo, nia Dio, ni dissendu ĉiuflanken al ĉiuj ceteraj niaj fratoj en ĉiujn regionojn de Izrael, kaj samtempe al la pastroj kaj Levidoj en la urbojn de ilia loĝado, ke ili kolektiĝu al ni;"],[13,3,"kaj ni transportu al ni la keston de nia Dio, ĉar ni ne turnis nin al Li en la tempo de Saul.","kaj ni transportu al ni la keston de nia Dio, ĉar ni ne turnis nin al Li en la tempo de Saul."],[13,4,"Kaj la tuta komunumo diris, ke oni tiel agu; ĉar la afero plaĉis al la tuta popolo.","Kaj la tuta komunumo diris, ke oni tiel agu; ĉar la afero plaĉis al la tuta popolo."],[13,5,"Tiam David kolektis la tutan Izraelon, de Ŝiĥor la Egipta ĝis Ĥamat, por ke oni venigu la keston de Dio el Kirjat-Jearim.","Tiam David kolektis la tutan Izraelon, de Ŝiĥor la Egipta ĝis Ĥamat, por ke oni venigu la keston de Dio el Kirjat-Jearim."],[13,6,"Kaj David kun la tuta Izrael iris en Baalan, en Kirjat-Jearimon, kiu troviĝas en Judujo, por venigi de tie la keston de Dio, de la Eternulo, kiu sidas sur la keruboj, kie estas vokata Lia nomo.","Kaj David kun la tuta Izrael iris en Baalan, en Kirjat-Jearimon, kiu troviĝas en Judujo, por venigi de tie la keston de Dio, de la Eternulo, kiu sidas sur la keruboj, kie estas vokata Lia nomo."],[13,7,"Kaj oni veturigis la keston de Dio sur nova veturilo el la domo de Abinadab, kaj Uza kaj Aĥjo kondukis la veturilon.","Kaj oni veturigis la keston de Dio sur nova veturilo el la domo de Abinadab, kaj Uza kaj Aĥjo kondukis la veturilon."],[13,8,"Kaj David kaj ĉiuj Izraelidoj ludis antaŭ Dio per la tuta forto, kun kantoj, harpoj, psalteroj, tamburinoj, cimbaloj, kaj trumpetoj.","Kaj David kaj ĉiuj Izraelidoj ludis antaŭ Dio per la tuta forto, kun kantoj, harpoj, psalteroj, tamburinoj, cimbaloj, kaj trumpetoj."],[13,9,"Kiam ili alvenis al la draŝejo de Kidon, Uza etendis sian manon, por subteni la keston, ĉar la bovoj klinpuŝis ĝin.","Kiam ili alvenis al la draŝejo de Kidon, Uza etendis sian manon, por subteni la keston, ĉar la bovoj klinpuŝis ĝin."],[13,10,"Tiam ekflamis la kolero de la Eternulo kontraŭ Uza, kaj Li mortigis lin pro tio, ke li etendis sian manon al la kesto; kaj li mortis tie antaŭ Dio.","Tiam ekflamis la kolero de la Eternulo kontraŭ Uza, kaj Li mortigis lin pro tio, ke li etendis sian manon al la kesto; kaj li mortis tie antaŭ Dio."],[13,11,"Kaj afliktiĝis David pro tio, ke la Eternulo frapis Uzan, kaj li donis al tiu loko la nomon Perec-Uza, ĝis la nuna tago.","Kaj afliktiĝis David pro tio, ke la Eternulo frapis Uzan, kaj li donis al tiu loko la nomon Perec-Uza, ĝis la nuna tago."],[13,12,"Kaj David ektimis Dion en tiu tago, kaj diris: Kiamaniere mi enportos al mi la keston de Dio?","Kaj David ektimis Dion en tiu tago, kaj diris: Kiamaniere mi enportos al mi la keston de Dio?"],[13,13,"Kaj David ne transportigis la keston al si, en la urbon de David, sed li direktis ĝin en la domon de Obed-Edom, la Gatano.","Kaj David ne transportigis la keston al si, en la urbon de David, sed li direktis ĝin en la domon de Obed-Edom, la Gatano."],[13,14,"Kaj la kesto de Dio restis kun la familio de Obed-Edom en lia domo dum tri monatoj; kaj la Eternulo benis la domon de Obed-Edom, kaj ĉion, kio apartenis al li.","Kaj la kesto de Dio restis kun la familio de Obed-Edom en lia domo dum tri monatoj; kaj la Eternulo benis la domon de Obed-Edom, kaj ĉion, kio apartenis al li."],[14,1,"Ĥiram, reĝo de Tiro, sendis al David senditojn, kaj cedran lignon, kaj masonistojn kaj ĉarpentistojn, por ke ili konstruu por li domon.","Ĥiram, reĝo de Tiro, sendis al David senditojn, kaj cedran lignon, kaj masonistojn kaj ĉarpentistojn, por ke ili konstruu por li domon."],[14,2,"Kaj David konsciis, ke la Eternulo fortikigis lin kiel reĝon super Izrael, ke lia regno leviĝis alte pro Lia popolo Izrael.","Kaj David konsciis, ke la Eternulo fortikigis lin kiel reĝon super Izrael, ke lia regno leviĝis alte pro Lia popolo Izrael."],[14,3,"Kaj David prenis ankoraŭ edzinojn en Jerusalem, kaj David naskigis ankoraŭ filojn kaj filinojn.","Kaj David prenis ankoraŭ edzinojn en Jerusalem, kaj David naskigis ankoraŭ filojn kaj filinojn."],[14,4,"Kaj jen estas la nomoj de tiuj, kiuj naskiĝis al li en Jerusalem: Ŝamua kaj Ŝobab, Natan kaj Salomono","Kaj jen estas la nomoj de tiuj, kiuj naskiĝis al li en Jerusalem: Ŝamua kaj Ŝobab, Natan kaj Salomono"],[14,5,"kaj Jibĥar kaj Eliŝua kaj Elpelet","kaj Jibĥar kaj Eliŝua kaj Elpelet"],[14,6,"kaj Noga kaj Nefeg kaj Jafia","kaj Noga kaj Nefeg kaj Jafia"],[14,7,"kaj Eliŝama kaj Beeljada kaj Elifelet.","kaj Eliŝama kaj Beeljada kaj Elifelet."],[14,8,"Kiam la Filiŝtoj aŭdis, ke David estas oleita kiel reĝo super la tuta Izrael, tiam ĉiuj Filiŝtoj iris, por serĉi Davidon. David aŭdis pri tio, kaj li eliris kontraŭ ilin.","Kiam la Filiŝtoj aŭdis, ke David estas oleita kiel reĝo super la tuta Izrael, tiam ĉiuj Filiŝtoj iris, por serĉi Davidon. David aŭdis pri tio, kaj li eliris kontraŭ ilin."],[14,9,"Kaj la Filiŝtoj venis kaj okupis la valon Refaim.","Kaj la Filiŝtoj venis kaj okupis la valon Refaim."],[14,10,"Kaj David demandis Dion, dirante: Ĉu mi iru kontraŭ la Filiŝtojn? kaj ĉu Vi transdonos ilin en mian manon? Kaj la Eternulo diris al li: Iru, ĉar Mi transdonos ilin en vian manon.","Kaj David demandis Dion, dirante: Ĉu mi iru kontraŭ la Filiŝtojn? kaj ĉu Vi transdonos ilin en mian manon? Kaj la Eternulo diris al li: Iru, ĉar Mi transdonos ilin en vian manon."],[14,11,"Kaj ili iris al Baal-Peracim, kaj David venkobatis ilin tie. Kaj David diris: Dio disbatis miajn malamikojn per mia mano, kiel oni disbatas akvon. Tial oni donis al tiu loko la nomon Baal-Peracim.","Kaj ili iris al Baal-Peracim, kaj David venkobatis ilin tie. Kaj David diris: Dio disbatis miajn malamikojn per mia mano, kiel oni disbatas akvon. Tial oni donis al tiu loko la nomon Baal-Peracim."],[14,12,"Kaj ili lasis tie siajn diojn; kaj David ordonis, ke oni forbruligu ilin per fajro.","Kaj ili lasis tie siajn diojn; kaj David ordonis, ke oni forbruligu ilin per fajro."],[14,13,"Kaj denove venis la Filiŝtoj kaj okupis la valon.","Kaj denove venis la Filiŝtoj kaj okupis la valon."],[14,14,"Tiam David denove demandis Dion, kaj Dio diris al li: Ne iru post ili, deturnu vin de ili, kaj venu al ili de la flanko de la morusarboj;","Tiam David denove demandis Dion, kaj Dio diris al li: Ne iru post ili, deturnu vin de ili, kaj venu al ili de la flanko de la morusarboj;"],[14,15,"kaj kiam vi ekaŭdos la sonon de paŝoj sur la supro de la morusarboj, tiam komencu la batalon; ĉar Dio eliris antaŭ vi, por frapi la tendaron de la Filiŝtoj.","kaj kiam vi ekaŭdos la sonon de paŝoj sur la supro de la morusarboj, tiam komencu la batalon; ĉar Dio eliris antaŭ vi, por frapi la tendaron de la Filiŝtoj."],[14,16,"Kaj David faris, kiel ordonis al li Dio; kaj ili venkobatis la tendaron de la Filiŝtoj de Gibeon ĝis Gezer.","Kaj David faris, kiel ordonis al li Dio; kaj ili venkobatis la tendaron de la Filiŝtoj de Gibeon ĝis Gezer."],[14,17,"Kaj la nomo de David fariĝis fama en ĉiuj landoj; kaj la Eternulo faris lin timata de ĉiuj nacioj.","Kaj la nomo de David fariĝis fama en ĉiuj landoj; kaj la Eternulo faris lin timata de ĉiuj nacioj."],[15,1,"Li konstruis al si domojn en la urbo de David, kaj pretigis lokon por la kesto de Dio, kaj etendis tendon super ĝi.","Li konstruis al si domojn en la urbo de David, kaj pretigis lokon por la kesto de Dio, kaj etendis tendon super ĝi."],[15,2,"Tiam David diris: Neniu portu la keston de Dio krom la Levidoj; ĉar ilin la Eternulo elektis, por ke ili portu la keston de Dio kaj servu al Li eterne.","Tiam David diris: Neniu portu la keston de Dio krom la Levidoj; ĉar ilin la Eternulo elektis, por ke ili portu la keston de Dio kaj servu al Li eterne."],[15,3,"Kaj David kunvenigis ĉiujn Izraelidojn en Jerusalemon, por porti la keston de la Eternulo sur ĝian lokon, kiun li pretigis por ĝi.","Kaj David kunvenigis ĉiujn Izraelidojn en Jerusalemon, por porti la keston de la Eternulo sur ĝian lokon, kiun li pretigis por ĝi."],[15,4,"Kaj David kunvenigis la idojn de Aaron kaj la Levidojn:","Kaj David kunvenigis la idojn de Aaron kaj la Levidojn:"],[15,5,"el la idoj de Kehat estis: la estro Uriel kaj liaj fratoj, cent dudek;","el la idoj de Kehat estis: la estro Uriel kaj liaj fratoj, cent dudek;"],[15,6,"el la idoj de Merari: la estro Asaja kaj liaj fratoj, ducent dudek;","el la idoj de Merari: la estro Asaja kaj liaj fratoj, ducent dudek;"],[15,7,"el la idoj de Gerŝon: la estro Joel kaj liaj fratoj, cent tridek;","el la idoj de Gerŝon: la estro Joel kaj liaj fratoj, cent tridek;"],[15,8,"el la idoj de Elicafan: la estro Ŝemaja kaj liaj fratoj, ducent;","el la idoj de Elicafan: la estro Ŝemaja kaj liaj fratoj, ducent;"],[15,9,"el la idoj de Ĥebron: la estro Eliel kaj liaj fratoj, okdek;","el la idoj de Ĥebron: la estro Eliel kaj liaj fratoj, okdek;"],[15,10,"el la idoj de Uziel: la estro Aminadab kaj liaj fratoj, cent dek du.","el la idoj de Uziel: la estro Aminadab kaj liaj fratoj, cent dek du."],[15,11,"Kaj David alvokis la pastrojn Cadok kaj Ebjatar, kaj la Levidojn Uriel, Asaja, Joel, Ŝemaja, Eliel, kaj Aminadab;","Kaj David alvokis la pastrojn Cadok kaj Ebjatar, kaj la Levidojn Uriel, Asaja, Joel, Ŝemaja, Eliel, kaj Aminadab;"],[15,12,"kaj li diris al ili: Vi, ĉefoj de patrodomoj de la Levidoj, sanktigu vin kaj viajn fratojn, kaj alportu la keston de la Eternulo, Dio de Izrael, sur la lokon, kiun mi pretigis por ĝi;","kaj li diris al ili: Vi, ĉefoj de patrodomoj de la Levidoj, sanktigu vin kaj viajn fratojn, kaj alportu la keston de la Eternulo, Dio de Izrael, sur la lokon, kiun mi pretigis por ĝi;"],[15,13,"ĉar antaŭe, kiam ne vi tion faris, la Eternulo, nia Dio, frapis nin pro tio, ke ni serĉis Lin ne tiel, kiel oni devas.","ĉar antaŭe, kiam ne vi tion faris, la Eternulo, nia Dio, frapis nin pro tio, ke ni serĉis Lin ne tiel, kiel oni devas."],[15,14,"Kaj sanktigis sin la pastroj kaj la Levidoj, por porti la keston de la Eternulo, Dio de Izrael.","Kaj sanktigis sin la pastroj kaj la Levidoj, por porti la keston de la Eternulo, Dio de Izrael."],[15,15,"Kaj la idoj de Levi ekportis la keston de Dio, kiel ordonis Moseo laŭ la vorto de la Eternulo, sur siaj ŝultroj, per stangoj sur ili.","Kaj la idoj de Levi ekportis la keston de Dio, kiel ordonis Moseo laŭ la vorto de la Eternulo, sur siaj ŝultroj, per stangoj sur ili."],[15,16,"Kaj David diris al la estroj de la Levidoj, ke ili starigu siajn fratojn la kantistojn kun muzikaj instrumentoj, psalteroj, harpoj, kaj laŭtaj cimbaloj, por ke alte aŭdiĝu la sonoj de ĝojo.","Kaj David diris al la estroj de la Levidoj, ke ili starigu siajn fratojn la kantistojn kun muzikaj instrumentoj, psalteroj, harpoj, kaj laŭtaj cimbaloj, por ke alte aŭdiĝu la sonoj de ĝojo."],[15,17,"Kaj la Levidoj starigis Hemanon, filon de Joel, kaj el liaj fratoj Asafon, filon de Bereĥja, kaj el la idoj de Merari, siaj fratoj, Etanon, filon de Kuŝaja;","Kaj la Levidoj starigis Hemanon, filon de Joel, kaj el liaj fratoj Asafon, filon de Bereĥja, kaj el la idoj de Merari, siaj fratoj, Etanon, filon de Kuŝaja;"],[15,18,"kaj kun ili iliajn duagradajn fratojn: Zeĥarja, Ben, Jaaziel, Ŝemiramot, Jeĥiel, Uni, Eliab, Benaja, Maaseja, Matitja, Eliflehu, Mikneja, Obed-Edom, kaj Jeiel, kiel pordegistojn.","kaj kun ili iliajn duagradajn fratojn: Zeĥarja, Ben, Jaaziel, Ŝemiramot, Jeĥiel, Uni, Eliab, Benaja, Maaseja, Matitja, Eliflehu, Mikneja, Obed-Edom, kaj Jeiel, kiel pordegistojn."],[15,19,"La kantistoj Heman, Asaf, kaj Etan estis por ludado sur kupraj cimbaloj;","La kantistoj Heman, Asaf, kaj Etan estis por ludado sur kupraj cimbaloj;"],[15,20,"Zeĥarja, Aziel, Ŝemiramot, Jeĥiel, Uni, Eliab, Maaseja, kaj Benaja — sur psalteroj, por sopranuloj;","Zeĥarja, Aziel, Ŝemiramot, Jeĥiel, Uni, Eliab, Maaseja, kaj Benaja — sur psalteroj, por sopranuloj;"],[15,21,"Matitja, Eliflehu, Mikneja, Obed-Edom, Jeiel, kaj Azazja — sur harpoj, por basuloj, por antaŭkanti;","Matitja, Eliflehu, Mikneja, Obed-Edom, Jeiel, kaj Azazja — sur harpoj, por basuloj, por antaŭkanti;"],[15,22,"Kenanja, la estro de la Levidoj — por aranĝado; li aranĝadis la muzikon, ĉar li estis kompetentulo.","Kenanja, la estro de la Levidoj — por aranĝado; li aranĝadis la muzikon, ĉar li estis kompetentulo."],[15,23,"Bereĥja kaj Elkana estis pordogardistoj ĉe la kesto;","Bereĥja kaj Elkana estis pordogardistoj ĉe la kesto;"],[15,24,"Ŝebanja, Joŝafat, Netanel, Amasaj, Zeĥarja, Benaja, kaj Eliezer, la pastroj, trumpetadis per trumpetoj antaŭ la kesto de Dio; Obed-Edom kaj Jeĥija estis pordogardistoj ĉe la kesto.","Ŝebanja, Joŝafat, Netanel, Amasaj, Zeĥarja, Benaja, kaj Eliezer, la pastroj, trumpetadis per trumpetoj antaŭ la kesto de Dio; Obed-Edom kaj Jeĥija estis pordogardistoj ĉe la kesto."],[15,25,"Tiamaniere iris David kaj la plejaĝuloj de Izrael kaj la milestroj, por transporti kun ĝojo la keston de interligo de la Eternulo el la domo de Obed-Edom.","Tiamaniere iris David kaj la plejaĝuloj de Izrael kaj la milestroj, por transporti kun ĝojo la keston de interligo de la Eternulo el la domo de Obed-Edom."],[15,26,"Kaj kiam Dio helpis al la Levidoj, kiuj portis la keston de interligo de la Eternulo, oni oferbuĉis sep bovojn kaj sep ŝafojn.","Kaj kiam Dio helpis al la Levidoj, kiuj portis la keston de interligo de la Eternulo, oni oferbuĉis sep bovojn kaj sep ŝafojn."],[15,27,"David estis vestita per tuniko el delikata tolo, ankaŭ ĉiuj Levidoj, kiuj portis la keston, la kantistoj, kaj Kenanja, la estro de aranĝado de la ĥoroj; David ankaŭ havis sur si linan efodon.","David estis vestita per tuniko el delikata tolo, ankaŭ ĉiuj Levidoj, kiuj portis la keston, la kantistoj, kaj Kenanja, la estro de aranĝado de la ĥoroj; David ankaŭ havis sur si linan efodon."],[15,28,"Kaj ĉiuj Izraelidoj akompanis la keston de interligo de la Eternulo, kun ĝojkrioj, kun sonado de korno, kun trumpetoj, laŭtaj cimbaloj, psalteroj, kaj harpoj.","Kaj ĉiuj Izraelidoj akompanis la keston de interligo de la Eternulo, kun ĝojkrioj, kun sonado de korno, kun trumpetoj, laŭtaj cimbaloj, psalteroj, kaj harpoj."],[15,29,"Kiam la kesto de interligo de la Eternulo venis al la urbo de David, Miĥal, filino de Saul, rigardis tra la fenestro; kaj kiam ŝi vidis, ke la reĝo David saltas kaj ludas, ŝi ekmalestimis lin en sia koro.","Kiam la kesto de interligo de la Eternulo venis al la urbo de David, Miĥal, filino de Saul, rigardis tra la fenestro; kaj kiam ŝi vidis, ke la reĝo David saltas kaj ludas, ŝi ekmalestimis lin en sia koro."],[16,1,"Kaj oni alportis la keston de Dio, kaj metis ĝin interne de la tendo, kiun David starigis por ĝi; kaj oni alportis bruloferojn kaj pacoferojn antaŭ Dion.","Kaj oni alportis la keston de Dio, kaj metis ĝin interne de la tendo, kiun David starigis por ĝi; kaj oni alportis bruloferojn kaj pacoferojn antaŭ Dion."],[16,2,"Kiam David finis la oferadon de la bruloferoj kaj de la pacoferoj, li benis la popolon en la nomo de la Eternulo.","Kiam David finis la oferadon de la bruloferoj kaj de la pacoferoj, li benis la popolon en la nomo de la Eternulo."],[16,3,"Kaj li disdonis al ĉiuj Izraelidoj, kiel al la viroj, tiel ankaŭ al la virinoj, al ĉiu po unu bulo da pano, po unu porcio da viando, kaj po unu peniko da sekvinberoj.","Kaj li disdonis al ĉiuj Izraelidoj, kiel al la viroj, tiel ankaŭ al la virinoj, al ĉiu po unu bulo da pano, po unu porcio da viando, kaj po unu peniko da sekvinberoj."],[16,4,"Kaj li starigis antaŭ la kesto de la Eternulo el la Levidoj servantojn, por kantadi gloron, dankon, kaj laŭdon al la Eternulo, Dio de Izrael:","Kaj li starigis antaŭ la kesto de la Eternulo el la Levidoj servantojn, por kantadi gloron, dankon, kaj laŭdon al la Eternulo, Dio de Izrael:"],[16,5,"la ĉefo estis Asaf, la dua estis Zeĥarja, poste Jeiel, Ŝemiramot, Jeĥiel, Matitja, Eliab, Benaja, Obed-Edom, kaj Jeiel, kun psalteroj kaj harpoj, kaj Asaf sonigadis per cimbaloj;","la ĉefo estis Asaf, la dua estis Zeĥarja, poste Jeiel, Ŝemiramot, Jeĥiel, Matitja, Eliab, Benaja, Obed-Edom, kaj Jeiel, kun psalteroj kaj harpoj, kaj Asaf sonigadis per cimbaloj;"],[16,6,"Benaja kaj Jaĥaziel, la pastroj, estis kun trumpetoj ĉiam antaŭ la kesto de interligo de Dio.","Benaja kaj Jaĥaziel, la pastroj, estis kun trumpetoj ĉiam antaŭ la kesto de interligo de Dio."],[16,7,"Tiam, en tiu tago, David la unuan fojon aranĝis dankokanton al la Eternulo per Asaf kaj liaj fratoj:","Tiam, en tiu tago, David la unuan fojon aranĝis dankokanton al la Eternulo per Asaf kaj liaj fratoj:"],[16,8,"Gloru la Eternulon, voku Lian nomon; Sciigu inter la popoloj Liajn farojn.","Gloru la Eternulon, voku Lian nomon; Sciigu inter la popoloj Liajn farojn."],[16,9,"Kantu al Li, muziku al Li; Parolu pri ĉiuj Liaj mirakloj.","Kantu al Li, muziku al Li; Parolu pri ĉiuj Liaj mirakloj."],[16,10,"Laŭdu Lian sanktan nomon; Ĝoju la koro de tiuj, kiuj serĉas la Eternulon.","Laŭdu Lian sanktan nomon; Ĝoju la koro de tiuj, kiuj serĉas la Eternulon."],[16,11,"Turnu vin al la Eternulo kaj al Lia potenco; Serĉu ĉiam Lian vizaĝon.","Turnu vin al la Eternulo kaj al Lia potenco; Serĉu ĉiam Lian vizaĝon."],[16,12,"Memoru Liajn miraklojn, kiujn Li faris; Liajn signomiraklojn kaj la juĝojn de Lia buŝo;","Memoru Liajn miraklojn, kiujn Li faris; Liajn signomiraklojn kaj la juĝojn de Lia buŝo;"],[16,13,"Vi, semo de Izrael, Lia sklavo, Filoj de Jakob, Liaj elektitoj.","Vi, semo de Izrael, Lia sklavo, Filoj de Jakob, Liaj elektitoj."],[16,14,"Li estas la Eternulo, nia Dio; Sur la tuta tero estas Liaj juĝoj.","Li estas la Eternulo, nia Dio; Sur la tuta tero estas Liaj juĝoj."],[16,15,"Memoru eterne Lian interligon, La vorton, kiun Li testamentis por mil generacioj,","Memoru eterne Lian interligon, La vorton, kiun Li testamentis por mil generacioj,"],[16,16,"Kiun Li interkonsentis kun Abraham Kaj ĵuris al Isaak.","Kiun Li interkonsentis kun Abraham Kaj ĵuris al Isaak."],[16,17,"Li metis ĝin por Jakob kiel leĝon, Por Izrael kiel eternan interligon,","Li metis ĝin por Jakob kiel leĝon, Por Izrael kiel eternan interligon,"],[16,18,"Dirante: Al vi Mi donos la landon Kanaanan Kiel vian parton heredan.","Dirante: Al vi Mi donos la landon Kanaanan Kiel vian parton heredan."],[16,19,"Kiam vi estis malgrandnombraj, Malmultaj, kaj fremduloj en ĝi,","Kiam vi estis malgrandnombraj, Malmultaj, kaj fremduloj en ĝi,"],[16,20,"Kaj ili iradis de popolo al popolo, El unu regno al alia gento,","Kaj ili iradis de popolo al popolo, El unu regno al alia gento,"],[16,21,"Tiam Li al neniu permesis premi ilin, Kaj Li punis pro ili reĝojn;","Tiam Li al neniu permesis premi ilin, Kaj Li punis pro ili reĝojn;"],[16,22,"Dirante: Ne tuŝu Miajn sanktoleitojn, Kaj al Miaj profetoj ne faru malbonon.","Dirante: Ne tuŝu Miajn sanktoleitojn, Kaj al Miaj profetoj ne faru malbonon."],[16,23,"Kantu al la Eternulo la tuta tero; Proklamu de tago al tago Lian savon.","Kantu al la Eternulo la tuta tero; Proklamu de tago al tago Lian savon."],[16,24,"Rakontu inter la popoloj Lian gloron, Inter ĉiuj gentoj Liajn miraklojn.","Rakontu inter la popoloj Lian gloron, Inter ĉiuj gentoj Liajn miraklojn."],[16,25,"Ĉar la Eternulo estas granda kaj tre glorinda; Li estas timinda super ĉiuj dioj;","Ĉar la Eternulo estas granda kaj tre glorinda; Li estas timinda super ĉiuj dioj;"],[16,26,"Ĉar ĉiuj dioj de la popoloj estas idoloj; Sed la Eternulo kreis la ĉielon.","Ĉar ĉiuj dioj de la popoloj estas idoloj; Sed la Eternulo kreis la ĉielon."],[16,27,"Gloro kaj majesto estas antaŭ Li; Forto kaj beleco estas sur Lia loko.","Gloro kaj majesto estas antaŭ Li; Forto kaj beleco estas sur Lia loko."],[16,28,"Tributu al la Eternulo, familioj de la popoloj; Tributu al la Eternulo gloron kaj potencon.","Tributu al la Eternulo, familioj de la popoloj; Tributu al la Eternulo gloron kaj potencon."],[16,29,"Tributu al la Eternulo honoron de Lia nomo; Alportu donacon, kaj venu antaŭ Lin; Adorkliniĝu antaŭ la Eternulo en sankta ornamo.","Tributu al la Eternulo honoron de Lia nomo; Alportu donacon, kaj venu antaŭ Lin; Adorkliniĝu antaŭ la Eternulo en sankta ornamo."],[16,30,"Tremu antaŭ Li la tuta tero; Li aranĝis ja la mondon, ke ĝi ne ŝanceliĝu.","Tremu antaŭ Li la tuta tero; Li aranĝis ja la mondon, ke ĝi ne ŝanceliĝu."],[16,31,"Ĝoju la ĉielo, kaj estu gaja la tero; Kaj oni diru inter la nacioj: La Eternulo reĝas.","Ĝoju la ĉielo, kaj estu gaja la tero; Kaj oni diru inter la nacioj: La Eternulo reĝas."],[16,32,"Bruu la maro, kaj ĉio, kio ĝin plenigas; Ĝoju la kampo, kaj ĉio, kio estas sur ĝi.","Bruu la maro, kaj ĉio, kio ĝin plenigas; Ĝoju la kampo, kaj ĉio, kio estas sur ĝi."],[16,33,"Tiam kantu ĉiuj arboj de la arbaro antaŭ la Eternulo, Ĉar Li venas, por juĝi la teron.","Tiam kantu ĉiuj arboj de la arbaro antaŭ la Eternulo, Ĉar Li venas, por juĝi la teron."],[16,34,"Laŭdu la Eternulon, ĉar Li estas bona; Ĉar eterna estas Lia favorkoreco.","Laŭdu la Eternulon, ĉar Li estas bona; Ĉar eterna estas Lia favorkoreco."],[16,35,"Kaj diru: Savu nin, ho Dio de nia savo, Kolektu nin kaj liberigu nin el inter la nacioj, Por ke ni danku Vian sanktan nomon, Por ke ni gloru nin per Via majesto.","Kaj diru: Savu nin, ho Dio de nia savo, Kolektu nin kaj liberigu nin el inter la nacioj, Por ke ni danku Vian sanktan nomon, Por ke ni gloru nin per Via majesto."],[16,36,"Benata estu la Eternulo, Dio de Izrael, De eterne ĝis eterne. Kaj la tuta popolo diris: Amen! kaj gloro al la Eternulo!","Benata estu la Eternulo, Dio de Izrael, De eterne ĝis eterne. Kaj la tuta popolo diris: Amen! kaj gloro al la Eternulo!"],[16,37,"Kaj li restigis tie antaŭ la kesto de interligo de la Eternulo Asafon kaj liajn fratojn, por servadi antaŭ la kesto konstante, laŭ la ordo de ĉiu tago;","Kaj li restigis tie antaŭ la kesto de interligo de la Eternulo Asafon kaj liajn fratojn, por servadi antaŭ la kesto konstante, laŭ la ordo de ĉiu tago;"],[16,38,"kaj Obed-Edomon kaj liajn fratojn, sesdek ok; Obed-Edom, filo de Jedutun, kaj Ĥosa, restis kiel pordegistoj;","kaj Obed-Edomon kaj liajn fratojn, sesdek ok; Obed-Edom, filo de Jedutun, kaj Ĥosa, restis kiel pordegistoj;"],[16,39,"kaj la pastron Cadok kaj liajn fratojn, la pastrojn, antaŭ la loĝejo de la Eternulo sur la altaĵo en Gibeon,","kaj la pastron Cadok kaj liajn fratojn, la pastrojn, antaŭ la loĝejo de la Eternulo sur la altaĵo en Gibeon,"],[16,40,"por ke ili alportadu bruloferojn al la Eternulo sur la altaro de bruloferoj konstante, matene kaj vespere, kaj por ĉio, kio estas skribita en la instruo de la Eternulo, kiun Li donis al Izrael.","por ke ili alportadu bruloferojn al la Eternulo sur la altaro de bruloferoj konstante, matene kaj vespere, kaj por ĉio, kio estas skribita en la instruo de la Eternulo, kiun Li donis al Izrael."],[16,41,"Kaj kun ili estis Heman kaj Jedutun, kaj la aliaj elektitoj, difinitaj laŭnome, por kantadi laŭdon al la Eternulo, ĉar eterna estas Lia favorkoreco;","Kaj kun ili estis Heman kaj Jedutun, kaj la aliaj elektitoj, difinitaj laŭnome, por kantadi laŭdon al la Eternulo, ĉar eterna estas Lia favorkoreco;"],[16,42,"kun ili estis Heman kaj Jedutun, kun trumpetoj kaj cimbaloj kaj aliaj instrumentoj por kantado antaŭ Dio; kaj la filoj de Jedutun estis ĉe la pordego.","kun ili estis Heman kaj Jedutun, kun trumpetoj kaj cimbaloj kaj aliaj instrumentoj por kantado antaŭ Dio; kaj la filoj de Jedutun estis ĉe la pordego."],[16,43,"Kaj la tuta popolo disiris ĉiu en sian domon; kaj David iris returne, por beni sian domon.","Kaj la tuta popolo disiris ĉiu en sian domon; kaj David iris returne, por beni sian domon."],[17,1,"Kiam David loĝis en sia domo, li diris unu fojon al la profeto Natan: Jen mi loĝas en domo cedroligna, kaj la kesto de interligo de la Eternulo restas sub tapiŝoj.","Kiam David loĝis en sia domo, li diris unu fojon al la profeto Natan: Jen mi loĝas en domo cedroligna, kaj la kesto de interligo de la Eternulo restas sub tapiŝoj."],[17,2,"Kaj Natan diris al David: Ĉion, kio estas sur via koro, faru, ĉar Dio estas kun vi.","Kaj Natan diris al David: Ĉion, kio estas sur via koro, faru, ĉar Dio estas kun vi."],[17,3,"Sed en tiu sama nokto aperis vorto de Dio al Natan, dirante:","Sed en tiu sama nokto aperis vorto de Dio al Natan, dirante:"],[17,4,"Iru, kaj diru al Mia servanto David: Tiele diras la Eternulo: Ne vi konstruos por Mi la domon por loĝi;","Iru, kaj diru al Mia servanto David: Tiele diras la Eternulo: Ne vi konstruos por Mi la domon por loĝi;"],[17,5,"ĉar Mi ne loĝis en domo de post tiu tago, kiam Mi elkondukis Izraelon, ĝis la nuna tempo; sed Mi estis nur en tabernaklo kaj en tendo.","ĉar Mi ne loĝis en domo de post tiu tago, kiam Mi elkondukis Izraelon, ĝis la nuna tempo; sed Mi estis nur en tabernaklo kaj en tendo."],[17,6,"Kien ajn Mi iris kun la tuta Izrael, ĉu Mi diris eĉ unu vorton al iu el la juĝistoj de Izrael, al kiuj Mi ordonis paŝti Mian popolon, dirante: Kial vi ne konstruis por Mi cedrolignan domon?","Kien ajn Mi iris kun la tuta Izrael, ĉu Mi diris eĉ unu vorton al iu el la juĝistoj de Izrael, al kiuj Mi ordonis paŝti Mian popolon, dirante: Kial vi ne konstruis por Mi cedrolignan domon?"],[17,7,"Kaj nun diru jenon al Mia servanto David: Tiele diras la Eternulo Cebaot: Mi prenis vin de ŝafejo, de ŝafoj, por ke vi estu estro super Mia popolo Izrael;","Kaj nun diru jenon al Mia servanto David: Tiele diras la Eternulo Cebaot: Mi prenis vin de ŝafejo, de ŝafoj, por ke vi estu estro super Mia popolo Izrael;"],[17,8,"kaj Mi estis kun vi ĉie, kien vi iris; kaj Mi ekstermis ĉiujn viajn malamikojn antaŭ vi, kaj Mi faris al vi nomon, egalan al la nomoj de la potenculoj sur la tero;","kaj Mi estis kun vi ĉie, kien vi iris; kaj Mi ekstermis ĉiujn viajn malamikojn antaŭ vi, kaj Mi faris al vi nomon, egalan al la nomoj de la potenculoj sur la tero;"],[17,9,"kaj Mi aranĝis lokon por Mia popolo Izrael, kaj Mi plantis ĝin tiel, ke ĝi loĝu trankvile sur sia loko kaj ne plu tremu; kaj malbonuloj ne plu senfortigos ĝin, kiel antaŭe;","kaj Mi aranĝis lokon por Mia popolo Izrael, kaj Mi plantis ĝin tiel, ke ĝi loĝu trankvile sur sia loko kaj ne plu tremu; kaj malbonuloj ne plu senfortigos ĝin, kiel antaŭe;"],[17,10,"kaj de post tiu tempo, kiam Mi starigis juĝistojn super Mia popolo Izrael, Mi humiligis ĉiujn viajn malamikojn; kaj Mi diras al vi, ke domon konstruos al vi la Eternulo.","kaj de post tiu tempo, kiam Mi starigis juĝistojn super Mia popolo Izrael, Mi humiligis ĉiujn viajn malamikojn; kaj Mi diras al vi, ke domon konstruos al vi la Eternulo."],[17,11,"Kiam finiĝos viaj tagoj kaj vi iros al viaj patroj, Mi starigos post vi vian idon, kiu estos el viaj filoj; kaj Mi fortikigos lian regnon.","Kiam finiĝos viaj tagoj kaj vi iros al viaj patroj, Mi starigos post vi vian idon, kiu estos el viaj filoj; kaj Mi fortikigos lian regnon."],[17,12,"Li konstruos por Mi domon; kaj Mi fortikigos lian tronon por ĉiam.","Li konstruos por Mi domon; kaj Mi fortikigos lian tronon por ĉiam."],[17,13,"Mi estos al li patro, kaj li estos al Mi filo; kaj Mian favorkorecon Mi ne deturnos de li tiel, kiel Mi deturnis de tiu, kiu estis antaŭ vi.","Mi estos al li patro, kaj li estos al Mi filo; kaj Mian favorkorecon Mi ne deturnos de li tiel, kiel Mi deturnis de tiu, kiu estis antaŭ vi."],[17,14,"Kaj Mi starigos lin en Mia domo kaj en Mia regno por ĉiam; kaj lia trono estos fortikigita por eterne.","Kaj Mi starigos lin en Mia domo kaj en Mia regno por ĉiam; kaj lia trono estos fortikigita por eterne."],[17,15,"Konforme al ĉiuj ĉi tiuj vortoj kaj al ĉi tiu tuta vizio, Natan parolis al David.","Konforme al ĉiuj ĉi tiuj vortoj kaj al ĉi tiu tuta vizio, Natan parolis al David."],[17,16,"Kaj venis la reĝo David kaj sidiĝis antaŭ la Eternulo, kaj diris: Kiu estas mi, ho Dio Eternulo, kaj kio estas mia domo, ke Vi venigis min ĝis ĉi tie?","Kaj venis la reĝo David kaj sidiĝis antaŭ la Eternulo, kaj diris: Kiu estas mi, ho Dio Eternulo, kaj kio estas mia domo, ke Vi venigis min ĝis ĉi tie?"],[17,17,"Sed eĉ tio estis nesufiĉa antaŭ Vi, ho Dio, kaj Vi parolis pri la domo de Via servanto eĉ por la malproksima estonteco, kaj Vi rigardis min kiel homon alte starantan, ho Dio Eternulo.","Sed eĉ tio estis nesufiĉa antaŭ Vi, ho Dio, kaj Vi parolis pri la domo de Via servanto eĉ por la malproksima estonteco, kaj Vi rigardis min kiel homon alte starantan, ho Dio Eternulo."],[17,18,"Kion pli David povas diri al Vi, por honori Vian servanton? Vi konas ja Vian servanton.","Kion pli David povas diri al Vi, por honori Vian servanton? Vi konas ja Vian servanton."],[17,19,"Ho Eternulo, por Via servanto kaj laŭ Via koro Vi faris tiun tutan grandaĵon, por montri ĉian grandecon.","Ho Eternulo, por Via servanto kaj laŭ Via koro Vi faris tiun tutan grandaĵon, por montri ĉian grandecon."],[17,20,"Ho Eternulo, ne ekzistas simila al Vi, kaj ne ekzistas Dio krom Vi, laŭ ĉio, kion ni aŭdis per niaj oreloj.","Ho Eternulo, ne ekzistas simila al Vi, kaj ne ekzistas Dio krom Vi, laŭ ĉio, kion ni aŭdis per niaj oreloj."],[17,21,"Kaj kiu estas simila al Via popolo Izrael, la sola popolo sur la tero, koncerne kiun Dio iris, por elaĉeti ĝin al Si kiel popolon, por fari al Si nomon per grandaĵoj kaj timindaĵoj, forpelante naciojn antaŭ Via popolo, kiun Vi liberigis el Egiptujo?","Kaj kiu estas simila al Via popolo Izrael, la sola popolo sur la tero, koncerne kiun Dio iris, por elaĉeti ĝin al Si kiel popolon, por fari al Si nomon per grandaĵoj kaj timindaĵoj, forpelante naciojn antaŭ Via popolo, kiun Vi liberigis el Egiptujo?"],[17,22,"Vi faris Vian popolon Izrael Via popolo por eterne; kaj Vi, ho Eternulo, faris Vin Dio por ĝi.","Vi faris Vian popolon Izrael Via popolo por eterne; kaj Vi, ho Eternulo, faris Vin Dio por ĝi."],[17,23,"Kaj nun, ho Eternulo, la vorto, kiun Vi diris pri Via servanto kaj pri lia domo, veriĝu por eterne, kaj Vi agu tiel, kiel Vi diris.","Kaj nun, ho Eternulo, la vorto, kiun Vi diris pri Via servanto kaj pri lia domo, veriĝu por eterne, kaj Vi agu tiel, kiel Vi diris."],[17,24,"Kaj Via nomo estu vera kaj granda por eterne, por ke oni diru: La Eternulo Cebaot, Dio de Izrael, estas Dio al Izrael; kaj la domo de Via servanto David estu fortika antaŭ Vi.","Kaj Via nomo estu vera kaj granda por eterne, por ke oni diru: La Eternulo Cebaot, Dio de Izrael, estas Dio al Izrael; kaj la domo de Via servanto David estu fortika antaŭ Vi."],[17,25,"Ĉar Vi, ho mia Dio, sciigis al la orelo de Via servanto, ke Vi konstruos al li domon; tial Via servanto trovis kuraĝon preĝi antaŭ Vi.","Ĉar Vi, ho mia Dio, sciigis al la orelo de Via servanto, ke Vi konstruos al li domon; tial Via servanto trovis kuraĝon preĝi antaŭ Vi."],[17,26,"Kaj nun, ho Eternulo, Vi estas Dio, kaj Vi diris pri Via servanto ĉi tiun bonaĵon.","Kaj nun, ho Eternulo, Vi estas Dio, kaj Vi diris pri Via servanto ĉi tiun bonaĵon."],[17,27,"Nun komencu beni la domon de Via servanto, ke ĝi restu eterne antaŭ Vi; ĉar kion Vi, ho Eternulo, benas, tio restas benita por eterne.","Nun komencu beni la domon de Via servanto, ke ĝi restu eterne antaŭ Vi; ĉar kion Vi, ho Eternulo, benas, tio restas benita por eterne."],[18,1,"Post tio okazis, ke David venkobatis la Filiŝtojn kaj humiligis ilin, kaj li prenis Gaton kaj ĝiajn filinurbojn el la manoj de la Filiŝtoj.","Post tio okazis, ke David venkobatis la Filiŝtojn kaj humiligis ilin, kaj li prenis Gaton kaj ĝiajn filinurbojn el la manoj de la Filiŝtoj."],[18,2,"Li ankaŭ venkobatis la Moabidojn, kaj la Moabidoj submetiĝis al David kaj alportis tributojn.","Li ankaŭ venkobatis la Moabidojn, kaj la Moabidoj submetiĝis al David kaj alportis tributojn."],[18,3,"Kaj David venkobatis Hadarezeron, reĝon de Coba, en Ĥamat, kiam tiu iris, por fortikigi sian regadon super la rivero Eŭfrato.","Kaj David venkobatis Hadarezeron, reĝon de Coba, en Ĥamat, kiam tiu iris, por fortikigi sian regadon super la rivero Eŭfrato."],[18,4,"Kaj David venkoprenis de li mil ĉarojn kaj sep mil rajdantojn kaj dudek mil piedirantojn; kaj David lamigis ĉiujn ĉarĉevalojn, sed restigis el ili por cent ĉaroj.","Kaj David venkoprenis de li mil ĉarojn kaj sep mil rajdantojn kaj dudek mil piedirantojn; kaj David lamigis ĉiujn ĉarĉevalojn, sed restigis el ili por cent ĉaroj."],[18,5,"La Sirianoj Damaskaj venis, por helpi al Hadarezer, reĝo de Coba; sed David venkobatis el la Sirianoj dudek du mil homojn.","La Sirianoj Damaskaj venis, por helpi al Hadarezer, reĝo de Coba; sed David venkobatis el la Sirianoj dudek du mil homojn."],[18,6,"Kaj David restigis garnizonojn en la Damaska Sirio, kaj la Sirianoj submetiĝis al David kaj alportis tributojn. Kaj la Eternulo helpis al David ĉie, kien li iris.","Kaj David restigis garnizonojn en la Damaska Sirio, kaj la Sirianoj submetiĝis al David kaj alportis tributojn. Kaj la Eternulo helpis al David ĉie, kien li iris."],[18,7,"Kaj David prenis la orajn ŝildojn, kiujn havis sur si la servantoj de Hadarezer, kaj alportis ilin en Jerusalemon.","Kaj David prenis la orajn ŝildojn, kiujn havis sur si la servantoj de Hadarezer, kaj alportis ilin en Jerusalemon."],[18,8,"Kaj el Tibĥat kaj el Kun, urboj de Hadarezer, David prenis tre multe da kupro, el kiu poste Salomono faris la kupran maron, la kolonojn, kaj la kuprajn vazojn.","Kaj el Tibĥat kaj el Kun, urboj de Hadarezer, David prenis tre multe da kupro, el kiu poste Salomono faris la kupran maron, la kolonojn, kaj la kuprajn vazojn."],[18,9,"Kiam Tou, reĝo de Ĥamat, aŭdis, ke David venkobatis la tutan militistaron de Hadarezer, reĝo de Coba,","Kiam Tou, reĝo de Ĥamat, aŭdis, ke David venkobatis la tutan militistaron de Hadarezer, reĝo de Coba,"],[18,10,"tiam li sendis sian filon Hadoram al la reĝo David, por saluti lin, kaj gratuli lin pri tio, ke li militis kontraŭ Hadarezer kaj venkobatis lin (ĉar Tou estis en milito kontraŭ Hadarezer); kaj li havis kun si ĉiaspecajn vazojn el oro, arĝento, kaj kupro.","tiam li sendis sian filon Hadoram al la reĝo David, por saluti lin, kaj gratuli lin pri tio, ke li militis kontraŭ Hadarezer kaj venkobatis lin (ĉar Tou estis en milito kontraŭ Hadarezer); kaj li havis kun si ĉiaspecajn vazojn el oro, arĝento, kaj kupro."],[18,11,"Ankaŭ ĉi tiujn David dediĉis al la Eternulo, kune kun la arĝento kaj oro, kiun li prenis de ĉiuj nacioj: de Edom, de Moab, de la Amonidoj, de la Filiŝtoj, kaj de Amalek.","Ankaŭ ĉi tiujn David dediĉis al la Eternulo, kune kun la arĝento kaj oro, kiun li prenis de ĉiuj nacioj: de Edom, de Moab, de la Amonidoj, de la Filiŝtoj, kaj de Amalek."],[18,12,"Plue Abiŝaj, filo de Ceruja, venkobatis Edomon en la Valo de Salo, dek ok mil homojn;","Plue Abiŝaj, filo de Ceruja, venkobatis Edomon en la Valo de Salo, dek ok mil homojn;"],[18,13,"kaj li restigis en Edomujo garnizonojn, kaj ĉiuj Edomidoj submetiĝis al David. Kaj la Eternulo helpis al David ĉie, kien li iris.","kaj li restigis en Edomujo garnizonojn, kaj ĉiuj Edomidoj submetiĝis al David. Kaj la Eternulo helpis al David ĉie, kien li iris."],[18,14,"Kaj David reĝis super la tuta Izrael, kaj li faradis juĝon kaj justecon al sia tuta popolo.","Kaj David reĝis super la tuta Izrael, kaj li faradis juĝon kaj justecon al sia tuta popolo."],[18,15,"Joab, filo de Ceruja, estis estro de la militistaro; Jehoŝafat, filo de Aĥilud, estis kronikisto;","Joab, filo de Ceruja, estis estro de la militistaro; Jehoŝafat, filo de Aĥilud, estis kronikisto;"],[18,16,"Cadok, filo de Aĥitub, kaj Abimeleĥ, filo de Ebjatar, estis pastroj; kaj Ŝavŝa estis skribisto;","Cadok, filo de Aĥitub, kaj Abimeleĥ, filo de Ebjatar, estis pastroj; kaj Ŝavŝa estis skribisto;"],[18,17,"Benaja, filo de Jehojada, estis super la Keretidoj kaj la Peletidoj; kaj la filoj de David estis la unuaj apud la reĝo.","Benaja, filo de Jehojada, estis super la Keretidoj kaj la Peletidoj; kaj la filoj de David estis la unuaj apud la reĝo."],[19,1,"Okazis poste, ke mortis Naĥaŝ, reĝo de la Amonidoj, kaj lia filo fariĝis reĝo anstataŭ li.","Okazis poste, ke mortis Naĥaŝ, reĝo de la Amonidoj, kaj lia filo fariĝis reĝo anstataŭ li."],[19,2,"Tiam David diris: Mi estos favorkora al Ĥanun, filo de Naĥaŝ, ĉar lia patro agis favorkore koncerne min. Kaj David sendis senditojn, por konsoli lin pri lia patro. Kaj la servantoj de David venis en la landon de la Amonidoj, al Ĥanun, por lin konsoli.","Tiam David diris: Mi estos favorkora al Ĥanun, filo de Naĥaŝ, ĉar lia patro agis favorkore koncerne min. Kaj David sendis senditojn, por konsoli lin pri lia patro. Kaj la servantoj de David venis en la landon de la Amonidoj, al Ĥanun, por lin konsoli."],[19,3,"Sed la eminentuloj de la Amonidoj diris al Ĥanun: Ĉu efektive David deziras honori vian patron antaŭ vi, ke li sendis al vi konsolantojn? ĉu ne venis al vi liaj servantoj nur por esplori, por ruinigi, kaj por esplorrigardi la landon?","Sed la eminentuloj de la Amonidoj diris al Ĥanun: Ĉu efektive David deziras honori vian patron antaŭ vi, ke li sendis al vi konsolantojn? ĉu ne venis al vi liaj servantoj nur por esplori, por ruinigi, kaj por esplorrigardi la landon?"],[19,4,"Tiam Ĥanun prenis la servantojn de David, razigis ilin, detranĉis iliajn vestojn ĝis duono, ĝis la lumboj, kaj foririgis ilin.","Tiam Ĥanun prenis la servantojn de David, razigis ilin, detranĉis iliajn vestojn ĝis duono, ĝis la lumboj, kaj foririgis ilin."],[19,5,"Kaj ili iris. Kaj oni raportis al David pri tiuj viroj, kaj li sendis renkonte al ili, ĉar la viroj tre hontis. Kaj la reĝo diris: Restu en Jeriĥo, ĝis rekreskos viaj barboj, kaj tiam revenu.","Kaj ili iris. Kaj oni raportis al David pri tiuj viroj, kaj li sendis renkonte al ili, ĉar la viroj tre hontis. Kaj la reĝo diris: Restu en Jeriĥo, ĝis rekreskos viaj barboj, kaj tiam revenu."],[19,6,"Kiam la Amonidoj vidis, ke ili indignigis kontraŭ si Davidon, tiam Ĥanun kaj la Amonidoj sendis mil kikarojn da arĝento, por dungi al si el Mezopotamio, el Sirio de Maaĥa, kaj el Coba ĉarojn kaj rajdistojn.","Kiam la Amonidoj vidis, ke ili indignigis kontraŭ si Davidon, tiam Ĥanun kaj la Amonidoj sendis mil kikarojn da arĝento, por dungi al si el Mezopotamio, el Sirio de Maaĥa, kaj el Coba ĉarojn kaj rajdistojn."],[19,7,"Kaj ili dungis al si tridek du mil ĉarojn kaj la reĝon de Maaĥa kun lia popolo. Kaj ili venis kaj stariĝis tendare antaŭ Medba. Kaj la Amonidoj kolektiĝis el siaj urboj kaj venis al la milito.","Kaj ili dungis al si tridek du mil ĉarojn kaj la reĝon de Maaĥa kun lia popolo. Kaj ili venis kaj stariĝis tendare antaŭ Medba. Kaj la Amonidoj kolektiĝis el siaj urboj kaj venis al la milito."],[19,8,"Kiam David aŭdis pri tio, li sendis Joabon kaj la tutan armeon da kuraĝuloj.","Kiam David aŭdis pri tio, li sendis Joabon kaj la tutan armeon da kuraĝuloj."],[19,9,"Kaj la Amonidoj eliris, kaj batalaranĝiĝis antaŭ la enirejo de la urbo; kaj la reĝoj venintaj aranĝiĝis aparte, sur la kampo.","Kaj la Amonidoj eliris, kaj batalaranĝiĝis antaŭ la enirejo de la urbo; kaj la reĝoj venintaj aranĝiĝis aparte, sur la kampo."],[19,10,"Kiam Joab vidis, ke li havos kontraŭ si batalon antaŭe kaj malantaŭe, li faris elekton el ĉiuj plejbravuloj en Izrael kaj batalaranĝis ilin kontraŭ la Sirianoj;","Kiam Joab vidis, ke li havos kontraŭ si batalon antaŭe kaj malantaŭe, li faris elekton el ĉiuj plejbravuloj en Izrael kaj batalaranĝis ilin kontraŭ la Sirianoj;"],[19,11,"la ceteran parton de la popolo li komisiis al sia frato Abiŝaj, kaj ili batalaranĝis sin kontraŭ la Amonidoj.","la ceteran parton de la popolo li komisiis al sia frato Abiŝaj, kaj ili batalaranĝis sin kontraŭ la Amonidoj."],[19,12,"Kaj li diris: Se la Sirianoj superfortos min, tiam vi donos al mi helpon; sed se la Amonidoj superfortos vin, tiam mi donos al vi helpon;","Kaj li diris: Se la Sirianoj superfortos min, tiam vi donos al mi helpon; sed se la Amonidoj superfortos vin, tiam mi donos al vi helpon;"],[19,13,"estu kuraĝa, kaj ni tenu nin forte pro nia popolo kaj pro la urboj de nia Dio; kaj la Eternulo faru tion, kio plaĉos al Li.","estu kuraĝa, kaj ni tenu nin forte pro nia popolo kaj pro la urboj de nia Dio; kaj la Eternulo faru tion, kio plaĉos al Li."],[19,14,"Kaj Joab, kun la popolo, kiu estis kun li, komencis la batalon kontraŭ la Sirianoj, kaj ĉi tiuj forkuris antaŭ li.","Kaj Joab, kun la popolo, kiu estis kun li, komencis la batalon kontraŭ la Sirianoj, kaj ĉi tiuj forkuris antaŭ li."],[19,15,"Kiam la Amonidoj vidis, ke la Sirianoj forkuris, ili ankaŭ forkuris antaŭ lia frato Abiŝaj, kaj foriris en la urbon. Kaj Joab venis Jerusalemon.","Kiam la Amonidoj vidis, ke la Sirianoj forkuris, ili ankaŭ forkuris antaŭ lia frato Abiŝaj, kaj foriris en la urbon. Kaj Joab venis Jerusalemon."],[19,16,"Vidante, ke ili estas venkobatitaj de la Izraelidoj, la Sirianoj sendis senditojn kaj elirigis la Sirianojn transriverajn; kaj Ŝofaĥ, la militestro de Hadarezer, ilin kondukis.","Vidante, ke ili estas venkobatitaj de la Izraelidoj, la Sirianoj sendis senditojn kaj elirigis la Sirianojn transriverajn; kaj Ŝofaĥ, la militestro de Hadarezer, ilin kondukis."],[19,17,"Kiam tio estis raportita al David, li kolektis ĉiujn Izraelidojn, transiris Jordanon, venis al ili, kaj batalaranĝiĝis kontraŭ ili; David aranĝis batalon kontraŭ la Sirianoj, kaj ili interbatalis kun li.","Kiam tio estis raportita al David, li kolektis ĉiujn Izraelidojn, transiris Jordanon, venis al ili, kaj batalaranĝiĝis kontraŭ ili; David aranĝis batalon kontraŭ la Sirianoj, kaj ili interbatalis kun li."],[19,18,"Kaj la Sirianoj forkuris antaŭ Izrael, kaj David mortigis el la Sirianoj sep mil ĉaristojn kaj kvardek mil piedirantojn; ankaŭ Ŝofaĥon, la militestron, li mortigis.","Kaj la Sirianoj forkuris antaŭ Izrael, kaj David mortigis el la Sirianoj sep mil ĉaristojn kaj kvardek mil piedirantojn; ankaŭ Ŝofaĥon, la militestron, li mortigis."],[19,19,"Kiam la servantoj de Hadarezer vidis, ke ili estas venkobatitaj de la Izraelidoj, ili faris pacon kun David kaj submetiĝis al li. Kaj la Sirianoj ne volis plu helpi al la Amonidoj.","Kiam la servantoj de Hadarezer vidis, ke ili estas venkobatitaj de la Izraelidoj, ili faris pacon kun David kaj submetiĝis al li. Kaj la Sirianoj ne volis plu helpi al la Amonidoj."],[20,1,"Post paso de unu jaro, en la tempo, kiam la reĝoj eliras milite, Joab kondukis la militistaron kaj komencis ruinigi la landon de la Amonidoj, kaj li venis kaj eksieĝis Raban. Sed David restis en Jerusalem. Kaj Joab venkobatis Raban kaj detruis ĝin.","Post paso de unu jaro, en la tempo, kiam la reĝoj eliras milite, Joab kondukis la militistaron kaj komencis ruinigi la landon de la Amonidoj, kaj li venis kaj eksieĝis Raban. Sed David restis en Jerusalem. Kaj Joab venkobatis Raban kaj detruis ĝin."],[20,2,"Kaj David prenis la kronon de Malkam de lia kapo; li trovis, ke ĝi enhavas laŭpeze kikaron da oro, kaj estis en ĝi multekosta ŝtono, kiu transiris sur la kapon de David. Kaj da militakiraĵo li elportis el la urbo tre multe.","Kaj David prenis la kronon de Malkam de lia kapo; li trovis, ke ĝi enhavas laŭpeze kikaron da oro, kaj estis en ĝi multekosta ŝtono, kiu transiris sur la kapon de David. Kaj da militakiraĵo li elportis el la urbo tre multe."],[20,3,"Kaj la popolon, kiu estis tie, li elirigis, kaj mortigis per segiloj, feraj draŝiloj, kaj hakiloj. Tiele David agis kun ĉiuj urboj de la Amonidoj. Kaj David kun la tuta popolo revenis Jerusalemon.","Kaj la popolon, kiu estis tie, li elirigis, kaj mortigis per segiloj, feraj draŝiloj, kaj hakiloj. Tiele David agis kun ĉiuj urboj de la Amonidoj. Kaj David kun la tuta popolo revenis Jerusalemon."],[20,4,"Post tio komenciĝis milito en Gezer, kontraŭ la Filiŝtoj; tiam Sibĥaj, la Ĥuŝaido, mortigis Sipajon, unu el la infanoj de la giganto. Kaj ili humiliĝis.","Post tio komenciĝis milito en Gezer, kontraŭ la Filiŝtoj; tiam Sibĥaj, la Ĥuŝaido, mortigis Sipajon, unu el la infanoj de la giganto. Kaj ili humiliĝis."],[20,5,"Kaj denove estis milito kun la Filiŝtoj; kaj Elĥanan, filo de Jair, mortigis Laĥmin, fraton de Goljat, la Gatano, ĉe kiu la tenilo de lia lanco estis kiel rultrabo de teksisto.","Kaj denove estis milito kun la Filiŝtoj; kaj Elĥanan, filo de Jair, mortigis Laĥmin, fraton de Goljat, la Gatano, ĉe kiu la tenilo de lia lanco estis kiel rultrabo de teksisto."],[20,6,"Kaj denove estis milito en Gat; tie estis viro tre altkreska, kiu havis po ses fingroj, sume dudek kvar; li ankaŭ naskiĝis al la giganto.","Kaj denove estis milito en Gat; tie estis viro tre altkreska, kiu havis po ses fingroj, sume dudek kvar; li ankaŭ naskiĝis al la giganto."],[20,7,"Kiam li insultis Izraelon, lin mortigis Jonatan, filo de Ŝimea, frato de David.","Kiam li insultis Izraelon, lin mortigis Jonatan, filo de Ŝimea, frato de David."],[20,8,"Tiuj naskiĝis al la giganto en Gat, kaj ili falis de la mano de David kaj de la manoj de liaj servantoj.","Tiuj naskiĝis al la giganto en Gat, kaj ili falis de la mano de David kaj de la manoj de liaj servantoj."],[21,1,"Satano leviĝis kontraŭ Izraelon kaj instigis Davidon kalkuli Izraelon.","Satano leviĝis kontraŭ Izraelon kaj instigis Davidon kalkuli Izraelon."],[21,2,"Kaj David diris al Joab kaj al la estroj de la popolo: Iru, kalkulu la Izraelidojn, de Beer-Ŝeba ĝis Dan, kaj raportu al mi, por ke mi sciu ilian nombron.","Kaj David diris al Joab kaj al la estroj de la popolo: Iru, kalkulu la Izraelidojn, de Beer-Ŝeba ĝis Dan, kaj raportu al mi, por ke mi sciu ilian nombron."],[21,3,"Joab diris: La Eternulo multigu Sian popolon centoble; ili ĉiuj, ho reĝo, mia sinjoro, estas ja servantoj por mia sinjoro; por kio do mia sinjoro tion postulas? por kio tio fariĝu kulpo sur Izrael?","Joab diris: La Eternulo multigu Sian popolon centoble; ili ĉiuj, ho reĝo, mia sinjoro, estas ja servantoj por mia sinjoro; por kio do mia sinjoro tion postulas? por kio tio fariĝu kulpo sur Izrael?"],[21,4,"Sed la vorto de la reĝo superfortis Joabon; tial Joab iris, trairis la tutan Izraelidaron, kaj venis Jerusalemon.","Sed la vorto de la reĝo superfortis Joabon; tial Joab iris, trairis la tutan Izraelidaron, kaj venis Jerusalemon."],[21,5,"Kaj Joab transdonis al David la rezulton de la kalkulado de la popolo; kaj montriĝis, ke da Izraelidoj estas miliono kaj cent mil viroj povantaj eltiri glavon, kaj da Jehudaidoj kvarcent sepdek mil povantaj eltiri glavon.","Kaj Joab transdonis al David la rezulton de la kalkulado de la popolo; kaj montriĝis, ke da Izraelidoj estas miliono kaj cent mil viroj povantaj eltiri glavon, kaj da Jehudaidoj kvarcent sepdek mil povantaj eltiri glavon."],[21,6,"La Levidojn kaj la Benjamenidojn li ne kalkulis inter ili, ĉar antipatia estis al Joab la vorto de la reĝo.","La Levidojn kaj la Benjamenidojn li ne kalkulis inter ili, ĉar antipatia estis al Joab la vorto de la reĝo."],[21,7,"Kaj tiu afero malplaĉis al Dio, kaj Li frapis Izraelon.","Kaj tiu afero malplaĉis al Dio, kaj Li frapis Izraelon."],[21,8,"Tiam David diris al Dio: Mi forte pekis, farante tiun aferon. Sed nun, pardonu do la malbonagon de Via servanto; ĉar mi agis tre malsaĝe.","Tiam David diris al Dio: Mi forte pekis, farante tiun aferon. Sed nun, pardonu do la malbonagon de Via servanto; ĉar mi agis tre malsaĝe."],[21,9,"Kaj la Eternulo parolis al Gad, la viziisto de David, dirante:","Kaj la Eternulo parolis al Gad, la viziisto de David, dirante:"],[21,10,"Iru kaj diru al David: Tiele diras la Eternulo: Tri punojn Mi proponas al vi; elektu al vi unu el ili, ke Mi ĝin faru al vi.","Iru kaj diru al David: Tiele diras la Eternulo: Tri punojn Mi proponas al vi; elektu al vi unu el ili, ke Mi ĝin faru al vi."],[21,11,"Kaj Gad venis al David, kaj diris al li: Tiele diras la Eternulo: Akceptu por vi:","Kaj Gad venis al David, kaj diris al li: Tiele diras la Eternulo: Akceptu por vi:"],[21,12,"aŭ dum tri jaroj estos malsato en la lando; aŭ dum tri monatoj vi estos premata de viaj kontraŭuloj kaj vin atingos la glavo de viaj malamikoj; aŭ dum tri tagoj regos en la lando la glavo de la Eternulo kaj pesto, kaj anĝelo de la Eternulo ekstermados en ĉiuj regionoj de Izrael. Pripensu do nun, kion mi respondu al mia Sendinto.","aŭ dum tri jaroj estos malsato en la lando; aŭ dum tri monatoj vi estos premata de viaj kontraŭuloj kaj vin atingos la glavo de viaj malamikoj; aŭ dum tri tagoj regos en la lando la glavo de la Eternulo kaj pesto, kaj anĝelo de la Eternulo ekstermados en ĉiuj regionoj de Izrael. Pripensu do nun, kion mi respondu al mia Sendinto."],[21,13,"Tiam David diris al Gad: Estas al mi tre malfacile; sed mi falu en la manon de la Eternulo, ĉar tre granda estas Lia kompatemeco; nur mi ne falu en manon homan.","Tiam David diris al Gad: Estas al mi tre malfacile; sed mi falu en la manon de la Eternulo, ĉar tre granda estas Lia kompatemeco; nur mi ne falu en manon homan."],[21,14,"Kaj la Eternulo venigis peston sur Izraelon, kaj falis el la Izraelidoj sepdek mil homoj.","Kaj la Eternulo venigis peston sur Izraelon, kaj falis el la Izraelidoj sepdek mil homoj."],[21,15,"Kaj Dio sendis anĝelon al Jerusalem, por fari en ĝi ekstermon. Sed kiam li komencis la ekstermadon, la Eternulo rigardis, kaj bedaŭris la malbonon, kaj diris al la anĝelo-ekstermanto: Sufiĉe! nun haltigu vian manon! La anĝelo de la Eternulo staris tiam apud la draŝejo de Ornan, la Jebusido.","Kaj Dio sendis anĝelon al Jerusalem, por fari en ĝi ekstermon. Sed kiam li komencis la ekstermadon, la Eternulo rigardis, kaj bedaŭris la malbonon, kaj diris al la anĝelo-ekstermanto: Sufiĉe! nun haltigu vian manon! La anĝelo de la Eternulo staris tiam apud la draŝejo de Ornan, la Jebusido."],[21,16,"David levis siajn okulojn, kaj ekvidis la anĝelon de la Eternulo, starantan inter la tero kaj la ĉielo, kaj tenantan en sia mano eltiritan glavon, etenditan super Jerusalem. Tiam David kaj la plejaĝuloj, kovritaj per sakaĵoj, ĵetis sin vizaĝaltere.","David levis siajn okulojn, kaj ekvidis la anĝelon de la Eternulo, starantan inter la tero kaj la ĉielo, kaj tenantan en sia mano eltiritan glavon, etenditan super Jerusalem. Tiam David kaj la plejaĝuloj, kovritaj per sakaĵoj, ĵetis sin vizaĝaltere."],[21,17,"Kaj David diris al Dio: Mi estas ja tiu, kiu ordonis kalkuli la popolon; mi estas tiu, kiu pekis kaj faris la malbonaĵon; sed kion faris ĉi tiuj ŝafoj? Ho Eternulo, mia Dio, Via mano estu sur mi kaj sur la domo de mia patro; sed Vian popolon ne plagu.","Kaj David diris al Dio: Mi estas ja tiu, kiu ordonis kalkuli la popolon; mi estas tiu, kiu pekis kaj faris la malbonaĵon; sed kion faris ĉi tiuj ŝafoj? Ho Eternulo, mia Dio, Via mano estu sur mi kaj sur la domo de mia patro; sed Vian popolon ne plagu."],[21,18,"La anĝelo de la Eternulo diris al Gad, ke li diru al David, ke David iru kaj starigu altaron al la Eternulo sur la draŝejo de Ornan, la Jebusido.","La anĝelo de la Eternulo diris al Gad, ke li diru al David, ke David iru kaj starigu altaron al la Eternulo sur la draŝejo de Ornan, la Jebusido."],[21,19,"Tiam David iris, konforme al la vorto de Gad, kiun li eldiris en la nomo de la Eternulo.","Tiam David iris, konforme al la vorto de Gad, kiun li eldiris en la nomo de la Eternulo."],[21,20,"Kiam Ornan sin returnis kaj ekvidis la anĝelon, li kaj liaj kvar filoj kun li sin kaŝis. Ornan tiam estis draŝanta tritikon.","Kiam Ornan sin returnis kaj ekvidis la anĝelon, li kaj liaj kvar filoj kun li sin kaŝis. Ornan tiam estis draŝanta tritikon."],[21,21,"Kaj David venis al Ornan. Ornan ekrigardis kaj ekvidis Davidon, kaj li eliris el la draŝejo kaj adorkliniĝis antaŭ David vizaĝaltere.","Kaj David venis al Ornan. Ornan ekrigardis kaj ekvidis Davidon, kaj li eliris el la draŝejo kaj adorkliniĝis antaŭ David vizaĝaltere."],[21,22,"David diris al Ornan: Donu al mi la lokon de la draŝejo, por ke mi konstruu sur ĝi altaron al la Eternulo; pro ĝia plena prezo donu ĝin al mi, por ke ĉesiĝu la pesto inter la popolo.","David diris al Ornan: Donu al mi la lokon de la draŝejo, por ke mi konstruu sur ĝi altaron al la Eternulo; pro ĝia plena prezo donu ĝin al mi, por ke ĉesiĝu la pesto inter la popolo."],[21,23,"Kaj Ornan diris al David: Prenu al vi; mia sinjoro la reĝo faru tion, kio plaĉas al li; vidu, mi fordonas la bovojn por bruloferoj, la draŝilojn por ligno, kaj la tritikon por farunofero; ĉion mi fordonas.","Kaj Ornan diris al David: Prenu al vi; mia sinjoro la reĝo faru tion, kio plaĉas al li; vidu, mi fordonas la bovojn por bruloferoj, la draŝilojn por ligno, kaj la tritikon por farunofero; ĉion mi fordonas."],[21,24,"Sed la reĝo David diris al Ornan: Ne; mi volas aĉeti pro plena prezo; ĉar mi ne oferportos vian propraĵon al la Eternulo, kaj mi ne alportos bruloferon senpagan.","Sed la reĝo David diris al Ornan: Ne; mi volas aĉeti pro plena prezo; ĉar mi ne oferportos vian propraĵon al la Eternulo, kaj mi ne alportos bruloferon senpagan."],[21,25,"Kaj David donis al Ornan pro la loko sescent siklojn da oro.","Kaj David donis al Ornan pro la loko sescent siklojn da oro."],[21,26,"Kaj David konstruis tie altaron al la Eternulo, kaj alportis bruloferojn kaj pacoferojn, kaj ekvokis al la Eternulo; kaj Li respondis al li per fajro el la ĉielo sur la altaron de la brulofero.","Kaj David konstruis tie altaron al la Eternulo, kaj alportis bruloferojn kaj pacoferojn, kaj ekvokis al la Eternulo; kaj Li respondis al li per fajro el la ĉielo sur la altaron de la brulofero."],[21,27,"Kaj la Eternulo ordonis al la anĝelo, ke li remetu sian glavon en ĝian ingon.","Kaj la Eternulo ordonis al la anĝelo, ke li remetu sian glavon en ĝian ingon."],[21,28,"En tiu tempo, vidante, ke la Eternulo respondis al li sur la draŝejo de Ornan, la Jebusido, David alportis tie oferon.","En tiu tempo, vidante, ke la Eternulo respondis al li sur la draŝejo de Ornan, la Jebusido, David alportis tie oferon."],[21,29,"La tabernaklo de la Eternulo, kiun faris Moseo en la dezerto, kaj la altaro de bruloferoj, estis en tiu tempo sur altaĵo en Gibeon.","La tabernaklo de la Eternulo, kiun faris Moseo en la dezerto, kaj la altaro de bruloferoj, estis en tiu tempo sur altaĵo en Gibeon."],[21,30,"Sed David ne povis iri antaŭ ĝin por demandi Dion; ĉar lin timigis la glavo de la anĝelo de la Eternulo.","Sed David ne povis iri antaŭ ĝin por demandi Dion; ĉar lin timigis la glavo de la anĝelo de la Eternulo."],[22,1,"Kaj David diris: Ĉi tie estas la domo de Dio, la Eternulo, kaj ĉi tio estas altaro por bruloferoj por Izrael.","Kaj David diris: Ĉi tie estas la domo de Dio, la Eternulo, kaj ĉi tio estas altaro por bruloferoj por Izrael."],[22,2,"Kaj David ordonis kunvenigi la fremdulojn, kiuj estis en la lando de Izrael, kaj li starigis ŝtonhakistojn, por ĉirkaŭhaki ŝtonojn por la konstruado de la domo de Dio.","Kaj David ordonis kunvenigi la fremdulojn, kiuj estis en la lando de Izrael, kaj li starigis ŝtonhakistojn, por ĉirkaŭhaki ŝtonojn por la konstruado de la domo de Dio."],[22,3,"Kaj multe da fero por najloj al la pordoj de la pordegoj kaj por la krampoj pretigis David, ankaŭ multe da kupro, en nemezurita kvanto;","Kaj multe da fero por najloj al la pordoj de la pordegoj kaj por la krampoj pretigis David, ankaŭ multe da kupro, en nemezurita kvanto;"],[22,4,"kaj sennombran kvanton da cedra ligno, ĉar la Cidonanoj kaj Tiranoj alveturigis al David multe da cedra ligno.","kaj sennombran kvanton da cedra ligno, ĉar la Cidonanoj kaj Tiranoj alveturigis al David multe da cedra ligno."],[22,5,"Kaj David diris: Mia filo Salomono estas juna kaj neforta, kaj la domo, kiun oni devas konstrui por la Eternulo, devas esti granda, por ke Lia nomo kaj gloro estu konata en ĉiuj landoj. Tial mi preparados por li. Kaj David multe preparis antaŭ sia morto.","Kaj David diris: Mia filo Salomono estas juna kaj neforta, kaj la domo, kiun oni devas konstrui por la Eternulo, devas esti granda, por ke Lia nomo kaj gloro estu konata en ĉiuj landoj. Tial mi preparados por li. Kaj David multe preparis antaŭ sia morto."],[22,6,"Kaj li alvokis sian filon Salomono, kaj testamentis al li, ke li konstruu domon por la Eternulo, Dio de Izrael.","Kaj li alvokis sian filon Salomono, kaj testamentis al li, ke li konstruu domon por la Eternulo, Dio de Izrael."],[22,7,"Kaj David diris al Salomono: Mia filo, mi havis la intencon konstrui domon al la nomo de la Eternulo, mia Dio;","Kaj David diris al Salomono: Mia filo, mi havis la intencon konstrui domon al la nomo de la Eternulo, mia Dio;"],[22,8,"sed aperis pri mi vorto de la Eternulo, dirante: Multe da sango vi verŝis, kaj grandajn militojn vi faris, tial vi ne devas konstrui domon al Mia nomo; ĉar multe da sango vi verŝis antaŭ Mi sur la teron.","sed aperis pri mi vorto de la Eternulo, dirante: Multe da sango vi verŝis, kaj grandajn militojn vi faris, tial vi ne devas konstrui domon al Mia nomo; ĉar multe da sango vi verŝis antaŭ Mi sur la teron."],[22,9,"Jen filo naskiĝos al vi; li estos homo de paco, kaj Mi donos al li pacon en rilato al ĉiuj liaj malamikoj ĉirkaŭe; Salomono estos lia nomo, kaj pacon kaj trankvilecon Mi donos al Izrael en lia tempo.","Jen filo naskiĝos al vi; li estos homo de paco, kaj Mi donos al li pacon en rilato al ĉiuj liaj malamikoj ĉirkaŭe; Salomono estos lia nomo, kaj pacon kaj trankvilecon Mi donos al Izrael en lia tempo."],[22,10,"Li konstruos domon al Mia nomo; li estos al Mi filo, kaj Mi estos al li patro; kaj Mi fortikigos la tronon de lia reĝado super Izrael por ĉiam.","Li konstruos domon al Mia nomo; li estos al Mi filo, kaj Mi estos al li patro; kaj Mi fortikigos la tronon de lia reĝado super Izrael por ĉiam."],[22,11,"Nun, ho mia filo, la Eternulo estu kun vi, por ke vi sukcesu kaj konstruu la domon de la Eternulo, via Dio, kiel Li diris pri vi.","Nun, ho mia filo, la Eternulo estu kun vi, por ke vi sukcesu kaj konstruu la domon de la Eternulo, via Dio, kiel Li diris pri vi."],[22,12,"La Eternulo donu al vi saĝon kaj kompetentecon, kaj Li faru vin ordonanto super Izrael, por ke vi plenumadu la instruon de la Eternulo, via Dio.","La Eternulo donu al vi saĝon kaj kompetentecon, kaj Li faru vin ordonanto super Izrael, por ke vi plenumadu la instruon de la Eternulo, via Dio."],[22,13,"Tiam vi havos sukceson, se vi observos kaj plenumos la leĝojn kaj preskribojn, kiujn la Eternulo donis per Moseo al Izrael. Estu forta kaj kuraĝa; ne timu, kaj ne tremu.","Tiam vi havos sukceson, se vi observos kaj plenumos la leĝojn kaj preskribojn, kiujn la Eternulo donis per Moseo al Izrael. Estu forta kaj kuraĝa; ne timu, kaj ne tremu."],[22,14,"Jen mi en mia malriĉeco pretigis por la domo de la Eternulo cent mil kikarojn da oro, kaj milionon da kikaroj da arĝento, kaj kupron kaj feron en nekalkulebla kvanto, ĉar estas multe da ĝi; ankaŭ lignon kaj ŝtonojn mi pretigis; kaj vi povas aldoni al tio.","Jen mi en mia malriĉeco pretigis por la domo de la Eternulo cent mil kikarojn da oro, kaj milionon da kikaroj da arĝento, kaj kupron kaj feron en nekalkulebla kvanto, ĉar estas multe da ĝi; ankaŭ lignon kaj ŝtonojn mi pretigis; kaj vi povas aldoni al tio."],[22,15,"Vi havas multe da farontoj de la laboroj, masonistojn kaj ĉarpentistojn kaj kompetentulojn pri ĉiaj aferoj.","Vi havas multe da farontoj de la laboroj, masonistojn kaj ĉarpentistojn kaj kompetentulojn pri ĉiaj aferoj."],[22,16,"La oro, arĝento, kupro, kaj fero estas en nekalkulebla kvanto; leviĝu kaj faru, kaj la Eternulo estu kun vi.","La oro, arĝento, kupro, kaj fero estas en nekalkulebla kvanto; leviĝu kaj faru, kaj la Eternulo estu kun vi."],[22,17,"Kaj David ordonis al ĉiuj estroj de Izrael, ke ili helpu lian filon Salomono:","Kaj David ordonis al ĉiuj estroj de Izrael, ke ili helpu lian filon Salomono:"],[22,18,"La Eternulo, via Dio, estas ja kun vi, kaj Li donis al vi trankvilecon ĉiuflanke ĉirkaŭe; ĉar Li transdonis en miajn manojn la loĝantojn de la lando, kaj la lando humiliĝis antaŭ la Eternulo kaj antaŭ Lia popolo.","La Eternulo, via Dio, estas ja kun vi, kaj Li donis al vi trankvilecon ĉiuflanke ĉirkaŭe; ĉar Li transdonis en miajn manojn la loĝantojn de la lando, kaj la lando humiliĝis antaŭ la Eternulo kaj antaŭ Lia popolo."],[22,19,"Direktu do nun vian koron kaj vian animon, por turni vin al la Eternulo, via Dio. Leviĝu, kaj konstruu la sanktejon de la Eternulo Dio, por transporti la keston de interligo de la Eternulo kaj la sanktajn vazojn de Dio en la domon, kiu estos konstruita al la nomo de la Eternulo.","Direktu do nun vian koron kaj vian animon, por turni vin al la Eternulo, via Dio. Leviĝu, kaj konstruu la sanktejon de la Eternulo Dio, por transporti la keston de interligo de la Eternulo kaj la sanktajn vazojn de Dio en la domon, kiu estos konstruita al la nomo de la Eternulo."],[23,1,"David maljuniĝis kaj atingis sufiĉan aĝon; kaj li faris Salomonon, sian filon, reĝo super Izrael.","David maljuniĝis kaj atingis sufiĉan aĝon; kaj li faris Salomonon, sian filon, reĝo super Izrael."],[23,2,"Kaj li kunvenigis ĉiujn estrojn de Izrael kaj la pastrojn kaj la Levidojn.","Kaj li kunvenigis ĉiujn estrojn de Izrael kaj la pastrojn kaj la Levidojn."],[23,3,"Kaj estis kalkulitaj la Levidoj de la aĝo de tridek jaroj kaj pli; kaj montriĝis, ke ilia nombro, kalkulante ĉiujn kapojn de viroj, estis tridek ok mil.","Kaj estis kalkulitaj la Levidoj de la aĝo de tridek jaroj kaj pli; kaj montriĝis, ke ilia nombro, kalkulante ĉiujn kapojn de viroj, estis tridek ok mil."],[23,4,"El ili por administri la servadon de la domo de la Eternulo estis dudek kvar mil; da oficistoj kaj juĝistoj estis ses mil;","El ili por administri la servadon de la domo de la Eternulo estis dudek kvar mil; da oficistoj kaj juĝistoj estis ses mil;"],[23,5,"kvar mil pordegistoj, kaj kvar mil glorantoj de la Eternulo per instrumentoj, kiujn mi faris por glorado.","kvar mil pordegistoj, kaj kvar mil glorantoj de la Eternulo per instrumentoj, kiujn mi faris por glorado."],[23,6,"Kaj David dividis ilin en klasojn laŭ la filoj de Levi: Gerŝon, Kehat, kaj Merari.","Kaj David dividis ilin en klasojn laŭ la filoj de Levi: Gerŝon, Kehat, kaj Merari."],[23,7,"La Gerŝonidoj: Ladan kaj Ŝimei.","La Gerŝonidoj: Ladan kaj Ŝimei."],[23,8,"La filoj de Ladan: la ĉefo Jeĥiel, Zetam, kaj Joel — tri.","La filoj de Ladan: la ĉefo Jeĥiel, Zetam, kaj Joel — tri."],[23,9,"La filoj de Ŝimei: Ŝelomit, Ĥaziel, kaj Haran — tri. Tio estas la ĉefoj de patrodomoj de Ladan.","La filoj de Ŝimei: Ŝelomit, Ĥaziel, kaj Haran — tri. Tio estas la ĉefoj de patrodomoj de Ladan."],[23,10,"Kaj la filoj de Ŝimei: Jaĥat, Zina, Jeuŝ, kaj Beria. Tio estas la filoj de Ŝimei — kvar.","Kaj la filoj de Ŝimei: Jaĥat, Zina, Jeuŝ, kaj Beria. Tio estas la filoj de Ŝimei — kvar."],[23,11,"Jaĥat estis la ĉefo, Zina estis la dua; Jeuŝ kaj Beria havis nemulte da infanoj, tial ili ĉe la kalkulado prezentis unu patrodomon.","Jaĥat estis la ĉefo, Zina estis la dua; Jeuŝ kaj Beria havis nemulte da infanoj, tial ili ĉe la kalkulado prezentis unu patrodomon."],[23,12,"La filoj de Kehat: Amram, Jichar, Ĥebron, kaj Uziel — kvar.","La filoj de Kehat: Amram, Jichar, Ĥebron, kaj Uziel — kvar."],[23,13,"La filoj de Amram: Aaron kaj Moseo. Aaron estis apartigita kaj sanktigita por la plejsanktejo, li kaj liaj idoj por ĉiam, por incensadi antaŭ la Eternulo, por servadi al Li kaj por benadi en Lia nomo eterne.","La filoj de Amram: Aaron kaj Moseo. Aaron estis apartigita kaj sanktigita por la plejsanktejo, li kaj liaj idoj por ĉiam, por incensadi antaŭ la Eternulo, por servadi al Li kaj por benadi en Lia nomo eterne."],[23,14,"Moseo estis homo de Dio, kaj liaj idoj estis alkalkulitaj al la tribo de Levi.","Moseo estis homo de Dio, kaj liaj idoj estis alkalkulitaj al la tribo de Levi."],[23,15,"La filoj de Moseo: Gerŝom kaj Eliezer.","La filoj de Moseo: Gerŝom kaj Eliezer."],[23,16,"La filoj de Gerŝom: Ŝebuel estis la ĉefo.","La filoj de Gerŝom: Ŝebuel estis la ĉefo."],[23,17,"La filoj de Eliezer estis: Reĥabja, la unua; aliajn filojn Eliezer ne havis; sed Reĥabja havis tre multe da filoj.","La filoj de Eliezer estis: Reĥabja, la unua; aliajn filojn Eliezer ne havis; sed Reĥabja havis tre multe da filoj."],[23,18,"La filoj de Jichar: Ŝelomit, la unua.","La filoj de Jichar: Ŝelomit, la unua."],[23,19,"La filoj de Ĥebron: la unua estis Jerija, la dua estis Amarja, la tria estis Jaĥaziel, la kvara estis Jekameam.","La filoj de Ĥebron: la unua estis Jerija, la dua estis Amarja, la tria estis Jaĥaziel, la kvara estis Jekameam."],[23,20,"La filoj de Uziel: Miĥa, la unua, kaj Jiŝija, la dua.","La filoj de Uziel: Miĥa, la unua, kaj Jiŝija, la dua."],[23,21,"La filoj de Merari: Maĥli kaj Muŝi. La filoj de Maĥli: Eleazar kaj Kiŝ.","La filoj de Merari: Maĥli kaj Muŝi. La filoj de Maĥli: Eleazar kaj Kiŝ."],[23,22,"Eleazar mortis, kaj li ne havis filojn, sed nur filinojn; kaj ilin prenis al si la filoj de Kiŝ, iliaj kuzoj.","Eleazar mortis, kaj li ne havis filojn, sed nur filinojn; kaj ilin prenis al si la filoj de Kiŝ, iliaj kuzoj."],[23,23,"La filoj de Muŝi: Maĥli, Eder, kaj Jeremot — tri.","La filoj de Muŝi: Maĥli, Eder, kaj Jeremot — tri."],[23,24,"Tio estas la idoj de Levi laŭ iliaj patrodomoj, la ĉefoj de patrodomoj laŭ ilia kalkulo, laŭ ilia laŭnoma kaj laŭkapa nombro, kiuj faradis la laboron de servado en la domo de la Eternulo, komencante de la aĝo de dudek jaroj kaj plue.","Tio estas la idoj de Levi laŭ iliaj patrodomoj, la ĉefoj de patrodomoj laŭ ilia kalkulo, laŭ ilia laŭnoma kaj laŭkapa nombro, kiuj faradis la laboron de servado en la domo de la Eternulo, komencante de la aĝo de dudek jaroj kaj plue."],[23,25,"Ĉar David diris: La Eternulo, Dio de Izrael, donis ripozon al Sia popolo; kaj Li enloĝiĝis en Jerusalem por ĉiam.","Ĉar David diris: La Eternulo, Dio de Izrael, donis ripozon al Sia popolo; kaj Li enloĝiĝis en Jerusalem por ĉiam."],[23,26,"Kaj la Levidoj ne bezonis portadi la tabernaklon kaj ĉiujn ĝiajn vazojn por la servado en ĝi.","Kaj la Levidoj ne bezonis portadi la tabernaklon kaj ĉiujn ĝiajn vazojn por la servado en ĝi."],[23,27,"Laŭ la lastaj ordonoj de David estis kalkulitaj la Levidoj, havantaj la aĝon de dudek jaroj kaj pli.","Laŭ la lastaj ordonoj de David estis kalkulitaj la Levidoj, havantaj la aĝon de dudek jaroj kaj pli."],[23,28,"Ilia ofico estis helpi al la Aaronidoj ĉe la servado en la domo de la Eternulo, zorgi pri la kortoj, pri la ĉambroj, pri la pureco de ĉio sankta, kaj plenumi la laboron en la domo de Dio;","Ilia ofico estis helpi al la Aaronidoj ĉe la servado en la domo de la Eternulo, zorgi pri la kortoj, pri la ĉambroj, pri la pureco de ĉio sankta, kaj plenumi la laboron en la domo de Dio;"],[23,29,"zorgi pri la pano de propono, pri la faruno por farunoferoj, pri la macoj, pri la patoj, pri la rostado, kaj pri ĉia mezurado kaj pesado;","zorgi pri la pano de propono, pri la faruno por farunoferoj, pri la macoj, pri la patoj, pri la rostado, kaj pri ĉia mezurado kaj pesado;"],[23,30,"stari ĉiumatene, por kanti laŭdon kaj gloron al la Eternulo, tiel same ankaŭ vespere;","stari ĉiumatene, por kanti laŭdon kaj gloron al la Eternulo, tiel same ankaŭ vespere;"],[23,31,"fari ĉiujn bruloferojn al la Eternulo en la sabatoj, monatkomencoj, kaj festoj, laŭ ilia nombro, laŭ la preskribo pri ili, ĉiam antaŭ la Eternulo;","fari ĉiujn bruloferojn al la Eternulo en la sabatoj, monatkomencoj, kaj festoj, laŭ ilia nombro, laŭ la preskribo pri ili, ĉiam antaŭ la Eternulo;"],[23,32,"servi por deĵorado ĉe la tabernaklo de kunveno, ĉe la sanktaĵoj, kaj apud siaj fratoj la Aaronidoj ĉe la servado en la domo de la Eternulo.","servi por deĵorado ĉe la tabernaklo de kunveno, ĉe la sanktaĵoj, kaj apud siaj fratoj la Aaronidoj ĉe la servado en la domo de la Eternulo."],[24,1,"La ordo de la Aaronidoj: la filoj de Aaron: Nadab, Abihu, Eleazar, kaj Itamar.","La ordo de la Aaronidoj: la filoj de Aaron: Nadab, Abihu, Eleazar, kaj Itamar."],[24,2,"Nadab kaj Abihu mortis pli frue ol ilia patro, kaj filojn ili ne havis; kaj Eleazar kaj Itamar fariĝis pastroj.","Nadab kaj Abihu mortis pli frue ol ilia patro, kaj filojn ili ne havis; kaj Eleazar kaj Itamar fariĝis pastroj."],[24,3,"La ordon aranĝis David, kaj Cadok el la idoj de Eleazar, kaj Aĥimeleĥ el la idoj de Itamar, laŭ iliaj oficoj ĉe ilia servado.","La ordon aranĝis David, kaj Cadok el la idoj de Eleazar, kaj Aĥimeleĥ el la idoj de Itamar, laŭ iliaj oficoj ĉe ilia servado."],[24,4,"Montriĝis, ke inter la idoj de Eleazar estis pli granda nombro da viroj, ol inter la idoj de Itamar. Oni dividis ilin: por la idoj de Eleazar estis dek ses ĉefoj de patrodomoj, kaj por la idoj de Itamar ok patrodomoj.","Montriĝis, ke inter la idoj de Eleazar estis pli granda nombro da viroj, ol inter la idoj de Itamar. Oni dividis ilin: por la idoj de Eleazar estis dek ses ĉefoj de patrodomoj, kaj por la idoj de Itamar ok patrodomoj."],[24,5,"Oni dividis ilin per lotado, ambaŭ partojn paralele, ĉar la estroj de la sanktejo kaj la estroj en la aferoj de Dio estis el la idoj de Eleazar kaj el la idoj de Itamar.","Oni dividis ilin per lotado, ambaŭ partojn paralele, ĉar la estroj de la sanktejo kaj la estroj en la aferoj de Dio estis el la idoj de Eleazar kaj el la idoj de Itamar."],[24,6,"Kaj enskribis ilin Ŝemaja, filo de Netanel, skribisto el la Levidoj, antaŭ la reĝo kaj la estroj, antaŭ la pastro Cadok, antaŭ Aĥimeleĥ, filo de Ebjatar, kaj antaŭ la ĉefoj de patrodomoj de la pastroj kaj de la Levidoj; unu loto estis por patrodomo de Eleazaridoj, kaj unu loto estis por patrodomo de Itamaridoj.","Kaj enskribis ilin Ŝemaja, filo de Netanel, skribisto el la Levidoj, antaŭ la reĝo kaj la estroj, antaŭ la pastro Cadok, antaŭ Aĥimeleĥ, filo de Ebjatar, kaj antaŭ la ĉefoj de patrodomoj de la pastroj kaj de la Levidoj; unu loto estis por patrodomo de Eleazaridoj, kaj unu loto estis por patrodomo de Itamaridoj."],[24,7,"La unua loto eliris por Jehojarib, la dua por Jedaja,","La unua loto eliris por Jehojarib, la dua por Jedaja,"],[24,8,"la tria por Ĥarim, la kvara por Seorim,","la tria por Ĥarim, la kvara por Seorim,"],[24,9,"la kvina por Malkija, la sesa por Mijamin,","la kvina por Malkija, la sesa por Mijamin,"],[24,10,"la sepa por Hakoc, la oka por Abija,","la sepa por Hakoc, la oka por Abija,"],[24,11,"la naŭa por Jeŝua, la deka por Ŝeĥanja,","la naŭa por Jeŝua, la deka por Ŝeĥanja,"],[24,12,"la dek-unua por Eljaŝib, la dek-dua por Jakim,","la dek-unua por Eljaŝib, la dek-dua por Jakim,"],[24,13,"la dek-tria por Ĥupa, la dek-kvara por Jeŝebab,","la dek-tria por Ĥupa, la dek-kvara por Jeŝebab,"],[24,14,"la dek-kvina por Bilga, la dek-sesa por Imer,","la dek-kvina por Bilga, la dek-sesa por Imer,"],[24,15,"la dek-sepa por Ĥezir, la dek-oka por Hapicec,","la dek-sepa por Ĥezir, la dek-oka por Hapicec,"],[24,16,"la dek-naŭa por Petaĥja, la dudeka por Jeĥezkel,","la dek-naŭa por Petaĥja, la dudeka por Jeĥezkel,"],[24,17,"la dudek-unua por Jaĥin, la dudek-dua por Gamul,","la dudek-unua por Jaĥin, la dudek-dua por Gamul,"],[24,18,"la dudek-tria por Delaja, la dudek-kvara por Maazja.","la dudek-tria por Delaja, la dudek-kvara por Maazja."],[24,19,"Tio estis ilia ordo ĉe ilia servado, por iri en la domon de la Eternulo laŭ la preskribo donita per ilia patro Aaron, kiel ordonis al li la Eternulo, Dio de Izrael.","Tio estis ilia ordo ĉe ilia servado, por iri en la domon de la Eternulo laŭ la preskribo donita per ilia patro Aaron, kiel ordonis al li la Eternulo, Dio de Izrael."],[24,20,"La ordo por la ceteraj idoj de Levi: el la idoj de Amram: Ŝubael; el la idoj de Ŝubael: Jeĥdeja;","La ordo por la ceteraj idoj de Levi: el la idoj de Amram: Ŝubael; el la idoj de Ŝubael: Jeĥdeja;"],[24,21,"ĉe Reĥabja: el la idoj de Reĥabja la unua estis Jiŝija;","ĉe Reĥabja: el la idoj de Reĥabja la unua estis Jiŝija;"],[24,22,"ĉe la Jicharidoj: Ŝelomot; el la filoj de Ŝelomot: Jaĥat;","ĉe la Jicharidoj: Ŝelomot; el la filoj de Ŝelomot: Jaĥat;"],[24,23,"la filoj de Ĥebron: Jerija, Amarja estis la dua, Jaĥaziel la tria, Jekameam la kvara;","la filoj de Ĥebron: Jerija, Amarja estis la dua, Jaĥaziel la tria, Jekameam la kvara;"],[24,24,"el la filoj de Uziel: Miĥa; el la filoj de Miĥa: Ŝamir;","el la filoj de Uziel: Miĥa; el la filoj de Miĥa: Ŝamir;"],[24,25,"la frato de Miĥa estis Jiŝija; el la filoj de Jiŝija: Zeĥarja;","la frato de Miĥa estis Jiŝija; el la filoj de Jiŝija: Zeĥarja;"],[24,26,"el la filoj de Merari: Maĥli kaj Muŝi; el la filoj de Jaazija: Beno;","el la filoj de Merari: Maĥli kaj Muŝi; el la filoj de Jaazija: Beno;"],[24,27,"el la idoj de Merari: ĉe Jaazija: Beno, Ŝoham, Zakur, kaj Ibri;","el la idoj de Merari: ĉe Jaazija: Beno, Ŝoham, Zakur, kaj Ibri;"],[24,28,"ĉe Maĥli: Eleazar; li ne havis filojn;","ĉe Maĥli: Eleazar; li ne havis filojn;"],[24,29,"ĉe Kiŝ: el la filoj de Kiŝ: Jeraĥmeel;","ĉe Kiŝ: el la filoj de Kiŝ: Jeraĥmeel;"],[24,30,"la filoj de Muŝi: Maĥli, Eder, kaj Jerimot. Tio estas la Levidoj laŭ iliaj patrodomoj.","la filoj de Muŝi: Maĥli, Eder, kaj Jerimot. Tio estas la Levidoj laŭ iliaj patrodomoj."],[24,31,"Ili ankaŭ lotis samtempe kun siaj fratoj la Aaronidoj, antaŭ la reĝo David, Cadok, Aĥimeleĥ, kaj la ĉefoj de patrodomoj de la pastroj kaj de la Levidoj: ĉefo de patrodomo egale kun sia pli malgranda frato.","Ili ankaŭ lotis samtempe kun siaj fratoj la Aaronidoj, antaŭ la reĝo David, Cadok, Aĥimeleĥ, kaj la ĉefoj de patrodomoj de la pastroj kaj de la Levidoj: ĉefo de patrodomo egale kun sia pli malgranda frato."],[25,1,"David kaj la militestroj apartigis por la servado filojn de Asaf, de Heman, kaj de Jedutun, kiuj estis inspiritaj por harpoj, psalteroj, kaj cimbaloj. Ili estis kalkulitaj por sia servado:","David kaj la militestroj apartigis por la servado filojn de Asaf, de Heman, kaj de Jedutun, kiuj estis inspiritaj por harpoj, psalteroj, kaj cimbaloj. Ili estis kalkulitaj por sia servado:"],[25,2,"el la filoj de Asaf: Zakur, Jozef, Netanja, kaj Aŝarela, filoj de Asaf, sub gvidado de Asaf, kiu kantis ĉe la reĝo.","el la filoj de Asaf: Zakur, Jozef, Netanja, kaj Aŝarela, filoj de Asaf, sub gvidado de Asaf, kiu kantis ĉe la reĝo."],[25,3,"De Jedutun, la filoj de Jedutun: Gedalja, Ceri, Jeŝaja, Ĥaŝabja, kaj Matitja, ses, sub gvidado de sia patro Jedutun, kiu ludis inspirite sur harpo, por laŭdi kaj glori la Eternulon.","De Jedutun, la filoj de Jedutun: Gedalja, Ceri, Jeŝaja, Ĥaŝabja, kaj Matitja, ses, sub gvidado de sia patro Jedutun, kiu ludis inspirite sur harpo, por laŭdi kaj glori la Eternulon."],[25,4,"De Heman, la filoj de Heman: Bukija, Matanja, Uziel, Ŝebuel, Jerimot, Ĥananja, Ĥanani, Eliata, Gidalti, Romamti-Ezer, Joŝbekaŝa, Maloti, Hotir, kaj Maĥaziot.","De Heman, la filoj de Heman: Bukija, Matanja, Uziel, Ŝebuel, Jerimot, Ĥananja, Ĥanani, Eliata, Gidalti, Romamti-Ezer, Joŝbekaŝa, Maloti, Hotir, kaj Maĥaziot."],[25,5,"Ĉiuj ili estis filoj de Heman, viziisto de la reĝo koncerne la vortojn de Dio, por levi la kornon. Dio donis al Heman dek kvar filojn kaj tri filinojn.","Ĉiuj ili estis filoj de Heman, viziisto de la reĝo koncerne la vortojn de Dio, por levi la kornon. Dio donis al Heman dek kvar filojn kaj tri filinojn."],[25,6,"Ĉiuj ĉi tiuj estis sub la gvidado de siaj patroj ĉe la kantado en la domo de la Eternulo, kun cimbaloj, psalteroj, kaj harpoj, ĉe la servado en la domo de Dio, sub la gvidado de la reĝo, Asaf, Jedutun, kaj Heman.","Ĉiuj ĉi tiuj estis sub la gvidado de siaj patroj ĉe la kantado en la domo de la Eternulo, kun cimbaloj, psalteroj, kaj harpoj, ĉe la servado en la domo de Dio, sub la gvidado de la reĝo, Asaf, Jedutun, kaj Heman."],[25,7,"Ilia nombro, kune kun iliaj fratoj, instruitaj por kanti antaŭ la Eternulo, ĉiuj kompetentuloj, estis ducent okdek ok.","Ilia nombro, kune kun iliaj fratoj, instruitaj por kanti antaŭ la Eternulo, ĉiuj kompetentuloj, estis ducent okdek ok."],[25,8,"Ili lotis pri la vico de sia deĵorado, la malgrandaj egale kiel la grandaj, kompetentulo egale kiel lernanto.","Ili lotis pri la vico de sia deĵorado, la malgrandaj egale kiel la grandaj, kompetentulo egale kiel lernanto."],[25,9,"La unua loto eliris ĉe Asaf por Jozef; la dua por Gedalja; li kun siaj fratoj kaj siaj filoj estis dek du;","La unua loto eliris ĉe Asaf por Jozef; la dua por Gedalja; li kun siaj fratoj kaj siaj filoj estis dek du;"],[25,10,"la tria por Zakur; liaj filoj kaj fratoj estis dek du;","la tria por Zakur; liaj filoj kaj fratoj estis dek du;"],[25,11,"la kvara por Jicri; liaj filoj kaj fratoj estis dek du;","la kvara por Jicri; liaj filoj kaj fratoj estis dek du;"],[25,12,"la kvina por Netanja; liaj filoj kaj fratoj estis dek du;","la kvina por Netanja; liaj filoj kaj fratoj estis dek du;"],[25,13,"la sesa por Bukija; liaj filoj kaj fratoj estis dek du;","la sesa por Bukija; liaj filoj kaj fratoj estis dek du;"],[25,14,"la sepa por Jeŝarela; liaj filoj kaj fratoj estis dek du;","la sepa por Jeŝarela; liaj filoj kaj fratoj estis dek du;"],[25,15,"la oka por Jeŝaja; liaj filoj kaj fratoj estis dek du;","la oka por Jeŝaja; liaj filoj kaj fratoj estis dek du;"],[25,16,"la naŭa por Matanja; liaj filoj kaj fratoj estis dek du;","la naŭa por Matanja; liaj filoj kaj fratoj estis dek du;"],[25,17,"la deka por Ŝimei; liaj filoj kaj fratoj estis dek du;","la deka por Ŝimei; liaj filoj kaj fratoj estis dek du;"],[25,18,"la dek-unua por Azarel; liaj filoj kaj fratoj estis dek du;","la dek-unua por Azarel; liaj filoj kaj fratoj estis dek du;"],[25,19,"la dek-dua por Ĥaŝabja; liaj filoj kaj fratoj estis dek du;","la dek-dua por Ĥaŝabja; liaj filoj kaj fratoj estis dek du;"],[25,20,"la dek-tria por Ŝubael; liaj filoj kaj fratoj estis dek du;","la dek-tria por Ŝubael; liaj filoj kaj fratoj estis dek du;"],[25,21,"la dek-kvara por Matitja; liaj filoj kaj fratoj estis dek du;","la dek-kvara por Matitja; liaj filoj kaj fratoj estis dek du;"],[25,22,"la dek-kvina por Jeremot; liaj filoj kaj fratoj estis dek du;","la dek-kvina por Jeremot; liaj filoj kaj fratoj estis dek du;"],[25,23,"la dek-sesa por Ĥananja; liaj filoj kaj fratoj estis dek du;","la dek-sesa por Ĥananja; liaj filoj kaj fratoj estis dek du;"],[25,24,"la dek-sepa por Joŝbekaŝa; liaj filoj kaj fratoj estis dek du;","la dek-sepa por Joŝbekaŝa; liaj filoj kaj fratoj estis dek du;"],[25,25,"la dek-oka por Ĥanani; liaj filoj kaj fratoj estis dek du;","la dek-oka por Ĥanani; liaj filoj kaj fratoj estis dek du;"],[25,26,"la dek-naŭa por Maloti; liaj filoj kaj fratoj estis dek du;","la dek-naŭa por Maloti; liaj filoj kaj fratoj estis dek du;"],[25,27,"la dudeka por Eliata; liaj filoj kaj fratoj estis dek du;","la dudeka por Eliata; liaj filoj kaj fratoj estis dek du;"],[25,28,"la dudek-unua por Hotir; liaj filoj kaj fratoj estis dek du;","la dudek-unua por Hotir; liaj filoj kaj fratoj estis dek du;"],[25,29,"la dudek-dua por Gidalti; liaj filoj kaj fratoj estis dek du;","la dudek-dua por Gidalti; liaj filoj kaj fratoj estis dek du;"],[25,30,"la dudek-tria por Maĥaziot; liaj filoj kaj fratoj estis dek du;","la dudek-tria por Maĥaziot; liaj filoj kaj fratoj estis dek du;"],[25,31,"la dudek-kvara por Romamti-Ezer; liaj filoj kaj fratoj estis dek du.","la dudek-kvara por Romamti-Ezer; liaj filoj kaj fratoj estis dek du."],[26,1,"La klasoj de la pordegistoj: el la Koraĥidoj: Meŝelemja, filo de Kore, el la filoj de Asaf.","La klasoj de la pordegistoj: el la Koraĥidoj: Meŝelemja, filo de Kore, el la filoj de Asaf."],[26,2,"Meŝelemja havis filojn: la unuenaskito estis Zeĥarja, la dua estis Jediael, la tria estis Zebadja, la kvara estis Jatniel;","Meŝelemja havis filojn: la unuenaskito estis Zeĥarja, la dua estis Jediael, la tria estis Zebadja, la kvara estis Jatniel;"],[26,3,"la kvina estis Elam, la sesa estis Jehoĥanan, la sepa estis Eljehoenaj.","la kvina estis Elam, la sesa estis Jehoĥanan, la sepa estis Eljehoenaj."],[26,4,"Obed-Edom havis filojn: Ŝemaja estis la unuenaskito, Jehozabad la dua, Joaĥ la tria, Saĥar la kvara, Netanel la kvina,","Obed-Edom havis filojn: Ŝemaja estis la unuenaskito, Jehozabad la dua, Joaĥ la tria, Saĥar la kvara, Netanel la kvina,"],[26,5,"Amiel la sesa, Isaĥar la sepa, Peultaj la oka; ĉar benis lin Dio.","Amiel la sesa, Isaĥar la sepa, Peultaj la oka; ĉar benis lin Dio."],[26,6,"Al lia filo Ŝemaja naskiĝis filoj, kiuj regis en siaj patrodomoj, ĉar ili estis bravaj homoj.","Al lia filo Ŝemaja naskiĝis filoj, kiuj regis en siaj patrodomoj, ĉar ili estis bravaj homoj."],[26,7,"La filoj de Ŝemaja: Otni, Refael, Obed, Elzabad, liaj fratoj, bravaj homoj, Elihu kaj Semaĥja.","La filoj de Ŝemaja: Otni, Refael, Obed, Elzabad, liaj fratoj, bravaj homoj, Elihu kaj Semaĥja."],[26,8,"Ĉiuj ili estis el la idoj de Obed-Edom; ili kaj iliaj filoj kaj iliaj fratoj estis bravaj homoj, taŭgaj por servado: sesdek du ili estis ĉe Obed-Edom.","Ĉiuj ili estis el la idoj de Obed-Edom; ili kaj iliaj filoj kaj iliaj fratoj estis bravaj homoj, taŭgaj por servado: sesdek du ili estis ĉe Obed-Edom."],[26,9,"Meŝelemja havis filojn kaj fratojn, bravajn homojn dek ok.","Meŝelemja havis filojn kaj fratojn, bravajn homojn dek ok."],[26,10,"Ĥosa el la Merariidoj havis filojn: Ŝimri estis la ĉefo (kvankam li ne estis unuenaskito, tamen lia patro faris lin ĉefo),","Ĥosa el la Merariidoj havis filojn: Ŝimri estis la ĉefo (kvankam li ne estis unuenaskito, tamen lia patro faris lin ĉefo),"],[26,11,"Ĥilkija estis la dua, Tebalja la tria, Zeĥarja la kvara; ĉiuj filoj kaj fratoj de Ĥosa estis dek tri.","Ĥilkija estis la dua, Tebalja la tria, Zeĥarja la kvara; ĉiuj filoj kaj fratoj de Ĥosa estis dek tri."],[26,12,"Al tiuj grupoj da pordegistoj, al la ĉefoj de viroj, estis komisiita la servado en la domo de la Eternulo kune kun iliaj fratoj.","Al tiuj grupoj da pordegistoj, al la ĉefoj de viroj, estis komisiita la servado en la domo de la Eternulo kune kun iliaj fratoj."],[26,13,"Kaj ili lotis, kiel la malgrandaj, tiel ankaŭ la grandaj, laŭ siaj patrodomoj, por ĉiu pordego aparte.","Kaj ili lotis, kiel la malgrandaj, tiel ankaŭ la grandaj, laŭ siaj patrodomoj, por ĉiu pordego aparte."],[26,14,"Kaj la loto pri la oriento falis por Ŝelemja; kaj pri lia filo Zeĥarja, la saĝa konsilanto, oni lotis, kaj lia loto eliris por la nordo;","Kaj la loto pri la oriento falis por Ŝelemja; kaj pri lia filo Zeĥarja, la saĝa konsilanto, oni lotis, kaj lia loto eliris por la nordo;"],[26,15,"pri Obed-Edom por la sudo, kaj pri liaj filoj por la provizejo;","pri Obed-Edom por la sudo, kaj pri liaj filoj por la provizejo;"],[26,16,"pri Ŝupim kaj Ĥosa por la okcidento, por la Pordego Ŝaleĥet, kie la vojo leviĝas, kie gardo staras apud gardo.","pri Ŝupim kaj Ĥosa por la okcidento, por la Pordego Ŝaleĥet, kie la vojo leviĝas, kie gardo staras apud gardo."],[26,17,"Oriente estis ses Levidoj, norde kvar ĉiutage, sude kvar ĉiutage, kaj ĉe la provizejoj po du.","Oriente estis ses Levidoj, norde kvar ĉiutage, sude kvar ĉiutage, kaj ĉe la provizejoj po du."],[26,18,"Ĉe la alirejo okcidente estis: kvar ĉe la vojo, kaj du ĉe la alirejo.","Ĉe la alirejo okcidente estis: kvar ĉe la vojo, kaj du ĉe la alirejo."],[26,19,"Tio estis la grupoj da pordegistoj el la Koraĥidoj kaj el la Merariidoj.","Tio estis la grupoj da pordegistoj el la Koraĥidoj kaj el la Merariidoj."],[26,20,"El la Levidoj, Aĥija estis super la trezoroj de la domo de Dio kaj super la trezoroj de la sanktaĵoj.","El la Levidoj, Aĥija estis super la trezoroj de la domo de Dio kaj super la trezoroj de la sanktaĵoj."],[26,21,"El la idoj de Ladan, idoj de la Gerŝonido Ladan, ĉefoj de patrodomoj de la Gerŝonido Ladan estis la Jeĥielidoj.","El la idoj de Ladan, idoj de la Gerŝonido Ladan, ĉefoj de patrodomoj de la Gerŝonido Ladan estis la Jeĥielidoj."],[26,22,"La Jeĥielidoj: Zetam, kaj Joel, lia frato, estis super la trezoroj de la domo de la Eternulo.","La Jeĥielidoj: Zetam, kaj Joel, lia frato, estis super la trezoroj de la domo de la Eternulo."],[26,23,"El la Amramidoj, Jicharidoj, Ĥebronidoj, kaj Uzielidoj,","El la Amramidoj, Jicharidoj, Ĥebronidoj, kaj Uzielidoj,"],[26,24,"Ŝebuel, ido de Gerŝom, filo de Moseo, estis estro super la trezoroj.","Ŝebuel, ido de Gerŝom, filo de Moseo, estis estro super la trezoroj."],[26,25,"Lia frato Eliezer havis filon Reĥabja; lia filo estis Jeŝaja, lia filo estis Joram, lia filo estis Ziĥri, kaj lia filo estis Ŝelomit.","Lia frato Eliezer havis filon Reĥabja; lia filo estis Jeŝaja, lia filo estis Joram, lia filo estis Ziĥri, kaj lia filo estis Ŝelomit."],[26,26,"Ĉi tiu Ŝelomit kaj liaj fratoj estis super ĉiuj trezoroj de la sanktaĵoj, kiujn sanktigis la reĝo David, la ĉefoj de patrodomoj, la milestroj, kaj la centestroj, kaj la militestroj.","Ĉi tiu Ŝelomit kaj liaj fratoj estis super ĉiuj trezoroj de la sanktaĵoj, kiujn sanktigis la reĝo David, la ĉefoj de patrodomoj, la milestroj, kaj la centestroj, kaj la militestroj."],[26,27,"El la militoj kaj el la militakiraĵoj ili konsekris partojn, por subteni la domon de la Eternulo.","El la militoj kaj el la militakiraĵoj ili konsekris partojn, por subteni la domon de la Eternulo."],[26,28,"Ankaŭ ĉio, kion sanktigis la antaŭvidisto Samuel, kaj Saul, filo de Kiŝ, kaj Abner, filo de Ner, kaj Joab, filo de Ceruja, ĉio sanktigita estis sub la gardado de Ŝelomit kaj liaj fratoj.","Ankaŭ ĉio, kion sanktigis la antaŭvidisto Samuel, kaj Saul, filo de Kiŝ, kaj Abner, filo de Ner, kaj Joab, filo de Ceruja, ĉio sanktigita estis sub la gardado de Ŝelomit kaj liaj fratoj."],[26,29,"El la Jicharidoj, Kenanja kaj liaj filoj estis por la aferoj eksteraj de Izrael, kiel inspektistoj kaj juĝistoj.","El la Jicharidoj, Kenanja kaj liaj filoj estis por la aferoj eksteraj de Izrael, kiel inspektistoj kaj juĝistoj."],[26,30,"El la Ĥebronidoj, Ĥaŝabja kaj liaj fratoj, bravaj homoj, mil sepcent, havis oficojn en Izrael transe de Jordan, okcidente, por ĉiuj aferoj koncernantaj la Eternulon kaj por la aferoj de la reĝo.","El la Ĥebronidoj, Ĥaŝabja kaj liaj fratoj, bravaj homoj, mil sepcent, havis oficojn en Izrael transe de Jordan, okcidente, por ĉiuj aferoj koncernantaj la Eternulon kaj por la aferoj de la reĝo."],[26,31,"El la Ĥebronidoj, Jerija estis ĉefo de la Ĥebronidoj en iliaj generacioj kaj patrodomoj. En la kvardeka jaro de la reĝado de David ili estis esploritaj, kaj oni trovis ĉe ili bravajn homojn en Jazer en Gilead.","El la Ĥebronidoj, Jerija estis ĉefo de la Ĥebronidoj en iliaj generacioj kaj patrodomoj. En la kvardeka jaro de la reĝado de David ili estis esploritaj, kaj oni trovis ĉe ili bravajn homojn en Jazer en Gilead."],[26,32,"Kaj liaj fratoj, bravaj homoj, du mil sepcent, ĉefoj de patrodomoj; al ili la reĝo David donis oficojn ĉe la Rubenidoj, la Gadidoj, kaj la duontribo de Manase, por ĉiuj aferoj de Dio kaj aferoj de la reĝo.","Kaj liaj fratoj, bravaj homoj, du mil sepcent, ĉefoj de patrodomoj; al ili la reĝo David donis oficojn ĉe la Rubenidoj, la Gadidoj, kaj la duontribo de Manase, por ĉiuj aferoj de Dio kaj aferoj de la reĝo."],[27,1,"La Izraelidoj havis laŭ sia nombro ĉefojn de patrodomoj, milestrojn, centestrojn, kaj siajn inspektistojn, kiuj servis al la reĝo pri ĉiuj aferoj de la apartaĵoj, interŝanĝante sin ĉiumonate, en ĉiuj monatoj de la jaro. Ĉiu apartaĵo konsistis el dudek kvar mil.","La Izraelidoj havis laŭ sia nombro ĉefojn de patrodomoj, milestrojn, centestrojn, kaj siajn inspektistojn, kiuj servis al la reĝo pri ĉiuj aferoj de la apartaĵoj, interŝanĝante sin ĉiumonate, en ĉiuj monatoj de la jaro. Ĉiu apartaĵo konsistis el dudek kvar mil."],[27,2,"Super la unua apartaĵo en la unua monato estis Jaŝobeam, filo de Zabdiel; en lia apartaĵo estis dudek kvar mil;","Super la unua apartaĵo en la unua monato estis Jaŝobeam, filo de Zabdiel; en lia apartaĵo estis dudek kvar mil;"],[27,3,"li estis el la idoj de Perec, la ĉefo de ĉiuj militestroj por la unua monato.","li estis el la idoj de Perec, la ĉefo de ĉiuj militestroj por la unua monato."],[27,4,"Super la apartaĵo de la dua monato estis Dodaj, la Aĥoĥido; en lia apartaĵo estis ankaŭ la princo Miklot; en lia apartaĵo estis dudek kvar mil.","Super la apartaĵo de la dua monato estis Dodaj, la Aĥoĥido; en lia apartaĵo estis ankaŭ la princo Miklot; en lia apartaĵo estis dudek kvar mil."],[27,5,"La tria militestro, por la tria monato, estis Benaja, filo de la pastro Jehojada; en lia apartaĵo estis dudek kvar mil.","La tria militestro, por la tria monato, estis Benaja, filo de la pastro Jehojada; en lia apartaĵo estis dudek kvar mil."],[27,6,"Ĉi tiu Benaja estis el la tridek herooj, kaj estro super ili; en lia apartaĵo estis lia filo Amizabad.","Ĉi tiu Benaja estis el la tridek herooj, kaj estro super ili; en lia apartaĵo estis lia filo Amizabad."],[27,7,"La kvara, por la kvara monato, estis Asahel, frato de Joab, kaj post li lia filo Zebadja; en lia apartaĵo estis dudek kvar mil.","La kvara, por la kvara monato, estis Asahel, frato de Joab, kaj post li lia filo Zebadja; en lia apartaĵo estis dudek kvar mil."],[27,8,"La kvina, por la kvina monato, estis la estro Ŝamhut, la Jizraĥido; en lia apartaĵo estis dudek kvar mil.","La kvina, por la kvina monato, estis la estro Ŝamhut, la Jizraĥido; en lia apartaĵo estis dudek kvar mil."],[27,9,"La sesa, por la sesa monato, estis Ira, filo de Ikeŝ, la Tekoaano; en lia apartaĵo estis dudek kvar mil.","La sesa, por la sesa monato, estis Ira, filo de Ikeŝ, la Tekoaano; en lia apartaĵo estis dudek kvar mil."],[27,10,"La sepa, por la sepa monato, estis Ĥelec, la Pelonano, el la Efraimidoj; en lia apartaĵo estis dudek kvar mil.","La sepa, por la sepa monato, estis Ĥelec, la Pelonano, el la Efraimidoj; en lia apartaĵo estis dudek kvar mil."],[27,11,"La oka, por la oka monato, estis Sibĥaj, la Ĥuŝaido, el la Zeraĥidoj; en lia apartaĵo estis dudek kvar mil.","La oka, por la oka monato, estis Sibĥaj, la Ĥuŝaido, el la Zeraĥidoj; en lia apartaĵo estis dudek kvar mil."],[27,12,"La naŭa, por la naŭa monato, estis Abiezer, la Anatotano, el la Benjamenidoj; en lia apartaĵo estis dudek kvar mil.","La naŭa, por la naŭa monato, estis Abiezer, la Anatotano, el la Benjamenidoj; en lia apartaĵo estis dudek kvar mil."],[27,13,"La deka, por la deka monato, estis Maharaj, la Netofaano, el la Zeraĥidoj; en lia apartaĵo estis dudek kvar mil.","La deka, por la deka monato, estis Maharaj, la Netofaano, el la Zeraĥidoj; en lia apartaĵo estis dudek kvar mil."],[27,14,"La dek-unua, por la dek-unua monato, estis Benaja, la Piratonano, el la Efraimidoj; en lia apartaĵo estis dudek kvar mil.","La dek-unua, por la dek-unua monato, estis Benaja, la Piratonano, el la Efraimidoj; en lia apartaĵo estis dudek kvar mil."],[27,15,"La dek-dua, por la dek-dua monato, estis Ĥeldaj, la Netofaano, el la Otnielidoj; en lia apartaĵo estis dudek kvar mil.","La dek-dua, por la dek-dua monato, estis Ĥeldaj, la Netofaano, el la Otnielidoj; en lia apartaĵo estis dudek kvar mil."],[27,16,"Kaj super la triboj de Izrael: la estro de la Rubenidoj estis Eliezer, filo de Ziĥri; de la Simeonidoj: Ŝefatja, filo de Maaĥa;","Kaj super la triboj de Izrael: la estro de la Rubenidoj estis Eliezer, filo de Ziĥri; de la Simeonidoj: Ŝefatja, filo de Maaĥa;"],[27,17,"de la Levidoj: Ĥaŝabja, filo de Kemuel; de la Aaronidoj: Cadok;","de la Levidoj: Ĥaŝabja, filo de Kemuel; de la Aaronidoj: Cadok;"],[27,18,"de la Jehudaidoj: Elihu, el la fratoj de David; de la Isaĥaridoj: Omri, filo de Miĥael;","de la Jehudaidoj: Elihu, el la fratoj de David; de la Isaĥaridoj: Omri, filo de Miĥael;"],[27,19,"de la Zebulunidoj: Jiŝmaja, filo de Obadja; de la Naftaliidoj: Jerimot, filo de Azriel;","de la Zebulunidoj: Jiŝmaja, filo de Obadja; de la Naftaliidoj: Jerimot, filo de Azriel;"],[27,20,"de la Efraimidoj: Hoŝea, filo de Azazja; de la duontribo de Manase: Joel, filo de Pedaja;","de la Efraimidoj: Hoŝea, filo de Azazja; de la duontribo de Manase: Joel, filo de Pedaja;"],[27,21,"de la duontribo de Manase en Gilead: Jido, filo de Zeĥarja; de la Benjamenidoj: Jaasiel, filo de Abner;","de la duontribo de Manase en Gilead: Jido, filo de Zeĥarja; de la Benjamenidoj: Jaasiel, filo de Abner;"],[27,22,"de la Danidoj: Azarel, filo de Jeroĥam. Tio estis la estroj de la triboj de Izrael.","de la Danidoj: Azarel, filo de Jeroĥam. Tio estis la estroj de la triboj de Izrael."],[27,23,"Sed David ne faris kalkulon de tiuj, kiuj havis la aĝon de malpli ol dudek jaroj; ĉar la Eternulo promesis multigi Izraelon simile al la steloj de la ĉielo.","Sed David ne faris kalkulon de tiuj, kiuj havis la aĝon de malpli ol dudek jaroj; ĉar la Eternulo promesis multigi Izraelon simile al la steloj de la ĉielo."],[27,24,"Joab, filo de Ceruja, komencis la kalkuladon, sed ne finis. Kaj pro tio estis kolero kontraŭ Izrael; kaj tiu kalkulado ne estas enportita en la kronikon pri la reĝo David.","Joab, filo de Ceruja, komencis la kalkuladon, sed ne finis. Kaj pro tio estis kolero kontraŭ Izrael; kaj tiu kalkulado ne estas enportita en la kronikon pri la reĝo David."],[27,25,"Super la trezoroj de la reĝo estis Azmavet, filo de Adiel; super la trezoroj sur la kampo, en la urboj, en la vilaĝoj, kaj en la turoj estis Jonatan, filo de Uzija.","Super la trezoroj de la reĝo estis Azmavet, filo de Adiel; super la trezoroj sur la kampo, en la urboj, en la vilaĝoj, kaj en la turoj estis Jonatan, filo de Uzija."],[27,26,"Super la plenumantoj de la laboroj sur la kampo, super la terkultivo, estis Ezri, filo de Kelub.","Super la plenumantoj de la laboroj sur la kampo, super la terkultivo, estis Ezri, filo de Kelub."],[27,27,"Super la vinberĝardenoj estis Ŝimei, la Ramaano; super la provizoj de vino en la vinberĝardenoj estis Zabdi, la Ŝefamano.","Super la vinberĝardenoj estis Ŝimei, la Ramaano; super la provizoj de vino en la vinberĝardenoj estis Zabdi, la Ŝefamano."],[27,28,"Super la olivarboj kaj super la sikomoroj, kiuj estis en la valo, estis Baal-Ĥanan, la Gederano; super la provizoj de oleo estis Joaŝ.","Super la olivarboj kaj super la sikomoroj, kiuj estis en la valo, estis Baal-Ĥanan, la Gederano; super la provizoj de oleo estis Joaŝ."],[27,29,"Super la bovoj, kiuj paŝtiĝis en Ŝaron, estis Ŝitraj, la Ŝaronano; super la bovoj en la valoj estis Ŝafat, filo de Adlaj.","Super la bovoj, kiuj paŝtiĝis en Ŝaron, estis Ŝitraj, la Ŝaronano; super la bovoj en la valoj estis Ŝafat, filo de Adlaj."],[27,30,"Super la kameloj estis Obil, la Iŝmaelido; super la azeninoj estis Jeĥdeja, la Meronotano.","Super la kameloj estis Obil, la Iŝmaelido; super la azeninoj estis Jeĥdeja, la Meronotano."],[27,31,"Super la ŝafoj estis Jaziz, la Hagarido. Ĉiuj ĉi tiuj estis estroj super la havaĵoj, kiujn posedis la reĝo David.","Super la ŝafoj estis Jaziz, la Hagarido. Ĉiuj ĉi tiuj estis estroj super la havaĵoj, kiujn posedis la reĝo David."],[27,32,"Jonatan, onklo de David, estis konsilisto; li estis homo kompetenta kaj klera; Jeĥiel, filo de Ĥaĥmoni, estis ĉe la filoj de la reĝo.","Jonatan, onklo de David, estis konsilisto; li estis homo kompetenta kaj klera; Jeĥiel, filo de Ĥaĥmoni, estis ĉe la filoj de la reĝo."],[27,33,"Aĥitofel estis konsilisto de la reĝo; Ĥuŝaj, la Arkano, estis amiko de la reĝo.","Aĥitofel estis konsilisto de la reĝo; Ĥuŝaj, la Arkano, estis amiko de la reĝo."],[27,34,"Post Aĥitofel estis Jehojada, filo de Benaja, kaj Ebjatar; la militestro de la reĝo estis Joab.","Post Aĥitofel estis Jehojada, filo de Benaja, kaj Ebjatar; la militestro de la reĝo estis Joab."],[28,1,"David kunvenigis en Jerusalemon ĉiujn estrojn de Izrael, la estrojn de la triboj, la estrojn de la apartaĵoj, kiuj servis al la reĝo, la milestrojn kaj centestrojn, la estrojn super ĉiuj havaĵoj kaj super la brutoj de la reĝo kaj de liaj filoj, ankaŭ la korteganojn, heroojn, kaj ĉiujn distingitojn.","David kunvenigis en Jerusalemon ĉiujn estrojn de Izrael, la estrojn de la triboj, la estrojn de la apartaĵoj, kiuj servis al la reĝo, la milestrojn kaj centestrojn, la estrojn super ĉiuj havaĵoj kaj super la brutoj de la reĝo kaj de liaj filoj, ankaŭ la korteganojn, heroojn, kaj ĉiujn distingitojn."],[28,2,"Kaj la reĝo David stariĝis sur siaj piedoj, kaj diris: Aŭskultu min, ho miaj fratoj kaj mia popolo! Mi intencis konstrui domon de ripozo por la kesto de interligo de la Eternulo kaj por piedbenketo por nia Dio, kaj mi preparis min, por konstrui.","Kaj la reĝo David stariĝis sur siaj piedoj, kaj diris: Aŭskultu min, ho miaj fratoj kaj mia popolo! Mi intencis konstrui domon de ripozo por la kesto de interligo de la Eternulo kaj por piedbenketo por nia Dio, kaj mi preparis min, por konstrui."],[28,3,"Sed Dio diris al mi: Ne konstruu domon al Mia nomo, ĉar vi estas homo de milito kaj vi verŝadis sangon.","Sed Dio diris al mi: Ne konstruu domon al Mia nomo, ĉar vi estas homo de milito kaj vi verŝadis sangon."],[28,4,"Tamen la Eternulo, Dio de Izrael, elektis min el la tuta domo de mia patro, por ke mi estu reĝo super Izrael por ĉiam; ĉar Jehudan Li elektis kiel reganton, kaj en la domo de Jehuda la domon de mia patro, kaj inter la filoj de mia patro Li favoris min, farante min reĝo super la tuta Izrael.","Tamen la Eternulo, Dio de Izrael, elektis min el la tuta domo de mia patro, por ke mi estu reĝo super Izrael por ĉiam; ĉar Jehudan Li elektis kiel reganton, kaj en la domo de Jehuda la domon de mia patro, kaj inter la filoj de mia patro Li favoris min, farante min reĝo super la tuta Izrael."],[28,5,"Kaj el ĉiuj miaj filoj — ĉar multe da filoj donis al mi la Eternulo — Li elektis mian filon Salomono, ke li sidu sur la trono de la reĝado de la Eternulo super Izrael.","Kaj el ĉiuj miaj filoj — ĉar multe da filoj donis al mi la Eternulo — Li elektis mian filon Salomono, ke li sidu sur la trono de la reĝado de la Eternulo super Izrael."],[28,6,"Kaj Li diris al mi: Via filo Salomono, li konstruos Mian domon kaj Miajn kortojn; ĉar Mi elektis lin al Mi kiel filon, kaj Mi estos al li patro.","Kaj Li diris al mi: Via filo Salomono, li konstruos Mian domon kaj Miajn kortojn; ĉar Mi elektis lin al Mi kiel filon, kaj Mi estos al li patro."],[28,7,"Kaj Mi fortikigos lian regnon por ĉiam, se li persistos en la plenumado de Miaj ordonoj kaj preskriboj kiel ĝis nun.","Kaj Mi fortikigos lian regnon por ĉiam, se li persistos en la plenumado de Miaj ordonoj kaj preskriboj kiel ĝis nun."],[28,8,"Kaj nun antaŭ la okuloj de la tuta Izrael, la komunumo de la Eternulo, kaj antaŭ la oreloj de nia Dio: observu kaj atentu ĉiujn ordonojn de la Eternulo, via Dio, por ke vi posedu ĉi tiun bonan landon kaj heredigu ĝin al viaj infanoj post vi eterne.","Kaj nun antaŭ la okuloj de la tuta Izrael, la komunumo de la Eternulo, kaj antaŭ la oreloj de nia Dio: observu kaj atentu ĉiujn ordonojn de la Eternulo, via Dio, por ke vi posedu ĉi tiun bonan landon kaj heredigu ĝin al viaj infanoj post vi eterne."],[28,9,"Kaj vi, mia filo Salomono, konu la Dion de via patro, kaj servu al Li el plena koro kaj kun animo sincera; ĉar ĉiujn korojn la Eternulo esploras, kaj ĉiujn pensojn kaj intencojn Li komprenas. Se vi serĉos Lin, vi Lin trovos; kaj se vi forlasos Lin, Li forpuŝos vin por ĉiam.","Kaj vi, mia filo Salomono, konu la Dion de via patro, kaj servu al Li el plena koro kaj kun animo sincera; ĉar ĉiujn korojn la Eternulo esploras, kaj ĉiujn pensojn kaj intencojn Li komprenas. Se vi serĉos Lin, vi Lin trovos; kaj se vi forlasos Lin, Li forpuŝos vin por ĉiam."],[28,10,"Vidu nun, kiam la Eternulo elektis vin, por konstrui domon por la sanktejo; estu forta, kaj agu.","Vidu nun, kiam la Eternulo elektis vin, por konstrui domon por la sanktejo; estu forta, kaj agu."],[28,11,"Kaj David donis al sia filo Salomono la desegnon de la portiko, de la domoj, provizejoj, supraj ĉambroj, internaj ĉambroj, kaj de la loko por la sankta kesto;","Kaj David donis al sia filo Salomono la desegnon de la portiko, de la domoj, provizejoj, supraj ĉambroj, internaj ĉambroj, kaj de la loko por la sankta kesto;"],[28,12,"kaj la desegnon de ĉio, kion li havis en sia animo koncerne la kortojn de la domo de la Eternulo kaj koncerne ĉiujn ĉambrojn ĉirkaŭe, koncerne la trezorojn de la domo de Dio kaj la trezorojn de la sanktaĵoj,","kaj la desegnon de ĉio, kion li havis en sia animo koncerne la kortojn de la domo de la Eternulo kaj koncerne ĉiujn ĉambrojn ĉirkaŭe, koncerne la trezorojn de la domo de Dio kaj la trezorojn de la sanktaĵoj,"],[28,13,"koncerne la ordojn de la pastroj kaj de la Levidoj, koncerne la tutan servadon en la domo de la Eternulo, kaj koncerne ĉiujn objektojn de servado en la domo de la Eternulo;","koncerne la ordojn de la pastroj kaj de la Levidoj, koncerne la tutan servadon en la domo de la Eternulo, kaj koncerne ĉiujn objektojn de servado en la domo de la Eternulo;"],[28,14,"ankaŭ la oron, laŭ la pezo de la oro por ĉiuj objektoj de servado, kaj la pezon de ĉiuj arĝentaj objektoj de servado;","ankaŭ la oron, laŭ la pezo de la oro por ĉiuj objektoj de servado, kaj la pezon de ĉiuj arĝentaj objektoj de servado;"],[28,15,"ankaŭ la pezon de la oraj kandelabroj kaj de iliaj oraj lucernoj, montrante aparte la pezon de ĉiu kandelabro kaj de ĝiaj lucernoj, kaj la pezon de la arĝentaj kandelabroj, de ĉiu kandelabro kaj de ĝiaj lucernoj, laŭ la destino de ĉiu kandelabro.","ankaŭ la pezon de la oraj kandelabroj kaj de iliaj oraj lucernoj, montrante aparte la pezon de ĉiu kandelabro kaj de ĝiaj lucernoj, kaj la pezon de la arĝentaj kandelabroj, de ĉiu kandelabro kaj de ĝiaj lucernoj, laŭ la destino de ĉiu kandelabro."],[28,16,"Li donis ankaŭ la pezon de la oro por la tabloj de propono, por ĉiu tablo aparte, kaj de la arĝento por la tabloj arĝentaj;","Li donis ankaŭ la pezon de la oro por la tabloj de propono, por ĉiu tablo aparte, kaj de la arĝento por la tabloj arĝentaj;"],[28,17,"ankaŭ por la forkoj, aspergaj kalikoj, tasoj el pura oro, oraj pelvoj, montrante la pezon por ĉiu pelvo aparte, kaj por la arĝentaj pelvoj, montrante la pezon de ĉiu pelvo;","ankaŭ por la forkoj, aspergaj kalikoj, tasoj el pura oro, oraj pelvoj, montrante la pezon por ĉiu pelvo aparte, kaj por la arĝentaj pelvoj, montrante la pezon de ĉiu pelvo;"],[28,18,"ankaŭ la pezon de la incensaltaro el refandita oro. Li donis ankaŭ desegnon de la ĉaro kun la oraj keruboj, kiuj etendas la flugilojn kaj ŝirmas la keston de interligo de la Eternulo.","ankaŭ la pezon de la incensaltaro el refandita oro. Li donis ankaŭ desegnon de la ĉaro kun la oraj keruboj, kiuj etendas la flugilojn kaj ŝirmas la keston de interligo de la Eternulo."],[28,19,"Ĉio ĉi tio, li diris, estas skribita al mi de la mano de la Eternulo; Li klarigis al mi ĉiujn detalojn de la desegno.","Ĉio ĉi tio, li diris, estas skribita al mi de la mano de la Eternulo; Li klarigis al mi ĉiujn detalojn de la desegno."],[28,20,"Kaj David diris al sia filo Salomono: Estu forta kaj kuraĝa, kaj agu; ne timu, kaj ne tremu; ĉar Dio la Eternulo, mia Dio, estas kun vi; Li ne deturnos Sin de vi kaj ne forlasos vin, ĝis vi finos la tutan aferon por la servado en la domo de la Eternulo.","Kaj David diris al sia filo Salomono: Estu forta kaj kuraĝa, kaj agu; ne timu, kaj ne tremu; ĉar Dio la Eternulo, mia Dio, estas kun vi; Li ne deturnos Sin de vi kaj ne forlasos vin, ĝis vi finos la tutan aferon por la servado en la domo de la Eternulo."],[28,21,"Kaj jen estas la ordoj de la pastroj kaj de la Levidoj por ĉia servado en la domo de Dio; ili estos kun vi por ĉiu faro, kun fervoro kaj lerteco en ĉiu laboro; kaj la estroj kaj la tuta popolo plenumos ĉiujn viajn vortojn.","Kaj jen estas la ordoj de la pastroj kaj de la Levidoj por ĉia servado en la domo de Dio; ili estos kun vi por ĉiu faro, kun fervoro kaj lerteco en ĉiu laboro; kaj la estroj kaj la tuta popolo plenumos ĉiujn viajn vortojn."],[29,1,"Kaj la reĝo David diris al la tuta komunumo: Mia filo Salomono, la sola, kiun elektis la Eternulo, estas juna kaj neforta, kaj la laboro estas granda; ĉar ne por homo estas la loĝejo, sed por Dio la Eternulo.","Kaj la reĝo David diris al la tuta komunumo: Mia filo Salomono, la sola, kiun elektis la Eternulo, estas juna kaj neforta, kaj la laboro estas granda; ĉar ne por homo estas la loĝejo, sed por Dio la Eternulo."],[29,2,"Mi preparis per mia tuta forto por la domo de mia Dio oron por la oraj objektoj, arĝenton por la arĝentaj, kupron por la kupraj, feron por la feraj, lignon por la lignaj, ŝtonojn oniksajn kaj ŝtonojn enkadrigitajn, ŝtonojn belajn kaj diverskolorajn, kaj ĉiaspecajn ŝtonojn multekostajn, kaj multe da ŝtonoj marmoraj.","Mi preparis per mia tuta forto por la domo de mia Dio oron por la oraj objektoj, arĝenton por la arĝentaj, kupron por la kupraj, feron por la feraj, lignon por la lignaj, ŝtonojn oniksajn kaj ŝtonojn enkadrigitajn, ŝtonojn belajn kaj diverskolorajn, kaj ĉiaspecajn ŝtonojn multekostajn, kaj multe da ŝtonoj marmoraj."],[29,3,"Krom tio, pro mia amo al la domo de mia Dio, mian propran trezoron de oro kaj arĝento, kiun mi havas, mi fordonas por la domo de mia Dio, krom tio, kion mi pretigis por la sankta domo:","Krom tio, pro mia amo al la domo de mia Dio, mian propran trezoron de oro kaj arĝento, kiun mi havas, mi fordonas por la domo de mia Dio, krom tio, kion mi pretigis por la sankta domo:"],[29,4,"tri mil kikarojn da oro, el la oro de Ofir, kaj sep mil kikarojn da arĝento refandita, por tegi la murojn de la domoj;","tri mil kikarojn da oro, el la oro de Ofir, kaj sep mil kikarojn da arĝento refandita, por tegi la murojn de la domoj;"],[29,5,"oron por la oraj objektoj, arĝenton por la arĝentaj, kaj por ĉiuj laborotaĵoj de la majstroj. Tamen kiu ankoraŭ deziras oferi hodiaŭ por la Eternulo?","oron por la oraj objektoj, arĝenton por la arĝentaj, kaj por ĉiuj laborotaĵoj de la majstroj. Tamen kiu ankoraŭ deziras oferi hodiaŭ por la Eternulo?"],[29,6,"Kaj oferis la ĉefoj de patrodomoj, la estroj de la triboj de Izrael, la milestroj kaj centestroj, kaj la estroj super la aferoj de la reĝo;","Kaj oferis la ĉefoj de patrodomoj, la estroj de la triboj de Izrael, la milestroj kaj centestroj, kaj la estroj super la aferoj de la reĝo;"],[29,7,"kaj ili donis por la bezonoj de la domo de Dio kvin mil kikarojn da oro kaj dek mil darkemonojn, kaj dek mil kikarojn da arĝento, kaj dek ok mil kikarojn da kupro, kaj cent mil kikarojn da fero.","kaj ili donis por la bezonoj de la domo de Dio kvin mil kikarojn da oro kaj dek mil darkemonojn, kaj dek mil kikarojn da arĝento, kaj dek ok mil kikarojn da kupro, kaj cent mil kikarojn da fero."],[29,8,"Kaj tiuj, ĉe kiuj troviĝis multekostaj ŝtonoj, donis ilin por la trezorejo de la domo de la Eternulo, en la manojn de Jeĥiel, la Gerŝonido.","Kaj tiuj, ĉe kiuj troviĝis multekostaj ŝtonoj, donis ilin por la trezorejo de la domo de la Eternulo, en la manojn de Jeĥiel, la Gerŝonido."],[29,9,"Kaj la popolo ĝojis pro tiu oferado, ĉar el plena koro ili oferis al la Eternulo; ankaŭ la reĝo David ĝojis tre forte.","Kaj la popolo ĝojis pro tiu oferado, ĉar el plena koro ili oferis al la Eternulo; ankaŭ la reĝo David ĝojis tre forte."],[29,10,"Kaj David benis la Eternulon antaŭ la okuloj de la tuta komunumo, kaj David diris: Estu benata, ho Eternulo, Dio de nia patro Izrael, eterne kaj eterne.","Kaj David benis la Eternulon antaŭ la okuloj de la tuta komunumo, kaj David diris: Estu benata, ho Eternulo, Dio de nia patro Izrael, eterne kaj eterne."],[29,11,"Al Vi, ho Eternulo, apartenas grandeco, potenco, majesto, venko, kaj gloro, ĉar ĉio en la ĉielo kaj sur la tero estas Via; al Vi, ho Eternulo, apartenas la reĝado, kaj Vi estas alte super ĉiuj estroj.","Al Vi, ho Eternulo, apartenas grandeco, potenco, majesto, venko, kaj gloro, ĉar ĉio en la ĉielo kaj sur la tero estas Via; al Vi, ho Eternulo, apartenas la reĝado, kaj Vi estas alte super ĉiuj estroj."],[29,12,"Riĉeco kaj honoro venas de Vi; Vi regas super ĉio; en Via mano estas forto kaj potenco; Via mano povas ĉion grandigi kaj fortikigi.","Riĉeco kaj honoro venas de Vi; Vi regas super ĉio; en Via mano estas forto kaj potenco; Via mano povas ĉion grandigi kaj fortikigi."],[29,13,"Kaj nun, ho nia Dio, ni dankas Vin, kaj ni gloras Vian majestan nomon.","Kaj nun, ho nia Dio, ni dankas Vin, kaj ni gloras Vian majestan nomon."],[29,14,"Ĉar kiu estas mi, kaj kio estas mia popolo, ke mi havis la forton, por oferi tiom? de Vi estas ĉio, kaj el Via mano ni donis al Vi.","Ĉar kiu estas mi, kaj kio estas mia popolo, ke mi havis la forton, por oferi tiom? de Vi estas ĉio, kaj el Via mano ni donis al Vi."],[29,15,"Pasloĝantoj kaj enmigrintoj ni estas apud Vi, kiel ĉiuj niaj patroj; kiel ombro estas niaj tagoj sur la tero, nenio fortika.","Pasloĝantoj kaj enmigrintoj ni estas apud Vi, kiel ĉiuj niaj patroj; kiel ombro estas niaj tagoj sur la tero, nenio fortika."],[29,16,"Ho Eternulo, nia Dio! ĉi tiu tuta abundaĵo, kiun ni preparis, por konstrui al Vi domon, al Via sankta nomo, estas el Via mano, al Vi ĉio apartenas.","Ho Eternulo, nia Dio! ĉi tiu tuta abundaĵo, kiun ni preparis, por konstrui al Vi domon, al Via sankta nomo, estas el Via mano, al Vi ĉio apartenas."],[29,17,"Mi scias, ho mia Dio, ke Vi esploras la koron kaj ke sincereco plaĉas al Vi; el sincera koro mi oferis ĉion ĉi tion; kaj nun mi vidas kun ĝojo Vian popolon, kiu troviĝas ĉi tie, ke ĝi oferas al Vi.","Mi scias, ho mia Dio, ke Vi esploras la koron kaj ke sincereco plaĉas al Vi; el sincera koro mi oferis ĉion ĉi tion; kaj nun mi vidas kun ĝojo Vian popolon, kiu troviĝas ĉi tie, ke ĝi oferas al Vi."],[29,18,"Ho Eternulo, Dio de niaj patroj Abraham, Isaak, kaj Izrael! konservu ĝin por ĉiam, ĉi tiun pensmanieron de la koro de Via popolo, kaj turnu ilian koron al Vi.","Ho Eternulo, Dio de niaj patroj Abraham, Isaak, kaj Izrael! konservu ĝin por ĉiam, ĉi tiun pensmanieron de la koro de Via popolo, kaj turnu ilian koron al Vi."],[29,19,"Kaj al mia filo Salomono donu koron perfektan, ke li observu Viajn ordonojn, Viajn preskribojn, kaj Viajn leĝojn, ke li ĉion plenumu, kaj ke li konstruu la konstruaĵon, por kiu mi faris la preparojn.","Kaj al mia filo Salomono donu koron perfektan, ke li observu Viajn ordonojn, Viajn preskribojn, kaj Viajn leĝojn, ke li ĉion plenumu, kaj ke li konstruu la konstruaĵon, por kiu mi faris la preparojn."],[29,20,"Kaj David diris al la tuta komunumo: Benu la Eternulon, vian Dion. Kaj la tuta komunumo benis la Eternulon, Dion de iliaj patroj; kaj ili kliniĝis kun adoro antaŭ la Eternulo kaj antaŭ la reĝo.","Kaj David diris al la tuta komunumo: Benu la Eternulon, vian Dion. Kaj la tuta komunumo benis la Eternulon, Dion de iliaj patroj; kaj ili kliniĝis kun adoro antaŭ la Eternulo kaj antaŭ la reĝo."],[29,21,"Kaj ili faris buĉoferojn al la Eternulo. Kaj en la sekvanta tago ili alportis bruloferojn al la Eternulo: mil bovojn, mil virŝafojn, mil ŝafidojn, kune kun iliaj verŝoferoj, kaj multe da oferoj por la tuta Izrael.","Kaj ili faris buĉoferojn al la Eternulo. Kaj en la sekvanta tago ili alportis bruloferojn al la Eternulo: mil bovojn, mil virŝafojn, mil ŝafidojn, kune kun iliaj verŝoferoj, kaj multe da oferoj por la tuta Izrael."],[29,22,"Kaj ili manĝis kaj trinkis antaŭ la Eternulo en tiu tago kun granda ĝojo. Kaj duafoje ili faris reĝo Salomonon, filon de David, kaj sanktoleis lin kiel reganton, kaj Cadokon kiel pastron.","Kaj ili manĝis kaj trinkis antaŭ la Eternulo en tiu tago kun granda ĝojo. Kaj duafoje ili faris reĝo Salomonon, filon de David, kaj sanktoleis lin kiel reganton, kaj Cadokon kiel pastron."],[29,23,"Kaj Salomono suriris sur la tronon de la Eternulo kiel reĝo anstataŭ sia patro David; kaj li havis sukceson, kaj la tuta Izrael obeadis lin.","Kaj Salomono suriris sur la tronon de la Eternulo kiel reĝo anstataŭ sia patro David; kaj li havis sukceson, kaj la tuta Izrael obeadis lin."],[29,24,"Kaj ĉiuj estroj kaj eminentuloj, kaj ankaŭ ĉiuj filoj de la reĝo David, submetis sin al la reĝo Salomono.","Kaj ĉiuj estroj kaj eminentuloj, kaj ankaŭ ĉiuj filoj de la reĝo David, submetis sin al la reĝo Salomono."],[29,25,"Kaj la Eternulo forte altigis Salomonon antaŭ la okuloj de la tuta Izrael, kaj metis sur lin reĝan majeston, kiu antaŭe estis sur neniu el la reĝoj de Izrael.","Kaj la Eternulo forte altigis Salomonon antaŭ la okuloj de la tuta Izrael, kaj metis sur lin reĝan majeston, kiu antaŭe estis sur neniu el la reĝoj de Izrael."],[29,26,"David, filo de Jiŝaj, estis reĝo super la tuta Izrael.","David, filo de Jiŝaj, estis reĝo super la tuta Izrael."],[29,27,"La tempo, dum kiu li reĝis super Izrael, estis kvardek jaroj: en Ĥebron li reĝis sep jarojn, kaj en Jerusalem li reĝis tridek tri jarojn.","La tempo, dum kiu li reĝis super Izrael, estis kvardek jaroj: en Ĥebron li reĝis sep jarojn, kaj en Jerusalem li reĝis tridek tri jarojn."],[29,28,"Kaj li mortis en bona maljuneco, sata de aĝo, riĉeco, kaj gloro; kaj anstataŭ li ekreĝis lia filo Salomono.","Kaj li mortis en bona maljuneco, sata de aĝo, riĉeco, kaj gloro; kaj anstataŭ li ekreĝis lia filo Salomono."],[29,29,"La historio de la reĝo David, la antaŭa kaj la posta, estas priskribita en la kroniko de la antaŭvidisto Samuel, en la kroniko de la profeto Natan, kaj en la kroniko de la viziisto Gad;","La historio de la reĝo David, la antaŭa kaj la posta, estas priskribita en la kroniko de la antaŭvidisto Samuel, en la kroniko de la profeto Natan, kaj en la kroniko de la viziisto Gad;"],[29,30,"lia tuta reĝado, lia potenco, kaj la tempo, kiun travivis li kaj Izrael kaj ĉiuj regnoj de la landoj.","lia tuta reĝado, lia potenco, kaj la tempo, kiun travivis li kaj Izrael kaj ĉiuj regnoj de la landoj."]]}};